import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

function url(p) {
  if (!p) return BASE_URL;
  if (/^https?:\/\//i.test(p)) return p;
  if (p.charAt(0) === '/') return BASE_URL + p;
  return BASE_URL + '/' + p;
}

function getHeader(res, name) {
  const headers = res && res.headers ? res.headers : {};
  const lower = name.toLowerCase();
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === lower) return headers[keys[i]];
  }
  return null;
}

function json(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function decodeHtml(s) {
  return String(s)
    .replace(/&#x([0-9a-fA-F]+);/g, function (_, h) { return String.fromCharCode(parseInt(h, 16)); })
    .replace(/&#(\d+);/g, function (_, d) { return String.fromCharCode(parseInt(d, 10)); })
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
}

function parseAttrs(tag) {
  const inner = String(tag).replace(/^<\s*[A-Za-z][A-Za-z0-9:-]*/, '').replace(/>\s*$/, '');
  const attrs = {};
  const re = /([A-Za-z_:][-A-Za-z0-9_:.]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>]+)))?/g;
  let m;
  while ((m = re.exec(inner)) !== null) {
    const name = m[1].toLowerCase();
    let value = '';
    if (m[2] !== undefined) value = m[2];
    else if (m[3] !== undefined) value = m[3];
    else if (m[4] !== undefined) value = m[4];
    attrs[name] = decodeHtml(value);
  }
  return attrs;
}

function findInputs(html) {
  const out = [];
  const re = /<input\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;
  let m;
  const s = String(html || '');
  while ((m = re.exec(s)) !== null) out.push(parseAttrs(m[0]));
  return out;
}

function findForms(html) {
  const out = [];
  const re = /<form\b(?:[^>"']|"[^"]*"|'[^']*')*>/gi;
  let m;
  const s = String(html || '');
  while ((m = re.exec(s)) !== null) out.push(parseAttrs(m[0]));
  return out;
}

function extractCsrf(html) {
  const inputs = findInputs(html);
  const csrfInputs = inputs.filter(function (a) { return (a.name || '').toLowerCase() === 'csrf'; });
  if (!csrfInputs.length) return null;
  const hidden = csrfInputs.filter(function (a) { return !a.type || a.type.toLowerCase() === 'hidden'; });
  const pool = hidden.length ? hidden : csrfInputs;
  const enabled = pool.filter(function (a) { return !Object.prototype.hasOwnProperty.call(a, 'disabled'); });
  const chosen = (enabled.length ? enabled : pool)[0];
  return chosen && chosen.value ? chosen.value : null;
}

function extractChallenge(html) {
  const forms = findForms(html);
  let action = null;
  for (let i = 0; i < forms.length; i++) {
    if (forms[i].action && forms[i].action.indexOf('/v2/challenges/') !== -1) {
      action = forms[i].action;
      break;
    }
  }
  if (!action) {
    for (let i = 0; i < forms.length; i++) {
      if (forms[i].action) {
        action = forms[i].action;
        break;
      }
    }
  }
  const inputs = findInputs(html);
  let challenge = null;
  for (let i = 0; i < inputs.length; i++) {
    if ((inputs[i].name || '').toLowerCase() === 'challenge') {
      challenge = inputs[i].value || null;
      break;
    }
  }
  return { action: action, challenge: challenge };
}

function rawRequest(method, path, body, csrf, extraHeaders) {
  const headers = Object.assign({}, extraHeaders || {});
  if (method !== 'GET') {
    headers['Content-Type'] = 'application/json';
    if (csrf) headers['X-CSRF-Token'] = csrf;
  }
  const payload = body == null ? null : JSON.stringify(body);
  return http.request(method, url(path), payload, { headers: headers, redirects: 0 });
}

function updateCsrf(state, res) {
  const b = json(res);
  if (b && b.csrf) state.csrf = b.csrf;
}

function finishLogin(res) {
  let finalRes = res;
  let body = json(res);
  if (res.status === 302) {
    const loc = getHeader(res, 'Location');
    if (loc) {
      finalRes = http.get(url(loc), { redirects: 0 });
      body = json(finalRes);
    }
  }
  const ok = (finalRes.status === 200 || finalRes.status === 201) && body && !!body.csrf;
  return { res: finalRes, body: body, ok: ok };
}

function renew(state) {
  const res = rawRequest('POST', '/v2/session/renew', {}, state.csrf, null);
  const b = json(res);
  if (res.status === 200 && b && b.csrf) {
    state.csrf = b.csrf;
    return true;
  }
  return false;
}

function recoverCart(state) {
  if (!state.cartId) return true;
  const res = rawRequest('POST', '/v2/carts/' + state.cartId + '/recover', {}, state.csrf, null);
  const b = json(res);
  if (b && b.csrf) state.csrf = b.csrf;
  const etag = getHeader(res, 'ETag');
  if (etag) state.cartEtag = etag;
  return res.status === 200 || res.status === 201 || res.status === 204;
}

function freshLogin(state, username) {
  const formRes = http.get(url('/v2/login-form'), { redirects: 0 });
  const csrf = extractCsrf(formRes.body);
  if (!csrf) return false;
  const loginRes = http.post(url('/v2/login'), JSON.stringify({ username: username, password: PASSWORD, csrf: csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  const fin = finishLogin(loginRes);
  if (fin.ok && fin.body && fin.body.csrf) {
    state.csrf = fin.body.csrf;
    return true;
  }
  return false;
}

function handle401(state, res, username) {
  const b = json(res);
  const err = b && b.error;
  if (err === 'expired') {
    const ok = renew(state) || freshLogin(state, username);
    if (ok && recoverCart(state)) return 'retry';
    return 'fail';
  }
  if (err === 'session') {
    if (freshLogin(state, username) && recoverCart(state)) return 'retry';
    return 'fail';
  }
  return 'denied';
}

function authRequest(state, username, method, path, body, extraHeaders) {
  let res = rawRequest(method, path, body, state.csrf, extraHeaders);
  if (res.status === 401) {
    const action = handle401(state, res, username);
    if (action === 'retry') res = rawRequest(method, path, body, state.csrf, extraHeaders);
  }
  updateCsrf(state, res);
  return res;
}

function extractProductFromPage(pb) {
  if (!pb) return null;
  if (pb.product) return pb.product;
  if (pb.data) {
    if (pb.data.product) return pb.data.product;
    if (pb.data.id && pb.data.variants) return pb.data;
    if (Array.isArray(pb.data.products) && pb.data.products.length) return pb.data.products[0];
  }
  if (Array.isArray(pb.products) && pb.products.length) return pb.products[0];
  if (pb.id && pb.variants) return pb;
  return null;
}

function getCatalog(state, username) {
  const res = authRequest(state, username, 'GET', '/v2/catalog', null, null);
  const b = json(res);
  const products = b && b.data && Array.isArray(b.data.products) ? b.data.products : null;
  if (res.status === 200 && products && products.length) return products;
  if (res.status === 200 || res.status === 404 || res.status === 405) {
    const out = [];
    let next = '/v2/catalog/page';
    for (let i = 0; i < 3 && next; i++) {
      const r = authRequest(state, username, 'GET', next, null, null);
      const pb = json(r);
      if (r.status !== 200 || !pb) break;
      const p = extractProductFromPage(pb);
      if (p) out.push(p);
      next = pb.next || (pb.data && pb.data.next) || null;
    }
    return out;
  }
  return [];
}

function pickProduct(list) {
  const products = Array.isArray(list) ? list : [];
  for (let i = 0; i < products.length; i++) {
    const variants = products[i].variants || [];
    for (let j = 0; j < variants.length; j++) {
      if (variants[j].in_stock) {
        return { product_id: products[i].id, variant_id: variants[j].id };
      }
    }
  }
  return null;
}

function doChallenge(state, username) {
  const formRes = authRequest(state, username, 'GET', '/v2/challenge-form', null, null);
  const ch = extractChallenge(formRes.body);
  if (!ch.action || !ch.challenge) return false;
  const postRes = authRequest(state, username, 'POST', ch.action, { challenge: ch.challenge }, null);
  if (postRes.status === 302) {
    const loc = getHeader(postRes, 'Location');
    if (!loc) return false;
    const r = http.get(url(loc), { redirects: 0 });
    const b = json(r);
    if (b && b.csrf) state.csrf = b.csrf;
    if (b && b.grant_id) {
      state.grantId = b.grant_id;
      return true;
    }
    return false;
  }
  const b = json(postRes);
  if (b && b.grant_id) {
    state.grantId = b.grant_id;
    if (b.csrf) state.csrf = b.csrf;
    return true;
  }
  return false;
}

function refreshCartEtag(state, username) {
  const r = authRequest(state, username, 'GET', '/v2/carts/' + state.cartId, null, null);
  const etag = getHeader(r, 'ETag');
  if (etag) state.cartEtag = etag;
  return r;
}

export default function () {
  const username = 'bench-' + (((__VU - 1) % 16) + 1);
  const state = { csrf: null, cartId: null, cartEtag: null, grantId: null };

  const formRes = http.get(url('/v2/login-form'), { redirects: 0 });
  const formCsrf = extractCsrf(formRes.body);
  check(formRes, { 'login form loaded': function (r) { return r.status === 200; } });
  check(formCsrf, { 'login csrf extracted': function (v) { return !!v; } });
  if (!formCsrf) return;

  const loginRes = http.post(url('/v2/login'), JSON.stringify({ username: username, password: PASSWORD, csrf: formCsrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });
  const login = finishLogin(loginRes);
  check(login.res, { 'login authorized': function () { return login.ok; } });
  if (!login.ok || !login.body || !login.body.csrf) return;
  state.csrf = login.body.csrf;

  const products = getCatalog(state, username);
  const pick = pickProduct(products);
  check(pick, { 'in-stock variant selected': function (v) { return !!v; } });
  if (!pick) return;

  const challengeOk = doChallenge(state, username);
  check(challengeOk, { 'challenge grant obtained': function (v) { return !!v; } });
  if (!challengeOk) return;

  const cartBody = { product_id: pick.product_id, variant_id: pick.variant_id };
  if (state.grantId) cartBody.grant_id = state.grantId;
  const cartRes = authRequest(state, username, 'POST', '/v2/carts', cartBody, null);
  state.grantId = null;
  const cart = json(cartRes);
  if (cartRes.status === 201 && cart && cart.id) {
    state.cartId = cart.id;
    const etag = getHeader(cartRes, 'ETag');
    if (etag) state.cartEtag = etag;
  }
  check(cartRes, { 'cart created': function (r) { return r.status === 201 && !!state.cartId; } });
  if (!state.cartId) return;

  const quantity = 1;
  if (!state.cartEtag) refreshCartEtag(state, username);
  let patchRes = authRequest(state, username, 'PATCH', '/v2/carts/' + state.cartId, { quantity: quantity }, state.cartEtag ? { 'If-Match': state.cartEtag } : null);
  if (patchRes.status === 412) {
    refreshCartEtag(state, username);
    patchRes = authRequest(state, username, 'PATCH', '/v2/carts/' + state.cartId, { quantity: quantity }, state.cartEtag ? { 'If-Match': state.cartEtag } : null);
  }
  const patchEtag = getHeader(patchRes, 'ETag');
  if (patchEtag) state.cartEtag = patchEtag;
  check(patchRes, { 'cart quantity patched': function (r) { return r.status >= 200 && r.status < 300; } });
  if (patchRes.status < 200 || patchRes.status >= 300) return;
  refreshCartEtag(state, username);

  const reservationRes = authRequest(state, username, 'POST', '/v2/reservations', { cart_id: state.cartId }, null);
  const reservationBody = json(reservationRes);
  let reservationId = null;
  const initialStatus = reservationBody && (reservationBody.status || (reservationBody.data && reservationBody.data.status));
  if (initialStatus === 'ready') {
    reservationId = reservationBody.reservation_id || (reservationBody.data && reservationBody.data.reservation_id) || null;
  } else if (reservationBody && reservationBody.status_url) {
    for (let i = 0; i < 5; i++) {
      sleep(0.05);
      const statusRes = authRequest(state, username, 'GET', reservationBody.status_url, null, null);
      if (statusRes.status === 401 || statusRes.status === 403 || statusRes.status >= 500) break;
      const statusBody = json(statusRes);
      const status = statusBody && (statusBody.status || (statusBody.data && statusBody.data.status));
      if (status === 'ready') {
        reservationId = statusBody.reservation_id || (statusBody.data && statusBody.data.reservation_id) || null;
        break;
      }
      if (status === 'failed') break;
    }
  }
  check(reservationId, { 'reservation ready': function (v) { return !!v; } });
  if (!reservationId) return;

  const idem = __VU + '-' + __ITER + '-' + Date.now() + '-' + Math.floor(Math.random() * 1000000000);
  const orderBody = { cart_id: state.cartId, reservation_id: reservationId };
  const orderHeaders = { 'Idempotency-Key': idem };
  if (state.cartEtag) orderHeaders['If-Match'] = state.cartEtag;
  const orderRes = authRequest(state, username, 'POST', '/v2/orders', orderBody, orderHeaders);
  const order = json(orderRes);
  const accepted = orderRes.status === 201 && order && order.accepted === true && !!order.id;
  check(orderRes, { 'order committed': function () { return accepted; } });
}

import http from 'k6/http';
import { check } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '2m',
    },
  },
};

function jsonBody(res) {
  try {
    return res.json();
  } catch (e) {
    try {
      return JSON.parse(res.body);
    } catch (e2) {
      return null;
    }
  }
}

function header(res, name) {
  const headers = res && res.headers ? res.headers : {};
  const wanted = String(name).toLowerCase();
  for (const key in headers) {
    if (String(key).toLowerCase() === wanted) {
      return headers[key];
    }
  }
  return null;
}

function resolveUrl(loc) {
  if (!loc) return null;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.charAt(0) === '/') return BASE + loc;
  if (loc.charAt(0) === '?') return BASE + '/v2/catalog/page' + loc;
  return BASE + '/' + loc;
}

function parseAttrs(tag) {
  const attrs = {};
  const attrRe = /([A-Za-z_:][-A-Za-z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/g;
  let match;
  while ((match = attrRe.exec(tag)) !== null) {
    const name = match[1].toLowerCase();
    const value = match[3] !== undefined ? match[3] : (match[4] !== undefined ? match[4] : match[5]);
    attrs[name] = value;
  }
  return attrs;
}

function extractInputValue(html, wanted) {
  if (!html) return null;
  const inputRe = /<input\b[^>]*>/gi;
  let match;
  while ((match = inputRe.exec(html)) !== null) {
    const attrs = parseAttrs(match[0]);
    if (attrs.name === wanted && attrs.value) {
      return attrs.value;
    }
  }
  return null;
}

function extractCsrf(html) {
  return extractInputValue(html, 'csrf');
}

function compareIds(a, b) {
  const sa = String(a);
  const sb = String(b);
  const na = Number(sa);
  const nb = Number(sb);
  const aNum = sa.trim() !== '' && !isNaN(na);
  const bNum = sb.trim() !== '' && !isNaN(nb);
  if (aNum && bNum) return na - nb;
  if (sa < sb) return -1;
  if (sa > sb) return 1;
  return 0;
}

function isInStock(variant) {
  return !!variant && (variant.in_stock === true || variant.in_stock === 1 || variant.in_stock === 'true');
}

function selectEligible(products) {
  if (!Array.isArray(products)) return null;
  const eligible = [];
  for (const product of products) {
    if (!product || !Array.isArray(product.variants)) continue;
    const inStock = product.variants.filter(isInStock);
    if (inStock.length > 0) {
      eligible.push({ product: product, variants: inStock });
    }
  }
  if (eligible.length === 0) return null;
  eligible.sort((a, b) => compareIds(a.product.id, b.product.id));
  const chosen = eligible[0];
  const variants = chosen.variants.slice().sort((a, b) => compareIds(a.id, b.id));
  return { product: chosen.product, variant: variants[0] };
}

function updateCsrf(state, res) {
  const body = jsonBody(res);
  if (body && body.csrf) {
    state.csrf = body.csrf;
  }
  return body;
}

function errorCode(res) {
  const body = jsonBody(res);
  return body && body.error ? body.error : null;
}

function authHeaders(csrf, extra) {
  const headers = {
    'Content-Type': 'application/json',
    'X-CSRF-Token': csrf,
  };
  if (extra) {
    for (const key in extra) {
      if (extra[key] !== undefined && extra[key] !== null) {
        headers[key] = extra[key];
      }
    }
  }
  return headers;
}

function login(username) {
  const form = http.get(BASE + '/v2/login-form', { redirects: 0 });
  const csrf = extractCsrf(form.body);
  const formOk = form.status === 200 && !!csrf;
  check(form, { 'login form ok': () => formOk });
  if (!formOk) return null;

  let res = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: username, password: PASSWORD, csrf: csrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  if (res.status === 302) {
    const location = header(res, 'Location');
    check(res, { 'login redirect location': () => !!location });
    if (location) {
      res = http.get(resolveUrl(location), { redirects: 0 });
    }
  }

  const body = jsonBody(res);
  const ok = (res.status === 200 || res.status === 201) && body && body.csrf;
  check(res, { 'login ok': () => ok });
  if (!ok) return null;
  return { csrf: body.csrf, user: body.user };
}

function recoverSession(state, code) {
  if (code !== 'expired' && code !== 'session') return false;

  const renewRes = http.post(
    BASE + '/v2/session/renew',
    JSON.stringify({}),
    { headers: authHeaders(state.csrf), redirects: 0 }
  );
  updateCsrf(state, renewRes);
  let ok = renewRes.status >= 200 && renewRes.status < 300;

  if (!ok && code === 'session') {
    const fresh = login(state.username);
    if (fresh && fresh.csrf) {
      state.csrf = fresh.csrf;
      ok = true;
    }
  }

  if (state.cartId) {
    const recoverRes = http.post(
      BASE + '/v2/carts/' + state.cartId + '/recover',
      JSON.stringify({}),
      { headers: authHeaders(state.csrf), redirects: 0 }
    );
    updateCsrf(state, recoverRes);
    if (!(recoverRes.status >= 200 && recoverRes.status < 300)) {
      ok = false;
    }
  }

  return ok;
}

function callWithRecovery(state, fn) {
  let res = fn();
  updateCsrf(state, res);

  if (res.status === 401) {
    const code = errorCode(res);
    if (code === 'denied') {
      check(res, { 'authorization not denied': () => false });
      return res;
    }
    if (recoverSession(state, code)) {
      res = fn();
      updateCsrf(state, res);
    }
  }

  return res;
}

function authGet(state, url) {
  return callWithRecovery(state, () => http.get(url, {
    headers: { 'X-CSRF-Token': state.csrf },
    redirects: 0,
  }));
}

function authPost(state, url, payload, extra) {
  return callWithRecovery(state, () => http.post(url, JSON.stringify(payload), {
    headers: authHeaders(state.csrf, extra),
    redirects: 0,
  }));
}

function authPatch(state, url, payload, extra) {
  return callWithRecovery(state, () => http.patch(url, JSON.stringify(payload), {
    headers: authHeaders(state.csrf, extra),
    redirects: 0,
  }));
}

function fetchProducts(state) {
  let res = authGet(state, BASE + '/v2/catalog');
  let body = jsonBody(res);
  let products = body && body.data && Array.isArray(body.data.products) ? body.data.products : null;
  if (products) {
    return { res: res, products: products };
  }

  products = [];
  let url = BASE + '/v2/catalog/page';
  let lastRes = res;
  for (let i = 0; i < 3 && url; i++) {
    lastRes = authGet(state, resolveUrl(url));
    body = jsonBody(lastRes);
    let product = null;
    if (body && body.data && body.data.product) {
      product = body.data.product;
    } else if (body && body.product) {
      product = body.product;
    } else if (body && body.data && Array.isArray(body.data.products)) {
      product = body.data.products[0];
    }
    if (product) {
      products.push(product);
    }
    url = body && body.next ? resolveUrl(body.next) : null;
  }
  return { res: lastRes, products: products };
}

function createCart(state, selection) {
  const payload = {
    product_id: selection.product.id,
    variant_id: selection.variant.id,
  };
  const res = authPost(state, BASE + '/v2/carts', payload);
  const body = jsonBody(res);
  const ok = res.status === 201 && body && body.id;
  check(res, { 'cart created': () => ok });
  if (ok) {
    state.cartId = body.id;
    state.etag = header(res, 'ETag');
    if (body.csrf) state.csrf = body.csrf;
    if (!state.etag) {
      const cart = authGet(state, BASE + '/v2/carts/' + state.cartId);
      const etag = header(cart, 'ETag');
      if (etag) state.etag = etag;
    }
  }
  return res;
}

function patchCart(state) {
  const url = BASE + '/v2/carts/' + state.cartId;
  let extra = {};
  if (state.etag) extra['If-Match'] = state.etag;

  let res = authPatch(state, url, { quantity: 1 }, extra);
  if (res.status === 412) {
    const cart = authGet(state, url);
    const etag = header(cart, 'ETag');
    if (etag) state.etag = etag;
    extra = {};
    if (state.etag) extra['If-Match'] = state.etag;
    res = authPatch(state, url, { quantity: 1 }, extra);
  }

  const ok = res.status >= 200 && res.status < 300;
  check(res, { 'cart patched': () => ok });

  const newEtag = header(res, 'ETag');
  if (newEtag) {
    state.etag = newEtag;
  } else if (ok) {
    const cart = authGet(state, url);
    const etag = header(cart, 'ETag');
    if (etag) state.etag = etag;
  }
  return res;
}

function placeOrder(state) {
  const payload = { cart_id: state.cartId };
  if (state.reservationId) payload.reservation_id = state.reservationId;

  const idempotencyKey = 'order-' + state.cartId;
  let extra = { 'Idempotency-Key': idempotencyKey };
  if (state.etag) extra['If-Match'] = state.etag;

  let res = authPost(state, BASE + '/v2/orders', payload, extra);
  if (res.status === 412) {
    const cart = authGet(state, BASE + '/v2/carts/' + state.cartId);
    const etag = header(cart, 'ETag');
    if (etag) state.etag = etag;
    extra = { 'Idempotency-Key': idempotencyKey };
    if (state.etag) extra['If-Match'] = state.etag;
    res = authPost(state, BASE + '/v2/orders', payload, extra);
  }

  const body = jsonBody(res);
  const ok = res.status === 201 && body && body.accepted === true;
  check(res, { 'order accepted': () => ok });
  return res;
}

export default function () {
  const username = 'bench-' + __VU;
  const state = {
    username: username,
    csrf: null,
    cartId: null,
    etag: null,
    reservationId: null,
  };

  const loginRes = login(username);
  if (!loginRes) return;
  state.csrf = loginRes.csrf;

  const catalog = fetchProducts(state);
  check(catalog.res, { 'catalog ok': (r) => r.status === 200 });

  const selection = selectEligible(catalog.products);
  if (!selection) {
    check(catalog.res, { 'eligible parent selected': () => false });
    return;
  }

  check(catalog.res, { 'eligible parent selected': () => true });
  check(selection, {
    'variant belongs to parent and is in stock': (s) => {
      return !!s && !!s.product && Array.isArray(s.product.variants) &&
        s.product.variants.some((v) => v && v.id === s.variant.id && isInStock(v));
    },
  });

  createCart(state, selection);
  if (!state.cartId) return;

  patchCart(state);
  placeOrder(state);
}

import os
import re
import json
import time
import uuid
import html
from urllib.parse import urlsplit, urljoin

from locust import HttpUser, task, between, LoadTestShape, StopUser

TARGET_USERS = 2
ITERATIONS = 2

_completed_users = 0
_user_seq = 0

ATTR_RE = re.compile(r'''([A-Za-z_:][-A-Za-z0-9_:.]*)(?:\s*=\s*("[^"]*"|'[^']*'|[^\s"'=<>`]+))?''')
INPUT_RE = re.compile(r'''<input\b(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
FORM_RE = re.compile(r'''<form\b(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
A_LINK_RE = re.compile(r'''<(?:a|link)\b(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
TAG_RE = re.compile(r'''<(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
SCRIPT_RE = re.compile(r'''<script\b(?:[^>"']|"[^"]*"|'[^']*')*>(.*?)</script>''', re.I | re.S)
NEXT_HREF_RE = re.compile(r'''href=["']([^"']*(?:/v2/catalog/page|cursor=)[^"']*)["']''', re.I)
PRODUCT_ID_RES = [
    re.compile(r'''data-product-id=["']([^"']+)''', re.I),
    re.compile(r'''product_id=["']([^"']+)''', re.I),
    re.compile(r'''data-product=["']([^"']+)''', re.I),
    re.compile(r'''id=["']product[-_]([^"']+)''', re.I),
]


def truthy_stock(value):
    if value is None:
        return False
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    s = str(value).strip().lower()
    if s in ("true", "1", "yes", "y", "in_stock", "in-stock", "available", "in stock"):
        return True
    return False


def parse_attrs(tag):
    attrs = {}
    for match in ATTR_RE.finditer(tag or ""):
        key = match.group(1).lower()
        value = match.group(2)
        if value is None:
            attrs[key] = "true"
            continue
        value = value.strip()
        if len(value) >= 2 and ((value[0] == '"' and value[-1] == '"') or (value[0] == "'" and value[-1] == "'")):
            value = value[1:-1]
        attrs[key] = html.unescape(value)
    return attrs


def extract_input_value(html_text, name):
    for match in INPUT_RE.finditer(html_text or ""):
        attrs = parse_attrs(match.group(0))
        if attrs.get("disabled") is not None:
            continue
        if attrs.get("name") == name and "value" in attrs:
            return attrs["value"]
    return None


def find_form_action(html_text, contains=None):
    first = None
    for match in FORM_RE.finditer(html_text or ""):
        attrs = parse_attrs(match.group(0))
        action = attrs.get("action")
        if not action:
            continue
        if first is None:
            first = action
        if contains is None or contains in action:
            return action
    return None if contains else first


def find_next_link(html_text):
    for match in A_LINK_RE.finditer(html_text or ""):
        attrs = parse_attrs(match.group(0))
        rel = attrs.get("rel", "").lower().split()
        cls = attrs.get("class", "").lower().split()
        aria = attrs.get("aria-label", "").lower()
        if "next" in rel or "next" in cls or "next" in aria or attrs.get("data-next"):
            href = attrs.get("href") or attrs.get("data-next")
            if href:
                return href
    match = NEXT_HREF_RE.search(html_text or "")
    if match:
        return html.unescape(match.group(1))
    return None


def find_product_and_next(obj):
    product = None
    next_url = None
    if isinstance(obj, list):
        if obj and isinstance(obj[0], dict):
            product = obj[0]
        return product, None
    if not isinstance(obj, dict):
        return None, None
    data = obj.get("data")
    candidates = []
    if isinstance(obj.get("product"), dict):
        candidates.append(obj["product"])
    if isinstance(data, dict):
        if isinstance(data.get("product"), dict):
            candidates.append(data["product"])
        products = data.get("products")
        if isinstance(products, list) and products and isinstance(products[0], dict):
            candidates.append(products[0])
        if "id" in data and "variants" in data:
            candidates.append(data)
    if "id" in obj and "variants" in obj:
        candidates.append(obj)
    if candidates:
        product = candidates[0]
    next_url = obj.get("next")
    if next_url is None and isinstance(data, dict):
        next_url = data.get("next")
    if isinstance(next_url, dict):
        next_url = next_url.get("url") or next_url.get("href")
    if next_url in ("", False):
        next_url = None
    if next_url is not None and not isinstance(next_url, str):
        next_url = None
    return product, next_url


def parse_catalog_html(body):
    for match in SCRIPT_RE.finditer(body or ""):
        txt = match.group(1).strip()
        if not txt:
            continue
        candidates = [txt]
        start = txt.find("{")
        end = txt.rfind("}")
        if start != -1 and end != -1 and end > start:
            candidates.append(txt[start:end + 1])
        for candidate in candidates:
            try:
                obj = json.loads(candidate)
            except Exception:
                continue
            product, next_url = find_product_and_next(obj)
            if product:
                return product, next_url

    product_id = None
    for pattern in PRODUCT_ID_RES:
        match = pattern.search(body or "")
        if match:
            product_id = html.unescape(match.group(1))
            break

    variants = []
    for match in TAG_RE.finditer(body or ""):
        tag = match.group(0)
        low = tag.lower()
        if "variant" not in low and "data-variant" not in low and "variant_id" not in low:
            continue
        attrs = parse_attrs(tag)
        vid = attrs.get("data-variant-id") or attrs.get("variant_id") or attrs.get("data-variant") or attrs.get("data-id") or attrs.get("id")
        if not vid:
            continue
        if not product_id:
            product_id = attrs.get("data-product-id") or attrs.get("product_id")
        stock = attrs.get("data-in-stock") or attrs.get("in_stock") or attrs.get("data-stock") or attrs.get("stock") or attrs.get("data-available") or attrs.get("available")
        if stock is None:
            cls = (attrs.get("class", "") + " " + attrs.get("id", "")).lower()
            if "out" in cls or "unavailable" in cls or "sold" in cls:
                stock = "false"
            elif "in-stock" in cls or "in_stock" in cls or "available" in cls:
                stock = "true"
        variants.append({"id": vid, "in_stock": truthy_stock(stock)})

    if not product_id:
        for match in TAG_RE.finditer(body or ""):
            attrs = parse_attrs(match.group(0))
            cls = attrs.get("class", "").lower()
            if "product" in cls and attrs.get("data-id"):
                product_id = attrs["data-id"]
                break

    next_url = find_next_link(body)
    if product_id and variants:
        return {"id": product_id, "variants": variants}, next_url
    return None, next_url


def parse_catalog_body(resp):
    body_text = resp.text or ""
    ctype = (resp.headers.get("Content-Type") or resp.headers.get("content-type") or "").lower()
    stripped = body_text.strip()
    if "json" in ctype or stripped.startswith("{") or stripped.startswith("["):
        try:
            obj = json.loads(body_text)
            return find_product_and_next(obj)
        except Exception:
            pass
    return parse_catalog_html(body_text)


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = between(0.05, 0.2)

    def on_start(self):
        global _user_seq
        _user_seq += 1
        self.username = "bench-%d" % (((_user_seq - 1) % 16) + 1)
        self.password = "bench"
        self.reset_state()

    def reset_state(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.reservation_id = None
        self.order_id = None
        self.grant_id = None
        self.idempotency_key = None

    def auth_headers(self):
        return {"X-CSRF-Token": self.csrf} if self.csrf else {}

    def json_body(self, resp):
        try:
            body = resp.json()
            return body if isinstance(body, (dict, list)) else {}
        except Exception:
            return {}

    def update_csrf(self, body):
        if not isinstance(body, dict):
            return
        csrf = body.get("csrf")
        data = body.get("data")
        if not csrf and isinstance(data, dict):
            csrf = data.get("csrf")
        if isinstance(csrf, str) and csrf:
            self.csrf = csrf

    def update_etag(self, resp):
        etag = resp.headers.get("ETag") or resp.headers.get("etag")
        if etag:
            self.etag = etag

    def error_from(self, resp):
        body = self.json_body(resp)
        err = None
        if isinstance(body, dict):
            err = body.get("error") or body.get("code")
            data = body.get("data")
            if not err and isinstance(data, dict):
                err = data.get("error") or data.get("code")
        return str(err).lower() if err else ""

    def safe_url(self, url, base="/"):
        if not url:
            return None
        url = str(url).strip()
        if url.startswith("/"):
            return url
        parts = urlsplit(url)
        host_parts = urlsplit(self.host)
        if parts.scheme in ("http", "https") and parts.netloc == host_parts.netloc:
            path = parts.path or "/"
            if parts.query:
                path += "?" + parts.query
            if parts.fragment:
                path += "#" + parts.fragment
            return path
        if not parts.scheme and not parts.netloc:
            return urljoin(base, url)
        return None

    def do_login(self):
        form = self.client.get("/v2/login-form", allow_redirects=False, catch_response=True, name="/v2/login-form")
        if form.status_code != 200:
            form.failure("login-form status %s" % form.status_code)
            return False
        csrf = extract_input_value(form.text, "csrf")
        if not csrf:
            form.failure("missing login csrf")
            return False
        self.csrf = csrf
        resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            headers=self.auth_headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        )
        if resp.status_code == 302:
            loc = resp.headers.get("Location") or resp.headers.get("location")
            loc = self.safe_url(loc, "/v2/") if loc else None
            if not loc:
                resp.failure("login 302 without safe Location")
                return False
            resp = self.client.get(loc, allow_redirects=False, catch_response=True, name="/v2/login-redirect")
            if resp.status_code != 200:
                resp.failure("login redirect status %s" % resp.status_code)
                return False
            body = self.json_body(resp)
            self.update_csrf(body)
            if not self.csrf:
                resp.failure("missing csrf after login redirect")
                return False
            return True
        if resp.status_code == 200:
            body = self.json_body(resp)
            self.update_csrf(body)
            if not self.csrf:
                resp.failure("missing csrf after login")
                return False
            return True
        resp.failure("login status %s" % resp.status_code)
        return False

    def handle_401(self, resp, cart_exists=True):
        err = self.error_from(resp)
        if err == "denied":
            resp.failure("denied")
            return False
        if err not in ("expired", "session"):
            resp.failure("401 %s" % (err or "unknown"))
            return False
        renew = self.client.post(
            "/v2/session/renew",
            json={},
            headers=self.auth_headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/session/renew",
        )
        if renew.status_code == 200:
            self.update_csrf(self.json_body(renew))
        else:
            rerr = self.error_from(renew)
            if rerr == "denied":
                renew.failure("renew denied")
                return False
            if not self.do_login():
                renew.failure("renew failed and fresh login failed")
                return False
        if cart_exists and self.cart_id:
            rec = self.client.post(
                "/v2/carts/%s/recover" % self.cart_id,
                json={},
                headers=self.auth_headers(),
                allow_redirects=False,
                catch_response=True,
                name="/v2/carts/{id}/recover",
            )
            if rec.status_code in (200, 201, 202, 204):
                self.update_csrf(self.json_body(rec))
                self.update_etag(rec)
                return True
            rec.failure("recover status %s" % rec.status_code)
            return False
        return True

    def request_with_recovery(self, method, url, name, cart_exists=True, json_payload=None, extra_headers=None, if_match=False):
        def build_headers():
            headers = self.auth_headers()
            if extra_headers:
                headers.update(extra_headers)
            if if_match and self.etag:
                headers["If-Match"] = self.etag
            return headers

        def send():
            headers = build_headers()
            if method == "GET":
                return self.client.get(url, headers=headers, allow_redirects=False, catch_response=True, name=name)
            if method == "POST":
                return self.client.post(url, json=json_payload, headers=headers, allow_redirects=False, catch_response=True, name=name)
            if method == "PATCH":
                return self.client.patch(url, json=json_payload, headers=headers, allow_redirects=False, catch_response=True, name=name)
            return self.client.request(method, url, json=json_payload, headers=headers, allow_redirects=False, catch_response=True, name=name)

        resp = send()
        if resp.status_code == 401:
            if self.handle_401(resp, cart_exists=cart_exists):
                resp = send()
                if resp.status_code == 401:
                    resp.failure("%s 401 after recovery" % name)
        return resp

    def select_item(self):
        url = "/v2/catalog/page"
        seen = set()
        last_resp = None
        for _ in range(3):
            resp = self.client.get(url, allow_redirects=False, catch_response=True, name="/v2/catalog/page")
            last_resp = resp
            if resp.status_code != 200:
                resp.failure("catalog status %s" % resp.status_code)
                return None
            product, next_url = parse_catalog_body(resp)
            if isinstance(product, dict):
                pid = product.get("id") or product.get("product_id")
                variants = product.get("variants") or []
                if isinstance(variants, dict):
                    variants = list(variants.values())
                for variant in variants:
                    if not isinstance(variant, dict):
                        continue
                    vid = variant.get("id") or variant.get("variant_id")
                    if vid and truthy_stock(variant.get("in_stock")):
                        if not pid:
                            resp.failure("eligible variant without product id")
                            return None
                        return pid, vid
            if not next_url:
                resp.failure("no eligible item and no next page")
                return None
            nxt = self.safe_url(next_url, "/v2/catalog/")
            if not nxt or not nxt.startswith("/v2/catalog/page"):
                resp.failure("invalid next cursor")
                return None
            if nxt in seen:
                resp.failure("repeated next cursor")
                return None
            seen.add(nxt)
            url = nxt
        if last_resp is not None:
            last_resp.failure("no eligible item in first 3 pages")
        return None

    def get_grant(self):
        form = self.client.get("/v2/challenge-form", allow_redirects=False, catch_response=True, name="/v2/challenge-form")
        if form.status_code != 200:
            form.failure("challenge-form status %s" % form.status_code)
            return None
        action = find_form_action(form.text, "/v2/challenges/")
        challenge = extract_input_value(form.text, "challenge")
        action = self.safe_url(action, "/v2/") if action else None
        if not action or not challenge:
            form.failure("missing challenge action or input")
            return None

        def send():
            return self.client.post(
                action,
                json={"challenge": challenge},
                headers=self.auth_headers(),
                allow_redirects=False,
                catch_response=True,
                name="/v2/challenges/{id}",
            )

        resp = send()
        if resp.status_code == 401:
            if self.handle_401(resp, cart_exists=False):
                resp = send()
                if resp.status_code == 401:
                    resp.failure("challenge 401 after recovery")
                    return None
            else:
                return None
        if resp.status_code == 302:
            loc = resp.headers.get("Location") or resp.headers.get("location")
            base = action if action.endswith("/") else action + "/"
            loc = self.safe_url(loc, base) if loc else None
            if not loc:
                resp.failure("challenge 302 without safe Location")
                return None
            resp = self.client.get(loc, allow_redirects=False, catch_response=True, name="/v2/challenges/result")
            if resp.status_code != 200:
                resp.failure("challenge result status %s" % resp.status_code)
                return None
            body = self.json_body(resp)
            self.update_csrf(body)
            grant = body.get("grant_id") if isinstance(body, dict) else None
            data = body.get("data") if isinstance(body, dict) else None
            if not grant and isinstance(data, dict):
                grant = data.get("grant_id")
            if not grant:
                resp.failure("missing grant_id")
                return None
            return grant
        if resp.status_code == 200:
            body = self.json_body(resp)
            self.update_csrf(body)
            grant = body.get("grant_id") if isinstance(body, dict) else None
            data = body.get("data") if isinstance(body, dict) else None
            if not grant and isinstance(data, dict):
                grant = data.get("grant_id")
            if not grant:
                resp.failure("missing grant_id")
                return None
            return grant
        resp.failure("challenge status %s" % resp.status_code)
        return None

    def create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        resp = self.request_with_recovery("POST", "/v2/carts", "/v2/carts", cart_exists=False, json_payload=payload)
        if resp.status_code != 201:
            resp.failure("cart status %s" % resp.status_code)
            return False
        body = self.json_body(resp)
        self.update_csrf(body)
        self.update_etag(resp)
        cart_id = body.get("id") if isinstance(body, dict) else None
        data = body.get("data") if isinstance(body, dict) else None
        if not cart_id and isinstance(data, dict):
            cart_id = data.get("id")
        if not cart_id:
            resp.failure("missing cart id")
            return False
        self.cart_id = cart_id
        self.idempotency_key = str(uuid.uuid4())
        return True

    def read_cart(self):
        if not self.cart_id:
            return False
        resp = self.client.get("/v2/carts/%s" % self.cart_id, allow_redirects=False, catch_response=True, name="/v2/carts/{id}")
        if resp.status_code == 401:
            if self.handle_401(resp, cart_exists=True):
                resp = self.client.get("/v2/carts/%s" % self.cart_id, allow_redirects=False, catch_response=True, name="/v2/carts/{id}")
                if resp.status_code == 401:
                    resp.failure("cart read 401 after recovery")
                    return False
            else:
                return False
        if resp.status_code != 200:
            resp.failure("cart read status %s" % resp.status_code)
            return False
        self.update_etag(resp)
        return True

    def update_cart(self):
        if not self.read_cart():
            return False
        payload = {"quantity": 1}
        resp = self.request_with_recovery("PATCH", "/v2/carts/%s" % self.cart_id, "/v2/carts/{id}", cart_exists=True, json_payload=payload, if_match=True)
        if resp.status_code == 412:
            if not self.read_cart():
                return False
            resp = self.request_with_recovery("PATCH", "/v2/carts/%s" % self.cart_id, "/v2/carts/{id}", cart_exists=True, json_payload=payload, if_match=True)
            if resp.status_code == 412:
                resp.failure("patch 412 after retry")
                return False
        if resp.status_code not in (200, 201, 204):
            resp.failure("patch status %s" % resp.status_code)
            return False
        self.update_csrf(self.json_body(resp))
        self.update_etag(resp)
        return True

    def create_reservation(self):
        resp = self.request_with_recovery("POST", "/v2/reservations", "/v2/reservations", cart_exists=True, json_payload={"cart_id": self.cart_id})
        if resp.status_code != 202:
            resp.failure("reservation status %s" % resp.status_code)
            return None
        body = self.json_body(resp)
        self.update_csrf(body)
        data = body.get("data") if isinstance(body, dict) else None
        status_url = body.get("status_url") if isinstance(body, dict) else None
        if not status_url and isinstance(data, dict):
            status_url = data.get("status_url")
        status_url = self.safe_url(status_url, "/v2/reservations/") if status_url else None
        if not status_url:
            resp.failure("missing status_url")
            return None
        last_poll = None
        for _ in range(5):
            time.sleep(0.05)
            poll = self.client.get(status_url, allow_redirects=False, catch_response=True, name="/v2/reservations/status")
            last_poll = poll
            if poll.status_code == 401:
                if self.handle_401(poll, cart_exists=True):
                    poll = self.client.get(status_url, allow_redirects=False, catch_response=True, name="/v2/reservations/status")
                    last_poll = poll
                    if poll.status_code == 401:
                        poll.failure("reservation poll 401 after recovery")
                        return None
                else:
                    return None
            if poll.status_code != 200:
                poll.failure("reservation poll status %s" % poll.status_code)
                return None
            pbody = self.json_body(poll)
            self.update_csrf(pbody)
            pdata = pbody.get("data") if isinstance(pbody, dict) else None
            if not isinstance(pdata, dict):
                pdata = pbody if isinstance(pbody, dict) else {}
            status = pdata.get("status") or (pbody.get("status") if isinstance(pbody, dict) else None)
            if status == "ready":
                rid = pdata.get("reservation_id") or (pbody.get("reservation_id") if isinstance(pbody, dict) else None)
                if not rid:
                    poll.failure("ready without reservation_id")
                    return None
                return rid
            if status == "failed":
                poll.failure("reservation failed")
                return None
        if last_poll is not None:
            last_poll.failure("reservation not ready after 5 polls")
        return None

    def place_order(self):
        if not self.idempotency_key:
            self.idempotency_key = str(uuid.uuid4())
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        extra = {"Idempotency-Key": self.idempotency_key}
        resp = self.request_with_recovery("POST", "/v2/orders", "/v2/orders", cart_exists=True, json_payload=payload, extra_headers=extra, if_match=True)
        if resp.status_code == 412:
            if not self.read_cart():
                return False
            resp = self.request_with_recovery("POST", "/v2/orders", "/v2/orders", cart_exists=True, json_payload=payload, extra_headers=extra, if_match=True)
            if resp.status_code == 412:
                resp.failure("order 412 after retry")
                return False
        body = self.json_body(resp)
        self.update_csrf(body)
        self.update_etag(resp)
        data = body.get("data") if isinstance(body, dict) else None
        if not isinstance(data, dict):
            data = {}
        accepted = body.get("accepted") if isinstance(body, dict) else None
        if accepted is None:
            accepted = data.get("accepted")
        order_id = body.get("id") if isinstance(body, dict) else None
        if not order_id:
            order_id = data.get("id")
        if resp.status_code == 200 and accepted is False:
            resp.failure("order business failure accepted=false")
            return False
        if resp.status_code != 201 or accepted is not True or not order_id:
            resp.failure("order status %s accepted=%s" % (resp.status_code, accepted))
            return False
        self.order_id = order_id
        return True

    def run_journey(self):
        self.reset_state()
        if not self.do_login():
            return False
        selected = self.select_item()
        if not selected:
            return False
        product_id, variant_id = selected
        grant_id = self.get_grant()
        if not grant_id:
            return False
        if not self.create_cart(product_id, variant_id, grant_id):
            return False
        if not self.update_cart():
            return False
        reservation_id = self.create_reservation()
        if not reservation_id:
            return False
        self.reservation_id = reservation_id
        return self.place_order()

    @task
    def journey(self):
        global _completed_users
        for _ in range(ITERATIONS):
            try:
                self.run_journey()
            except Exception:
                pass
        _completed_users += 1
        raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        if _completed_users >= TARGET_USERS:
            return None
        return {"user_count": max(0, TARGET_USERS - _completed_users), "spawn_rate": TARGET_USERS}

