import os
import re
import json
import time
import uuid
import html
from urllib.parse import urlsplit, urljoin

from locust import HttpUser, task, between, LoadTestShape
from locust.exception import StopUser

TARGET_USERS = 2
ITERATIONS = 2

_completed_users = 0
_user_seq = 0

ATTR_RE = re.compile(r'''([A-Za-z_:][-A-Za-z0-9_:.]*)(?:\s*=\s*("[^"]*"|'[^']*'|[^\s"'=<>`]+))?''')
INPUT_RE = re.compile(r'''<input\b(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
FORM_RE = re.compile(r'''<form\b(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
A_LINK_RE = re.compile(r'''<(?:a|link)\b(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
TAG_RE = re.compile(r'''<(?:[^>"']|"[^"]*"|'[^']*')*>''', re.I | re.S)
SCRIPT_RE = re.compile(r'''<script\b(?:[^>"']|"[^"]*"|'[^']*')*>(.*?)</script>''', re.I | re.S)
NEXT_HREF_RE = re.compile(r'''href=["']([^"']*(?:/v2/catalog/page|cursor=)[^"']*)["']''', re.I)
PRODUCT_ID_RES = [
    re.compile(r'''data-product-id=["']([^"']+)''', re.I),
    re.compile(r'''product_id=["']([^"']+)''', re.I),
    re.compile(r'''data-product=["']([^"']+)''', re.I),
    re.compile(r'''id=["']product[-_]([^"']+)''', re.I),
]


def truthy_stock(value):
    if value is None:
        return False
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    s = str(value).strip().lower()
    if s in ("true", "1", "yes", "y", "in_stock", "in-stock", "available", "in stock"):
        return True
    return False


def parse_attrs(tag):
    attrs = {}
    for match in ATTR_RE.finditer(tag or ""):
        key = match.group(1).lower()
        value = match.group(2)
        if value is None:
            attrs[key] = "true"
            continue
        value = value.strip()
        if len(value) >= 2 and ((value[0] == '"' and value[-1] == '"') or (value[0] == "'" and value[-1] == "'")):
            value = value[1:-1]
        attrs[key] = html.unescape(value)
    return attrs


def extract_input_value(html_text, name):
    for match in INPUT_RE.finditer(html_text or ""):
        attrs = parse_attrs(match.group(0))
        if attrs.get("disabled") is not None:
            continue
        if attrs.get("name") == name and "value" in attrs:
            return attrs["value"]
    return None


def find_form_action(html_text, contains=None):
    first = None
    for match in FORM_RE.finditer(html_text or ""):
        attrs = parse_attrs(match.group(0))
        action = attrs.get("action")
        if not action:
            continue
        if first is None:
            first = action
        if contains is None or contains in action:
            return action
    return None if contains else first


def find_next_link(html_text):
    for match in A_LINK_RE.finditer(html_text or ""):
        attrs = parse_attrs(match.group(0))
        rel = attrs.get("rel", "").lower().split()
        cls = attrs.get("class", "").lower().split()
        aria = attrs.get("aria-label", "").lower()
        if "next" in rel or "next" in cls or "next" in aria or attrs.get("data-next"):
            href = attrs.get("href") or attrs.get("data-next")
            if href:
                return href
    match = NEXT_HREF_RE.search(html_text or "")
    if match:
        return html.unescape(match.group(1))
    return None


def find_product_and_next(obj):
    product = None
    next_url = None
    if isinstance(obj, list):
        if obj and isinstance(obj[0], dict):
            product = obj[0]
        return product, None
    if not isinstance(obj, dict):
        return None, None
    data = obj.get("data")
    candidates = []
    if isinstance(obj.get("product"), dict):
        candidates.append(obj["product"])
    if isinstance(data, dict):
        if isinstance(data.get("product"), dict):
            candidates.append(data["product"])
        products = data.get("products")
        if isinstance(products, list) and products and isinstance(products[0], dict):
            candidates.append(products[0])
        if "id" in data and "variants" in data:
            candidates.append(data)
    if "id" in obj and "variants" in obj:
        candidates.append(obj)
    if candidates:
        product = candidates[0]
    next_url = obj.get("next")
    if next_url is None and isinstance(data, dict):
        next_url = data.get("next")
    if isinstance(next_url, dict):
        next_url = next_url.get("url") or next_url.get("href")
    if next_url in ("", False):
        next_url = None
    if next_url is not None and not isinstance(next_url, str):
        next_url = None
    return product, next_url


def parse_catalog_html(body):
    for match in SCRIPT_RE.finditer(body or ""):
        txt = match.group(1).strip()
        if not txt:
            continue
        candidates = [txt]
        start = txt.find("{")
        end = txt.rfind("}")
        if start != -1 and end != -1 and end > start:
            candidates.append(txt[start:end + 1])
        for candidate in candidates:
            try:
                obj = json.loads(candidate)
            except Exception:
                continue
            product, next_url = find_product_and_next(obj)
            if product:
                return product, next_url

    product_id = None
    for pattern in PRODUCT_ID_RES:
        match = pattern.search(body or "")
        if match:
            product_id = html.unescape(match.group(1))
            break

    variants = []
    for match in TAG_RE.finditer(body or ""):
        tag = match.group(0)
        low = tag.lower()
        if "variant" not in low and "data-variant" not in low and "variant_id" not in low:
            continue
        attrs = parse_attrs(tag)
        vid = attrs.get("data-variant-id") or attrs.get("variant_id") or attrs.get("data-variant") or attrs.get("data-id") or attrs.get("id")
        if not vid:
            continue
        if not product_id:
            product_id = attrs.get("data-product-id") or attrs.get("product_id")
        stock = attrs.get("data-in-stock") or attrs.get("in_stock") or attrs.get("data-stock") or attrs.get("stock") or attrs.get("data-available") or attrs.get("available")
        if stock is None:
            cls = (attrs.get("class", "") + " " + attrs.get("id", "")).lower()
            if "out" in cls or "unavailable" in cls or "sold" in cls:
                stock = "false"
            elif "in-stock" in cls or "in_stock" in cls or "available" in cls:
                stock = "true"
        variants.append({"id": vid, "in_stock": truthy_stock(stock)})

    if not product_id:
        for match in TAG_RE.finditer(body or ""):
            attrs = parse_attrs(match.group(0))
            cls = attrs.get("class", "").lower()
            if "product" in cls and attrs.get("data-id"):
                product_id = attrs["data-id"]
                break

    next_url = find_next_link(body)
    if product_id and variants:
        return {"id": product_id, "variants": variants}, next_url
    return None, next_url


def parse_catalog_body(resp):
    body_text = resp.text or ""
    ctype = (resp.headers.get("Content-Type") or resp.headers.get("content-type") or "").lower()
    stripped = body_text.strip()
    if "json" in ctype or stripped.startswith("{") or stripped.startswith("["):
        try:
            obj = json.loads(body_text)
            return find_product_and_next(obj)
        except Exception:
            pass
    return parse_catalog_html(body_text)


class ShopUser(HttpUser):
    host = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
    wait_time = between(0.05, 0.2)

    def on_start(self):
        global _user_seq
        _user_seq += 1
        self.username = "bench-%d" % (((_user_seq - 1) % 16) + 1)
        self.password = "bench"
        self.reset_state()

    def reset_state(self):
        self.csrf = None
        self.cart_id = None
        self.etag = None
        self.reservation_id = None
        self.order_id = None
        self.grant_id = None
        self.idempotency_key = None

    def auth_headers(self):
        return {"X-CSRF-Token": self.csrf} if self.csrf else {}

    def json_body(self, resp):
        try:
            body = resp.json()
            return body if isinstance(body, (dict, list)) else {}
        except Exception:
            return {}

    def update_csrf(self, body):
        if not isinstance(body, dict):
            return
        csrf = body.get("csrf")
        data = body.get("data")
        if not csrf and isinstance(data, dict):
            csrf = data.get("csrf")
        if isinstance(csrf, str) and csrf:
            self.csrf = csrf

    def update_etag(self, resp):
        etag = resp.headers.get("ETag") or resp.headers.get("etag")
        if etag:
            self.etag = etag

    def error_from(self, resp):
        body = self.json_body(resp)
        err = None
        if isinstance(body, dict):
            err = body.get("error") or body.get("code")
            data = body.get("data")
            if not err and isinstance(data, dict):
                err = data.get("error") or data.get("code")
        return str(err).lower() if err else ""

    def safe_url(self, url, base="/"):
        if not url:
            return None
        url = str(url).strip()
        if url.startswith("/"):
            return url
        parts = urlsplit(url)
        host_parts = urlsplit(self.host)
        if parts.scheme in ("http", "https") and parts.netloc == host_parts.netloc:
            path = parts.path or "/"
            if parts.query:
                path += "?" + parts.query
            if parts.fragment:
                path += "#" + parts.fragment
            return path
        if not parts.scheme and not parts.netloc:
            return urljoin(base, url)
        return None

    def do_login(self):
        form = self.client.get("/v2/login-form", allow_redirects=False, catch_response=True, name="/v2/login-form")
        if form.status_code != 200:
            form.failure("login-form status %s" % form.status_code)
            return False
        csrf = extract_input_value(form.text, "csrf")
        if not csrf:
            form.failure("missing login csrf")
            return False
        self.csrf = csrf
        resp = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            headers=self.auth_headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        )
        if resp.status_code == 302:
            loc = resp.headers.get("Location") or resp.headers.get("location")
            loc = self.safe_url(loc, "/v2/") if loc else None
            if not loc:
                resp.failure("login 302 without safe Location")
                return False
            resp = self.client.get(loc, allow_redirects=False, catch_response=True, name="/v2/login-redirect")
            if resp.status_code != 200:
                resp.failure("login redirect status %s" % resp.status_code)
                return False
            body = self.json_body(resp)
            self.update_csrf(body)
            if not self.csrf:
                resp.failure("missing csrf after login redirect")
                return False
            return True
        if resp.status_code == 200:
            body = self.json_body(resp)
            self.update_csrf(body)
            if not self.csrf:
                resp.failure("missing csrf after login")
                return False
            return True
        resp.failure("login status %s" % resp.status_code)
        return False

    def handle_401(self, resp, cart_exists=True):
        err = self.error_from(resp)
        if err == "denied":
            resp.failure("denied")
            return False
        if err not in ("expired", "session"):
            resp.failure("401 %s" % (err or "unknown"))
            return False
        renew = self.client.post(
            "/v2/session/renew",
            json={},
            headers=self.auth_headers(),
            allow_redirects=False,
            catch_response=True,
            name="/v2/session/renew",
        )
        if renew.status_code == 200:
            self.update_csrf(self.json_body(renew))
        else:
            rerr = self.error_from(renew)
            if rerr == "denied":
                renew.failure("renew denied")
                return False
            if not self.do_login():
                renew.failure("renew failed and fresh login failed")
                return False
        if cart_exists and self.cart_id:
            rec = self.client.post(
                "/v2/carts/%s/recover" % self.cart_id,
                json={},
                headers=self.auth_headers(),
                allow_redirects=False,
                catch_response=True,
                name="/v2/carts/{id}/recover",
            )
            if rec.status_code in (200, 201, 202, 204):
                self.update_csrf(self.json_body(rec))
                self.update_etag(rec)
                return True
            rec.failure("recover status %s" % rec.status_code)
            return False
        return True

    def request_with_recovery(self, method, url, name, cart_exists=True, json_payload=None, extra_headers=None, if_match=False):
        def build_headers():
            headers = self.auth_headers()
            if extra_headers:
                headers.update(extra_headers)
            if if_match and self.etag:
                headers["If-Match"] = self.etag
            return headers

        def send():
            headers = build_headers()
            if method == "GET":
                return self.client.get(url, headers=headers, allow_redirects=False, catch_response=True, name=name)
            if method == "POST":
                return self.client.post(url, json=json_payload, headers=headers, allow_redirects=False, catch_response=True, name=name)
            if method == "PATCH":
                return self.client.patch(url, json=json_payload, headers=headers, allow_redirects=False, catch_response=True, name=name)
            return self.client.request(method, url, json=json_payload, headers=headers, allow_redirects=False, catch_response=True, name=name)

        resp = send()
        if resp.status_code == 401:
            if self.handle_401(resp, cart_exists=cart_exists):
                resp = send()
                if resp.status_code == 401:
                    resp.failure("%s 401 after recovery" % name)
        return resp

    def select_item(self):
        url = "/v2/catalog/page"
        seen = set()
        last_resp = None
        for _ in range(3):
            resp = self.client.get(url, allow_redirects=False, catch_response=True, name="/v2/catalog/page")
            last_resp = resp
            if resp.status_code != 200:
                resp.failure("catalog status %s" % resp.status_code)
                return None
            product, next_url = parse_catalog_body(resp)
            if isinstance(product, dict):
                pid = product.get("id") or product.get("product_id")
                variants = product.get("variants") or []
                if isinstance(variants, dict):
                    variants = list(variants.values())
                for variant in variants:
                    if not isinstance(variant, dict):
                        continue
                    vid = variant.get("id") or variant.get("variant_id")
                    if vid and truthy_stock(variant.get("in_stock")):
                        if not pid:
                            resp.failure("eligible variant without product id")
                            return None
                        return pid, vid
            if not next_url:
                resp.failure("no eligible item and no next page")
                return None
            nxt = self.safe_url(next_url, "/v2/catalog/")
            if not nxt or not nxt.startswith("/v2/catalog/page"):
                resp.failure("invalid next cursor")
                return None
            if nxt in seen:
                resp.failure("repeated next cursor")
                return None
            seen.add(nxt)
            url = nxt
        if last_resp is not None:
            last_resp.failure("no eligible item in first 3 pages")
        return None

    def get_grant(self):
        form = self.client.get("/v2/challenge-form", allow_redirects=False, catch_response=True, name="/v2/challenge-form")
        if form.status_code != 200:
            form.failure("challenge-form status %s" % form.status_code)
            return None
        action = find_form_action(form.text, "/v2/challenges/")
        challenge = extract_input_value(form.text, "challenge")
        action = self.safe_url(action, "/v2/") if action else None
        if not action or not challenge:
            form.failure("missing challenge action or input")
            return None

        def send():
            return self.client.post(
                action,
                json={"challenge": challenge},
                headers=self.auth_headers(),
                allow_redirects=False,
                catch_response=True,
                name="/v2/challenges/{id}",
            )

        resp = send()
        if resp.status_code == 401:
            if self.handle_401(resp, cart_exists=False):
                resp = send()
                if resp.status_code == 401:
                    resp.failure("challenge 401 after recovery")
                    return None
            else:
                return None
        if resp.status_code == 302:
            loc = resp.headers.get("Location") or resp.headers.get("location")
            base = action if action.endswith("/") else action + "/"
            loc = self.safe_url(loc, base) if loc else None
            if not loc:
                resp.failure("challenge 302 without safe Location")
                return None
            resp = self.client.get(loc, allow_redirects=False, catch_response=True, name="/v2/challenges/result")
            if resp.status_code != 200:
                resp.failure("challenge result status %s" % resp.status_code)
                return None
            body = self.json_body(resp)
            self.update_csrf(body)
            grant = body.get("grant_id") if isinstance(body, dict) else None
            data = body.get("data") if isinstance(body, dict) else None
            if not grant and isinstance(data, dict):
                grant = data.get("grant_id")
            if not grant:
                resp.failure("missing grant_id")
                return None
            return grant
        if resp.status_code == 200:
            body = self.json_body(resp)
            self.update_csrf(body)
            grant = body.get("grant_id") if isinstance(body, dict) else None
            data = body.get("data") if isinstance(body, dict) else None
            if not grant and isinstance(data, dict):
                grant = data.get("grant_id")
            if not grant:
                resp.failure("missing grant_id")
                return None
            return grant
        resp.failure("challenge status %s" % resp.status_code)
        return None

    def create_cart(self, product_id, variant_id, grant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        resp = self.request_with_recovery("POST", "/v2/carts", "/v2/carts", cart_exists=False, json_payload=payload)
        if resp.status_code != 201:
            resp.failure("cart status %s" % resp.status_code)
            return False
        body = self.json_body(resp)
        self.update_csrf(body)
        self.update_etag(resp)
        cart_id = body.get("id") if isinstance(body, dict) else None
        data = body.get("data") if isinstance(body, dict) else None
        if not cart_id and isinstance(data, dict):
            cart_id = data.get("id")
        if not cart_id:
            resp.failure("missing cart id")
            return False
        self.cart_id = cart_id
        self.idempotency_key = str(uuid.uuid4())
        return True

    def read_cart(self):
        if not self.cart_id:
            return False
        resp = self.client.get("/v2/carts/%s" % self.cart_id, allow_redirects=False, catch_response=True, name="/v2/carts/{id}")
        if resp.status_code == 401:
            if self.handle_401(resp, cart_exists=True):
                resp = self.client.get("/v2/carts/%s" % self.cart_id, allow_redirects=False, catch_response=True, name="/v2/carts/{id}")
                if resp.status_code == 401:
                    resp.failure("cart read 401 after recovery")
                    return False
            else:
                return False
        if resp.status_code != 200:
            resp.failure("cart read status %s" % resp.status_code)
            return False
        self.update_etag(resp)
        return True

    def update_cart(self):
        if not self.read_cart():
            return False
        payload = {"quantity": 1}
        resp = self.request_with_recovery("PATCH", "/v2/carts/%s" % self.cart_id, "/v2/carts/{id}", cart_exists=True, json_payload=payload, if_match=True)
        if resp.status_code == 412:
            if not self.read_cart():
                return False
            resp = self.request_with_recovery("PATCH", "/v2/carts/%s" % self.cart_id, "/v2/carts/{id}", cart_exists=True, json_payload=payload, if_match=True)
            if resp.status_code == 412:
                resp.failure("patch 412 after retry")
                return False
        if resp.status_code not in (200, 201, 204):
            resp.failure("patch status %s" % resp.status_code)
            return False
        self.update_csrf(self.json_body(resp))
        self.update_etag(resp)
        return True

    def create_reservation(self):
        resp = self.request_with_recovery("POST", "/v2/reservations", "/v2/reservations", cart_exists=True, json_payload={"cart_id": self.cart_id})
        if resp.status_code != 202:
            resp.failure("reservation status %s" % resp.status_code)
            return None
        body = self.json_body(resp)
        self.update_csrf(body)
        data = body.get("data") if isinstance(body, dict) else None
        status_url = body.get("status_url") if isinstance(body, dict) else None
        if not status_url and isinstance(data, dict):
            status_url = data.get("status_url")
        status_url = self.safe_url(status_url, "/v2/reservations/") if status_url else None
        if not status_url:
            resp.failure("missing status_url")
            return None
        last_poll = None
        for _ in range(5):
            time.sleep(0.05)
            poll = self.client.get(status_url, allow_redirects=False, catch_response=True, name="/v2/reservations/status")
            last_poll = poll
            if poll.status_code == 401:
                if self.handle_401(poll, cart_exists=True):
                    poll = self.client.get(status_url, allow_redirects=False, catch_response=True, name="/v2/reservations/status")
                    last_poll = poll
                    if poll.status_code == 401:
                        poll.failure("reservation poll 401 after recovery")
                        return None
                else:
                    return None
            if poll.status_code != 200:
                poll.failure("reservation poll status %s" % poll.status_code)
                return None
            pbody = self.json_body(poll)
            self.update_csrf(pbody)
            pdata = pbody.get("data") if isinstance(pbody, dict) else None
            if not isinstance(pdata, dict):
                pdata = pbody if isinstance(pbody, dict) else {}
            status = pdata.get("status") or (pbody.get("status") if isinstance(pbody, dict) else None)
            if status == "ready":
                rid = pdata.get("reservation_id") or (pbody.get("reservation_id") if isinstance(pbody, dict) else None)
                if not rid:
                    poll.failure("ready without reservation_id")
                    return None
                return rid
            if status == "failed":
                poll.failure("reservation failed")
                return None
        if last_poll is not None:
            last_poll.failure("reservation not ready after 5 polls")
        return None

    def place_order(self):
        if not self.idempotency_key:
            self.idempotency_key = str(uuid.uuid4())
        payload = {"cart_id": self.cart_id}
        if self.reservation_id:
            payload["reservation_id"] = self.reservation_id
        extra = {"Idempotency-Key": self.idempotency_key}
        resp = self.request_with_recovery("POST", "/v2/orders", "/v2/orders", cart_exists=True, json_payload=payload, extra_headers=extra, if_match=True)
        if resp.status_code == 412:
            if not self.read_cart():
                return False
            resp = self.request_with_recovery("POST", "/v2/orders", "/v2/orders", cart_exists=True, json_payload=payload, extra_headers=extra, if_match=True)
            if resp.status_code == 412:
                resp.failure("order 412 after retry")
                return False
        body = self.json_body(resp)
        self.update_csrf(body)
        self.update_etag(resp)
        data = body.get("data") if isinstance(body, dict) else None
        if not isinstance(data, dict):
            data = {}
        accepted = body.get("accepted") if isinstance(body, dict) else None
        if accepted is None:
            accepted = data.get("accepted")
        order_id = body.get("id") if isinstance(body, dict) else None
        if not order_id:
            order_id = data.get("id")
        if resp.status_code == 200 and accepted is False:
            resp.failure("order business failure accepted=false")
            return False
        if resp.status_code != 201 or accepted is not True or not order_id:
            resp.failure("order status %s accepted=%s" % (resp.status_code, accepted))
            return False
        self.order_id = order_id
        return True

    def run_journey(self):
        self.reset_state()
        if not self.do_login():
            return False
        selected = self.select_item()
        if not selected:
            return False
        product_id, variant_id = selected
        grant_id = self.get_grant()
        if not grant_id:
            return False
        if not self.create_cart(product_id, variant_id, grant_id):
            return False
        if not self.update_cart():
            return False
        reservation_id = self.create_reservation()
        if not reservation_id:
            return False
        self.reservation_id = reservation_id
        return self.place_order()

    @task
    def journey(self):
        global _completed_users
        for _ in range(ITERATIONS):
            try:
                self.run_journey()
            except Exception:
                pass
        _completed_users += 1
        raise StopUser()


class ShopShape(LoadTestShape):
    def tick(self):
        if _completed_users >= TARGET_USERS:
            return None
        return {"user_count": max(0, TARGET_USERS - _completed_users), "spawn_rate": TARGET_USERS}

import http from 'k6/http';
import { check, fail } from 'k6';

const BASE_URL = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const QUANTITY = Number(__ENV.QUANTITY || 2);
const USERNAME = `bench-${__VU}`;
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    etag: {
      executor: 'per-vu-iterations',
      vus: Number(__ENV.USERS || 2),
      iterations: Number(__ENV.ITERATIONS || 2),
      maxDuration: '2m',
    },
  },
};

function resolveUrl(loc, basePath) {
  if (!loc) return BASE_URL + (basePath || '/');
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.charAt(0) === '/') return BASE_URL + loc;
  const base = basePath || '/';
  const dir = base.endsWith('/') ? base : base.slice(0, base.lastIndexOf('/') + 1);
  return BASE_URL + dir + loc;
}

function url(path) {
  return resolveUrl(path, '/');
}

function header(res, name) {
  const wanted = name.toLowerCase();
  const headers = (res && res.headers) || {};
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === wanted) return headers[key];
  }
  return undefined;
}

function json(res) {
  try {
    return res.json();
  } catch (_) {
    return null;
  }
}

function extractCsrf(html) {
  const inputs = String(html || '').match(/<input\b[^>]*>/gi) || [];
  for (const tag of inputs) {
    if (!/\bname\s*=\s*(?:(["'])csrf\1|csrf(?=[\s>]))/i.test(tag)) continue;
    const quoted = tag.match(/\bvalue\s*=\s*(["'])([\s\S]*?)\1/i);
    if (quoted) return quoted[2];
    const bare = tag.match(/\bvalue\s*=\s*([^\s>]+)/i);
    if (bare) return bare[1];
  }
  return null;
}

function authHeaders(csrf, extra) {
  return Object.assign(
    {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    extra || {}
  );
}

function pickInStock(products) {
  for (const product of products || []) {
    const variants = product && Array.isArray(product.variants) ? product.variants : [];
    for (const variant of variants) {
      if (variant && variant.in_stock) {
        return { productId: product.id, variantId: variant.id };
      }
    }
  }
  return null;
}

export default function () {
  const loginForm = http.get(url('/v2/login-form'), { redirects: 0 });
  if (!check(loginForm, { 'login form status 200': (r) => r.status === 200 })) {
    fail('login form failed');
  }

  const loginCsrf = extractCsrf(loginForm.body);
  if (!check(loginCsrf, { 'login csrf extracted': (v) => !!v })) {
    fail('missing login csrf');
  }

  let loginRes = http.post(
    url('/v2/login'),
    JSON.stringify({ username: USERNAME, password: PASSWORD, csrf: loginCsrf }),
    { headers: { 'Content-Type': 'application/json' }, redirects: 0 }
  );

  if (loginRes.status === 302) {
    const location = header(loginRes, 'Location');
    if (!check(location, { 'login redirect location present': (v) => !!v })) {
      fail('missing login redirect location');
    }
    loginRes = http.get(resolveUrl(location, '/v2/login'), { redirects: 0 });
  }

  if (!check(loginRes, { 'login status 2xx': (r) => r.status >= 200 && r.status < 300 })) {
    fail('login failed');
  }
  const loginJson = json(loginRes);
  let csrf = loginJson && loginJson.csrf;
  if (!check(csrf, { 'session csrf present': (v) => !!v })) {
    fail('missing session csrf');
  }

  let productId;
  let variantId;
  const catalogRes = http.get(url('/v2/catalog'), { redirects: 0 });
  if (catalogRes.status === 200) {
    const catalog = json(catalogRes);
    const products =
      catalog && catalog.data && Array.isArray(catalog.data.products) ? catalog.data.products : [];
    const picked = pickInStock(products);
    if (picked) {
      productId = picked.productId;
      variantId = picked.variantId;
    }
  }

  if (productId === undefined || productId === null) {
    let next = '/v2/catalog/page';
    for (let page = 0; page < 3 && next && (productId === undefined || productId === null); page += 1) {
      const pageRes = http.get(resolveUrl(next, '/v2/catalog/page'), { redirects: 0 });
      if (!check(pageRes, { 'catalog page status 200': (r) => r.status === 200 })) break;
      const body = json(pageRes);
