    fail('order creation failed');
  }
  if (!check(orderJson && orderJson.accepted, { 'order accepted': (v) => v === true })) {
    fail('order not accepted');
  }
}

import os
import re
import html
import uuid
import time
import itertools

from locust import HttpUser, task, constant, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
USERS = 2
ITERATIONS = 2
QUANTITY = 2
PASSWORD = "bench"

_user_seq = itertools.count(1)
_finished_users = 0
_started_at = time.time()


def safe_json(resp):
    try:
        return resp.json()
    except Exception:
        return None


def parse_csrf(markup):
    if not markup:
        return None
    for match in re.finditer(r"<input\b[^>]*>", markup, re.IGNORECASE | re.DOTALL):
        tag = match.group(0)
        attrs = {}
        for key, value in re.findall(
            r"([A-Za-z_:][-A-Za-z0-9_:.]*)\s*=\s*(\"[^\"]*\"|'[^']*'|[^\s\"'>]+)",
            tag,
        ):
            value = value.strip()
            if len(value) >= 2 and value[0] == value[-1] and value[0] in ("\"", "'"):
                value = value[1:-1]
            attrs[key.lower()] = html.unescape(value)
        if attrs.get("name") == "csrf" and attrs.get("value"):
            return attrs["value"]
    return None


def products_from(data):
    if not isinstance(data, dict):
        return []
    containers = [data]
    nested = data.get("data")
    if isinstance(nested, dict):
        containers.insert(0, nested)
    for container in containers:
        products = container.get("products")
        if isinstance(products, list):
            return products
        product = container.get("product")
        if isinstance(product, dict):
            return [product]
    return []


def scan_products(products):
    for product in products:
        if not isinstance(product, dict):
            continue
        product_id = product.get("id")
        variants = product.get("variants")
        if not isinstance(variants, list):
            continue
        for variant in variants:
            if not isinstance(variant, dict):
                continue
            variant_id = variant.get("id")
            if product_id is not None and variant_id is not None and variant.get("in_stock"):
                return product_id, variant_id
    return None


def extract_next(data):
    if not isinstance(data, dict):
        return None
    nxt = data.get("next")
    if nxt is None and isinstance(data.get("data"), dict):
        nxt = data["data"].get("next")
    return nxt if isinstance(nxt, str) and nxt else None


def error_code(resp):
    data = safe_json(resp)
    if not isinstance(data, dict):
        return None
    err = data.get("error")
    if isinstance(err, str):
        return err
    nested = data.get("data")
    if isinstance(nested, dict):
        err = nested.get("error")
        if isinstance(err, str):
            return err
    return None


class BenchUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        self.username = "bench-%d" % next(_user_seq)
        self.csrf = None
        self.cart_id = None

    def auth_headers(self):
        return {"X-CSRF-Token": self.csrf} if self.csrf else {}

    def update_csrf(self, data):
        if not isinstance(data, dict):
            return
        csrf = data.get("csrf")
        if not csrf and isinstance(data.get("data"), dict):
            csrf = data["data"].get("csrf")
        if csrf:
            self.csrf = csrf

    def login(self):
        with self.client.get("/v2/login-form", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                resp.failure("login-form status %s: %s" % (resp.status_code, resp.text[:200]))
                return False
            csrf = parse_csrf(resp.text)
            if not csrf:
                resp.failure("login-form missing csrf")
                return False
            self.csrf = csrf
            resp.success()

        payload = {"username": self.username, "password": PASSWORD, "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 302:
                location = resp.headers.get("Location") or resp.headers.get("location")
                if not location:
                    resp.failure("login 302 missing Location")
                    return False
                resp.success()
                with self.client.get(location, catch_response=True, allow_redirects=False) as callback:
                    if callback.status_code != 200:
                        callback.failure("login callback status %s: %s" % (callback.status_code, callback.text[:200]))
                        return False
                    data = safe_json(callback)
                    if not isinstance(data, dict):
                        callback.failure("login callback missing json")
                        return False
                    self.update_csrf(data)
                    callback.success()
                return True
            if resp.status_code != 200:
                resp.failure("login status %s: %s" % (resp.status_code, resp.text[:200]))
                return False
            data = safe_json(resp)
            if not isinstance(data, dict):
                resp.failure("login missing json")
                return False
            self.update_csrf(data)
            resp.success()
            return True

    def find_product(self):
        with self.client.get("/v2/catalog", catch_response=True, allow_redirects=False) as resp:
            if resp.status_code == 200:
                data = safe_json(resp)
                found = scan_products(products_from(data))
                resp.success()
                if found:
                    return found
            else:
                resp.failure("catalog status %s: %s" % (resp.status_code, resp.text[:200]))
                return None

        url = "/v2/catalog/page"
        for page_index in range(3):
            with self.client.get(url, catch_response=True, allow_redirects=False) as resp:
                if resp.status_code != 200:
                    resp.failure("catalog page status %s: %s" % (resp.status_code, resp.text[:200]))
                    return None
                data = safe_json(resp)
                found = scan_products(products_from(data))
                nxt = extract_next(data)
                if found:
                    resp.success()
                    return found
                if not nxt:
                    resp.failure("no in-stock product in catalog")
                    return None
                if page_index == 2:
                    resp.failure("no in-stock product in first 3 catalog pages")
                    return None
                resp.success()
                url = nxt
        return None

    def create_cart(self, product_id, variant_id):
        payload = {"product_id": product_id, "variant_id": variant_id}
        with self.client.post("/v2/carts", json=payload, headers=self.auth_headers(), catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 201:
                resp.failure("create cart status %s: %s" % (resp.status_code, resp.text[:200]))
                return None
            data = safe_json(resp)
            cart_id = data.get("id") if isinstance(data, dict) else None
            if not cart_id:
                resp.failure("create cart missing id")
                return None
            self.update_csrf(data)
            etag = resp.headers.get("ETag") or resp.headers.get("etag")
            resp.success()
            return cart_id, etag

    def get_cart_etag(self, cart_id):
        with self.client.get("/v2/carts/%s" % cart_id, catch_response=True, allow_redirects=False) as resp:
            if resp.status_code != 200:
                resp.failure("get cart status %s: %s" % (resp.status_code, resp.text[:200]))
                return None
            etag = resp.headers.get("ETag") or resp.headers.get("etag")
            if not etag:
                resp.failure("get cart missing ETag")
                return None
            resp.success()
            return etag

    def renew_session(self):
        with self.client.post("/v2/session/renew", json={}, headers=self.auth_headers(), catch_response=True, allow_redirects=False) as resp:
            data = safe_json(resp)
            if resp.status_code == 200:
                if data:
                    self.update_csrf(data)
                resp.success()
                return True
            err = error_code(resp)
            if resp.status_code == 401 and err == "session":
                resp.success()
                return False
            resp.failure("renew status %s: %s" % (resp.status_code, resp.text[:200]))
            return False

    def recover_cart(self, cart_id):
        with self.client.post("/v2/carts/%s/recover" % cart_id, json={}, headers=self.auth_headers(), catch_response=True, allow_redirects=False) as resp:
            data = safe_json(resp)
            if resp.status_code in (200, 201, 204):
                if data:
                    self.update_csrf(data)
                resp.success()
                return True
            resp.failure("recover cart status %s: %s" % (resp.status_code, resp.text[:200]))
            return False

    def recover_after_401(self, cart_id, err):
        if err == "denied":
            return False
        if err == "expired":
            if not self.renew_session():
                return False
            return self.recover_cart(cart_id) if cart_id else True
        if err == "session":
            if self.renew_session():
                return self.recover_cart(cart_id) if cart_id else True
            if not self.login():
                return False
            return self.recover_cart(cart_id) if cart_id else True
        return False

    def patch_cart(self, cart_id, etag):
        payload = {"quantity": QUANTITY}
        conflict_used = False
        recovery_used = False
        while True:
            headers = self.auth_headers()
            headers["If-Match"] = etag
            with self.client.patch("/v2/carts/%s" % cart_id, json=payload, headers=headers, catch_response=True, allow_redirects=False) as resp:
                if resp.status_code in (200, 201, 204):
                    data = safe_json(resp)
                    if data:
                        self.update_csrf(data)
                    resp.success()
                    return True
                if resp.status_code == 412 and not conflict_used:
                    conflict_used = True
                    resp.success()
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return False
                    etag = new_etag
                    continue
                if resp.status_code == 401 and not recovery_used:
                    err = error_code(resp)
                    if err == "denied":
                        resp.failure("patch cart denied")
                        return False
                    resp.success()
                    recovery_used = True
                    if not self.recover_after_401(cart_id, err):
                        return False
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return False
                    etag = new_etag
                    continue
                resp.failure("patch cart status %s: %s" % (resp.status_code, resp.text[:200]))
                return False

    def place_order(self, cart_id, etag):
        idempotency_key = "order-%s-%s" % (cart_id, uuid.uuid4().hex)
        recovery_used = False
        while True:
            headers = self.auth_headers()
            headers["Idempotency-Key"] = idempotency_key
            headers["If-Match"] = etag
            with self.client.post("/v2/orders", json={"cart_id": cart_id}, headers=headers, catch_response=True, allow_redirects=False) as resp:
                data = safe_json(resp)
                if resp.status_code == 201 and isinstance(data, dict) and data.get("accepted") is True:
                    self.update_csrf(data)
                    resp.success()
                    return True
                if resp.status_code == 200 and isinstance(data, dict) and data.get("accepted") is False:
                    resp.failure("order accepted=false")
                    return False
                if resp.status_code == 401 and not recovery_used:
                    err = error_code(resp)
                    if err == "denied":
                        resp.failure("order denied")
                        return False
                    resp.success()
                    recovery_used = True
                    if not self.recover_after_401(cart_id, err):
                        return False
                    new_etag = self.get_cart_etag(cart_id)
                    if not new_etag:
                        return False
                    etag = new_etag
                    continue
                resp.failure("order status %s: %s" % (resp.status_code, resp.text[:200]))
                return False

    def run_journey(self):
        self.csrf = None
        self.cart_id = None
        if not self.login():
            return
        found = self.find_product()
        if not found:
            return
        product_id, variant_id = found
        cart = self.create_cart(product_id, variant_id)
        if not cart:
            return
        cart_id, etag = cart
        self.cart_id = cart_id
        etag = self.get_cart_etag(cart_id) or etag
        if not etag:
            return
        if not self.patch_cart(cart_id, etag):
            return
        etag = self.get_cart_etag(cart_id)
        if not etag:
            return
        self.place_order(cart_id, etag)

    @task
    def journey(self):
        global _finished_users
        try:
            for _ in range(ITERATIONS):
                self.run_journey()
        finally:
            _finished_users += 1
            raise StopUser()


class EtagLoadShape(LoadTestShape):
    def tick(self):
        if _finished_users >= USERS:
            return None
        if time.time() - _started_at > 180:
            return None
        return {"user_count": USERS - _finished_users, "spawn_rate": USERS}

