import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL =
        System.getenv("BASE_URL") != null ? System.getenv("BASE_URL") : "http://127.0.0.1:8000";

    private final HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .disableAutoRedirect()
        .acceptHeader("application/json")
        .contentTypeHeader("application/json");

    private static String str(Session session, String key) {
        Object v = session.get(key);
        return v == null ? "" : String.valueOf(v);
    }

    private static String jsonScalar(String v) {
        if (v == null || v.isEmpty()) {
            return "null";
        }
        if (v.matches("-?\\d+")) {
            return v;
        }
        return "\"" + v.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }

    private static String extractIdAfter(String s, int idIdx) {
        if (idIdx < 0) {
            throw new IllegalStateException("id not found in catalog payload");
        }
        int colon = s.indexOf(':', idIdx);
        if (colon < 0) {
            throw new IllegalStateException("malformed id in catalog payload");
        }
        int i = colon + 1;
        while (i < s.length() && Character.isWhitespace(s.charAt(i))) {
            i++;
        }
        boolean quoted = i < s.length() && s.charAt(i) == '"';
        if (quoted) {
            i++;
        }
        int j = i;
        while (j < s.length()) {
            char c = s.charAt(j);
            if (quoted) {
                if (c == '"') {
                    break;
                }
            } else if (!Character.isDigit(c) && c != '-') {
                break;
            }
            j++;
        }
        if (j == i) {
            throw new IllegalStateException("empty id in catalog payload");
        }
        return s.substring(i, j);
    }

    private static String[] selectInStock(String body) {
        if (body == null || body.isEmpty()) {
            throw new IllegalStateException("empty catalog body");
        }
        int stock = body.indexOf("\"in_stock\":true");
        if (stock < 0) {
            stock = body.indexOf("\"in_stock\": true");
        }
        if (stock < 0) {
            stock = body.indexOf("\"in_stock\" : true");
        }
        if (stock < 0) {
            int p = body.indexOf("\"products\"");
            String pid = extractIdAfter(body, body.indexOf("\"id\"", p));
            int v = body.indexOf("\"variants\"", p);
            String vid = extractIdAfter(body, body.indexOf("\"id\"", v));
            return new String[]{pid, vid};
        }
        int vStart = body.lastIndexOf('{', stock);
        int vEnd = body.indexOf('}', stock);
        String variantObj = body.substring(vStart, vEnd);
        String variantId = extractIdAfter(variantObj, variantObj.indexOf("\"id\""));
        int variantsIdx = body.lastIndexOf("\"variants\"", vStart);
        int pidIdx = body.lastIndexOf("\"id\"", variantsIdx);
        String productId = extractIdAfter(body, pidIdx);
        return new String[]{productId, variantId};
    }

    private static String cartBody(Session session) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\"product_id\":").append(jsonScalar(str(session, "productId")))
          .append(",\"variant_id\":").append(jsonScalar(str(session, "variantId")));
        String grant = str(session, "grantId");
        if (!grant.isEmpty()) {
            sb.append(",\"grant_id\":").append(jsonScalar(grant));
        }
        sb.append("}");
        return sb.toString();
    }

    private HttpRequestBuilder cartRequest(String name, boolean strict) {
        HttpRequestBuilder req = http(name)
            .post("/v2/carts")
            .header("X-CSRF-Token", session -> str(session, "csrf"))
            .body(StringBody(session -> cartBody(session))).asJson();
        if (strict) {
            return req.check(status().is(201))
                .check(header("ETag").optional().saveAs("etag"))
                .check(jsonPath("$.id").saveAs("cartId"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"));
        }
        return req.check(status().in(201, 401))
            .check(header("ETag").optional().saveAs("etag"))
            .check(jsonPath("$.id").optional().saveAs("cartId"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(jsonPath("$.error").optional().saveAs("cartError"));
    }

    private HttpRequestBuilder patchRequest(String name, boolean strict) {
        HttpRequestBuilder req = http(name)
            .patch(session -> "/v2/carts/" + str(session, "cartId"))
            .header("X-CSRF-Token", session -> str(session, "csrf"))
            .header("If-Match", session -> str(session, "etag"))
            .body(StringBody("{\"quantity\":2}")).asJson();
        if (strict) {
            return req.check(status().in(200, 204))
                .check(header("ETag").optional().saveAs("etag"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"));
        }
        return req.check(status().in(200, 204, 401, 412))
            .check(status().saveAs("patchStatus"))
            .check(header("ETag").optional().saveAs("etag"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(jsonPath("$.error").optional().saveAs("patchError"));
    }

    private HttpRequestBuilder getCartRequest(String name, boolean strict) {
        HttpRequestBuilder req = http(name)
            .get(session -> "/v2/carts/" + str(session, "cartId"));
        if (strict) {
            return req.check(status().is(200))
                .check(header("ETag").saveAs("etag"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"));
        }
        return req.check(status().in(200, 401))
            .check(header("ETag").optional().saveAs("etag"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(jsonPath("$.error").optional().saveAs("getCartError"));
    }

    private HttpRequestBuilder reservationRequest(String name, boolean strict) {
        HttpRequestBuilder req = http(name)
            .post("/v2/reservations")
            .header("X-CSRF-Token", session -> str(session, "csrf"))
            .body(StringBody(session -> "{\"cart_id\":" + jsonScalar(str(session, "cartId")) + "}")).asJson();
        if (strict) {
            return req.check(status().is(202))
                .check(jsonPath("$.status_url").saveAs("statusUrl"))
                .check(jsonPath("$.csrf").optional().saveAs("csrf"));
        }
        return req.check(status().in(202, 401))
            .check(jsonPath("$.status_url").optional().saveAs("statusUrl"))
            .check(jsonPath("$.csrf").optional().saveAs("csrf"))
            .check(jsonPath("$.error").optional().saveAs("resError"));
    }

    private HttpRequestBuilder pollRequest(String name, boolean strict) {
        HttpRequestBuilder req = http(name)
            .get(session -> str(session, "statusUrl"));
