    private static String jsonScalar(String v) {
        if (v == null || v.isEmpty()) {
            return "null";
        }
        if (v.matches("-?\\d+")) {
            return v;
        }
        return "\"" + v.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }

    private static String extractIdAfter(String s, int idIdx) {
        if (idIdx < 0) {
            throw new IllegalStateException("id not found in catalog payload");
        }
        int colon = s.indexOf(':', idIdx);
        if (colon < 0) {
            throw new IllegalStateException("malformed id in catalog payload");
        }
        int i = colon + 1;
        while (i < s.length() && Character.isWhitespace(s.charAt(i))) {
            i++;
        }
        boolean quoted = i < s.length() && s.charAt(i) == '"';
        if (quoted) {
            i++;
        }
        int j = i;
        while (j < s.length()) {
            char c = s.charAt(j);
            if (quoted) {
                if (c == '"') {
                    break;
                }
            } else if (!Character.isDigit(c) && c != '-') {
                break;
            }
            j++;
        }
        if (j == i) {
            throw new IllegalStateException("empty id in catalog payload");
        }
        return s.substring(i, j);
    }

    private static String[] selectInStock(String body) {
        if (body == null || body.isEmpty()) {
            throw new IllegalStateException("empty catalog body");
        }
        Matcher m = Pattern.compile("\"in_stock\"\\s*:\\s*true").matcher(body);
        if (m.find()) {
            int stock = m.start();
            int vStart = body.lastIndexOf('{', stock);
            int vEnd = body.indexOf('}', stock);
            if (vStart < 0 || vEnd < 0) {
                throw new IllegalStateException("malformed variant in catalog payload");
            }
            String variantObj = body.substring(vStart, vEnd);
            String variantId = extractIdAfter(variantObj, variantObj.indexOf("\"id\""));
            int variantsIdx = body.lastIndexOf("\"variants\"", vStart);
            int pidIdx = body.lastIndexOf("\"id\"", variantsIdx);
            String productId = extractIdAfter(body, pidIdx);
            return new String[]{productId, variantId};
        }
        int p = body.indexOf("\"products\"");
        String pid = extractIdAfter(body, body.indexOf("\"id\"", p));
        int v = body.indexOf("\"variants\"", p);
        String vid = extractIdAfter(body, body.indexOf("\"id\"", v));
        return new String[]{pid, vid};
    }

