import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    expiry_journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '10m',
    },
  },
};

function parseJson(res) {
  try { return JSON.parse(res.body); } catch (e) { return null; }
}

function header(res, name) {
  const h = (res && res.headers) || {};
  const lower = name.toLowerCase();
  const keys = Object.keys(h);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === lower) return h[keys[i]];
  }
  return null;
}

function errorCode(res) {
  const b = parseJson(res);
  return b && b.error ? b.error : null;
}

function resolveUrl(u) {
  if (!u) return u;
  if (u.indexOf('http://') === 0 || u.indexOf('https://') === 0) return u;
  if (u.charAt(0) === '/') return BASE_URL + u;
  return BASE_URL + '/' + u;
}

function extractInputValue(html, name) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  let fallback = null;
  for (let i = 0; i < tags.length; i++) {
    const tag = tags[i];
    const nameM = tag.match(/name\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]*))/i);
    if (!nameM) continue;
    const n = nameM[1] !== undefined ? nameM[1] : (nameM[2] !== undefined ? nameM[2] : nameM[3]);
    if (n !== name) continue;
    const valM = tag.match(/value\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]*))/i);
    const v = valM ? (valM[1] !== undefined ? valM[1] : (valM[2] !== undefined ? valM[2] : valM[3])) : '';
    if (/type\s*=\s*(?:"hidden"|'hidden'|hidden)/i.test(tag)) return v;
    if (fallback === null) fallback = v;
  }
  return fallback;
}

function extractFormAction(html) {
  const m = String(html || '').match(/<form\b[^>]*action\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]*))/i);
  if (!m) return null;
  return m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]);
}

function login(jar, username) {
  const formRes = http.get(BASE_URL + '/v2/login-form', { jar: jar, redirects: 0 });
  check(formRes, { 'login form 200': function (r) { return r.status === 200; } });
  const csrf = extractInputValue(formRes.body, 'csrf');
  check(formRes, { 'login csrf present': function () { return !!csrf; } });
  if (!csrf) return null;

  const res = http.post(BASE_URL + '/v2/login', JSON.stringify({ username: username, password: 'bench', csrf: csrf }), {
    jar: jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json' },
  });

  let body = parseJson(res);
  if (res.status === 302) {
    const loc = header(res, 'Location');
    check(res, { 'login redirect has location': function () { return !!loc; } });
    if (loc) {
      const follow = http.get(resolveUrl(loc), { jar: jar, redirects: 0 });
      check(follow, { 'login follow 200': function (r) { return r.status === 200; } });
      const fb = parseJson(follow);
      if (fb) body = fb;
    }
  }
  const ok = (res.status === 200 || res.status === 302) && body && body.csrf;
  check(res, { 'login ok': function () { return !!ok; } });
  if (!ok) return null;
  return { csrf: body.csrf, user: body.user };
}

function renewSession(jar, csrf) {
  const res = http.post(BASE_URL + '/v2/session/renew', '{}', {
    jar: jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = parseJson(res);
  if (res.status === 200 && b) return b.csrf || csrf;
  return null;
}

function recoverCart(jar, cartId, csrf) {
  const res = http.post(BASE_URL + '/v2/carts/' + cartId + '/recover', '{}', {
    jar: jar,
    redirects: 0,
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf },
  });
  const b = parseJson(res);
  if (res.status === 200 || res.status === 201) return (b && b.csrf) || csrf;
  return csrf;
}

function authedRequest(method, url, payload, jar, state, opts) {
  opts = opts || {};
  const cartId = ('cartId' in opts) ? opts.cartId : state.cartId;
  const onRaw = opts.onRaw;

  const doReq = function (csrf) {
    const headers = { 'Content-Type': 'application/json', 'X-CSRF-Token': csrf };
    if (opts.ifMatch) headers['If-Match'] = opts.ifMatch;
    if (opts.idempotencyKey) headers['Idempotency-Key'] = opts.idempotencyKey;
    const res = http.request(method, url, (payload === null || payload === undefined) ? null : JSON.stringify(payload), {
      jar: jar,
      headers: headers,
      redirects: 0,
    });
    if (onRaw) onRaw(res);
    return res;
  };

  let res = doReq(state.csrf);

  if (res.status === 401) {
    const err = errorCode(res);
    if (err === 'expired') {
      const fresh = renewSession(jar, state.csrf);
      if (fresh) {
        state.csrf = fresh;
        if (cartId) state.csrf = recoverCart(jar, cartId, state.csrf);
        res = doReq(state.csrf);
      }
    } else if (err === 'session') {
      const relogin = login(jar, state.username);
      if (relogin) {
        state.csrf = relogin.csrf;
        if (cartId) state.csrf = recoverCart(jar, cartId, state.csrf);
        res = doReq(state.csrf);
      }
    } else if (err === 'denied') {
      check(res, { 'denied is not expiry': function () { return false; } });
    }
  }

  const b = parseJson(res);
  if (b && b.csrf) state.csrf = b.csrf;
  return res;
}

function pickVariant(jar) {
  const res = http.get(BASE_URL + '/v2/catalog', { jar: jar, redirects: 0 });
  check(res, { 'catalog 200': function (r) { return r.status === 200; } });
  const b = parseJson(res);
  const products = (b && b.data && b.data.products) ? b.data.products : [];
  for (let i = 0; i < products.length; i++) {
    const variants = products[i].variants || [];
    for (let j = 0; j < variants.length; j++) {
      if (variants[j].in_stock) {
        return { product_id: products[i].id, variant_id: variants[j].id };
      }
    }
  }
  return null;
}

function doChallenge(jar, state) {
  const formRes = http.get(BASE_URL + '/v2/challenge-form', {
    jar: jar,
    redirects: 0,
    headers: { 'X-CSRF-Token': state.csrf },
  });
  check(formRes, { 'challenge form 200': function (r) { return r.status === 200; } });
  const action = extractFormAction(formRes.body);
  const challenge = extractInputValue(formRes.body, 'challenge');
  check(formRes, { 'challenge parsed': function () { return !!action && !!challenge; } });
  if (!action || !challenge) return null;

  const postRes = authedRequest('POST', resolveUrl(action), { challenge: challenge }, jar, state, { cartId: null });
  const loc = header(postRes, 'Location');
  check(postRes, { 'challenge accepted': function (r) { return r.status === 302 && !!loc; } });
  if (postRes.status !== 302 || !loc) return null;

  const grantRes = http.get(resolveUrl(loc), {
    jar: jar,
    redirects: 0,
    headers: { 'X-CSRF-Token': state.csrf },
  });
  const b = parseJson(grantRes);
  check(grantRes, { 'grant received': function (r) { return r.status === 200 && !!b && !!b.grant_id; } });
  if (b && b.csrf) state.csrf = b.csrf;
  return b ? b.grant_id : null;
}

function patchCart(jar, state, cartId, quantity) {
  let getRes = authedRequest('GET', BASE_URL + '/v2/carts/' + cartId, null, jar, state, { cartId: cartId });
  let etag = header(getRes, 'ETag');
  if (etag) state.etag = etag;

  let res = authedRequest('PATCH', BASE_URL + '/v2/carts/' + cartId, { quantity: quantity }, jar, state, {
    cartId: cartId,
    ifMatch: state.etag,
  });
  if (res.status === 412) {
    getRes = authedRequest('GET', BASE_URL + '/v2/carts/' + cartId, null, jar, state, { cartId: cartId });
    etag = header(getRes, 'ETag');
    if (etag) state.etag = etag;
    res = authedRequest('PATCH', BASE_URL + '/v2/carts/' + cartId, { quantity: quantity }, jar, state, {
      cartId: cartId,
      ifMatch: state.etag,
    });
  }
  const newEtag = header(res, 'ETag');
  if (newEtag) state.etag = newEtag;
  return res;
}

function reserve(jar, state, cartId) {
  const res = authedRequest('POST', BASE_URL + '/v2/reservations', { cart_id: cartId }, jar, state, { cartId: cartId });
  check(res, { 'reservation accepted': function (r) { return r.status === 202; } });
  const b = parseJson(res);
  if (res.status !== 202 || !b || !b.status_url) return null;

  const statusUrl = resolveUrl(b.status_url);
  for (let i = 0; i < 5; i++) {
    sleep(0.05);
    const poll = authedRequest('GET', statusUrl, null, jar, state, { cartId: cartId });
    const pb = parseJson(poll);
    if (pb && pb.status === 'ready') return pb.reservation_id || null;
    if (pb && pb.status === 'failed') return null;
  }
  return null;
}

function placeOrder(jar, state, cartId, reservationId) {
  if (!state.idempotencyKey) {
    state.idempotencyKey = 'order-' + cartId + '-vu' + __VU + '-iter' + __ITER;
  }
  const payload = { cart_id: cartId };
  if (reservationId) payload.reservation_id = reservationId;
  const res = authedRequest('POST', BASE_URL + '/v2/orders', payload, jar, state, {
    cartId: cartId,
    ifMatch: state.etag,
    idempotencyKey: state.idempotencyKey,
  });
  const b = parseJson(res);
  const accepted = res.status === 201 && b && b.accepted === true;
  check(res, { 'order accepted': function () { return accepted; } });
  return res;
}

function doWork(jar, state) {
  let retries = 0;
  const onRaw = function (res) {
    const err = errorCode(res);
    const expectedExpiry = res.status === 401 && err === 'expired';
    const scheduled429 = res.status === 429;
    businessFailure.add((res.status !== 200 && !expectedExpiry && !scheduled429) ? 1 : 0);
  };
  while (true) {
    const res = authedRequest('POST', BASE_URL + '/v2/work', {}, jar, state, { cartId: state.cartId, onRaw: onRaw });
    if (res.status === 429 && retries < 4) {
      retries++;
      sleep(1);
      continue;
    }
    check(res, { 'work ok': function (r) { return r.status === 200; } });
    return res;
  }
}

export default function () {
  const jar = new http.CookieJar();
  const username = 'bench-' + __VU;
  const state = {
    username: username,
    csrf: null,
    cartId: null,
    etag: null,
    idempotencyKey: null,
  };

  const session = login(jar, username);
  if (!session) {
    check(null, { 'journey login succeeded': function () { return false; } });
    return;
  }
  state.csrf = session.csrf;

  const pick = pickVariant(jar);
  check(pick, { 'in-stock variant found': function (p) { return !!p; } });
  if (!pick) return;

  const grantId = doChallenge(jar, state);

  const cartPayload = { product_id: pick.product_id, variant_id: pick.variant_id };
  if (grantId) cartPayload.grant_id = grantId;
  const cartRes = authedRequest('POST', BASE_URL + '/v2/carts', cartPayload, jar, state, { cartId: null });
  const cartBody = parseJson(cartRes);
  check(cartRes, { 'cart created': function (r) { return r.status === 201 && !!cartBody && !!cartBody.id; } });
  if (cartRes.status !== 201 || !cartBody || !cartBody.id) return;
  state.cartId = cartBody.id;
  const cartEtag = header(cartRes, 'ETag');
  if (cartEtag) state.etag = cartEtag;
  if (cartBody.csrf) state.csrf = cartBody.csrf;

  const patchRes = patchCart(jar, state, state.cartId, 2);
  check(patchRes, { 'cart patched': function (r) { return r.status === 200; } });

  const reservationId = reserve(jar, state, state.cartId);
  check(reservationId, { 'reservation ready': function (r) { return !!r; } });

  if (reservationId) {
    placeOrder(jar, state, state.cartId, reservationId);
  } else {
    check(null, { 'reservation ready for checkout': function () { return false; } });
  }

  doWork(jar, state);
}
