import http from 'k6/http';
import { check, sleep } from 'k6';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';

export const options = {
  scenarios: {
    reservation: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '3m',
    },
  },
};

function resolveUrl(u) {
  if (!u) return null;
  u = String(u);
  if (u.startsWith('http://') || u.startsWith('https://')) return u;
  if (u.startsWith('/')) return BASE + u;
  return BASE + '/' + u;
}

function header(res, name) {
  if (!res || !res.headers) return null;
  const lower = String(name).toLowerCase();
  for (const k of Object.keys(res.headers)) {
    if (k.toLowerCase() === lower) return res.headers[k];
  }
  return null;
}

function attr(tag, name) {
  const m = String(tag).match(new RegExp(name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s"\'>]+))', 'i'));
  if (!m) return null;
  return m[1] !== undefined ? m[1] : (m[2] !== undefined ? m[2] : m[3]);
}

function extractInputValue(html, field) {
  if (!html) return null;
  const tags = String(html).match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const name = attr(tag, 'name');
    if (name === field) {
      const v = attr(tag, 'value');
      if (v !== null && v !== undefined) return v;
    }
  }
  return null;
}

function extractFormAction(html) {
  if (!html) return null;
  const m = String(html).match(/<form\b[^>]*>/i);
  if (!m) return null;
  return attr(m[0], 'action');
}

function tryParseJson(res) {
  try { return res.json(); } catch (e) { return null; }
}

function extractEmbeddedJson(body) {
  if (!body) return null;
  const s = String(body);
  const m = s.match(/<script\b[^>]*type=["']application\/json["'][^>]*>([\s\S]*?)<\/script>/i);
  if (m) { try { return JSON.parse(m[1]); } catch (e) {} }
  const first = s.indexOf('{');
  const last = s.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try { return JSON.parse(s.slice(first, last + 1)); } catch (e) {}
  }
  return null;
}

function newState() {
  return {
    jar: http.cookieJar(),
    username: 'bench-' + __VU,
    password: 'bench',
    csrf: null,
    cartId: null,
    cartEtag: null,
    idemKey: null,
  };
}

function headers(state, extra) {
  return Object.assign(
    { 'Content-Type': 'application/json', 'X-CSRF-Token': state.csrf || '' },
    extra || {}
  );
}

function noteCsrf(state, res) {
  const b = tryParseJson(res);
  if (b && b.csrf) state.csrf = b.csrf;
  return b;
}

function renewSession(state) {
  const r = http.post(BASE + '/v2/session/renew', JSON.stringify({}), {
    jar: state.jar,
    redirects: 0,
    headers: headers(state),
  });
  if (r.status === 200) { noteCsrf(state, r); return true; }
  return false;
}

function recoverCart(state) {
  if (!state.cartId) return false;
  const r = http.post(BASE + '/v2/carts/' + state.cartId + '/recover', JSON.stringify({}), {
    jar: state.jar,
    redirects: 0,
    headers: headers(state),
  });
  noteCsrf(state, r);
  return r.status === 200;
}

function login(state) {
  const formRes = http.get(BASE + '/v2/login-form', { jar: state.jar, redirects: 0 });
  check(formRes, { 'login form served': (r) => r.status === 200 });
  const formCsrf = extractInputValue(formRes.body, 'csrf');
  check(formRes, { 'login csrf present': () => !!formCsrf });
  if (!formCsrf) return false;

  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: state.username, password: state.password, csrf: formCsrf }),
    { jar: state.jar, redirects: 0, headers: { 'Content-Type': 'application/json' } }
  );

  if (loginRes.status === 302) {
    const loc = header(loginRes, 'Location');
    check(loginRes, { 'login redirect has location': () => !!loc });
    if (!loc) return false;
    const gr = http.get(resolveUrl(loc), { jar: state.jar, redirects: 0 });
    const b = tryParseJson(gr);
    state.csrf = (b && b.csrf) ? b.csrf : formCsrf;
    check(gr, { 'login redirect followed once': (r) => r.status === 200 });
    return true;
  }

  const b = tryParseJson(loginRes);
  state.csrf = (b && b.csrf) ? b.csrf : formCsrf;
  const ok = loginRes.status === 200;
  check(loginRes, { 'login ok': () => ok });
  return ok;
}

function authed(state, method, url, bodyObj, extraHeaders) {
  const payload = (bodyObj === null || bodyObj === undefined) ? null : JSON.stringify(bodyObj);
  const makeParams = () => ({ jar: state.jar, redirects: 0, headers: headers(state, extraHeaders) });
  let res = http.request(method, url, payload, makeParams());
  if (res.status === 401) {
    const b = tryParseJson(res);
    const err = b && b.error;
    if (err === 'expired') {
      if (renewSession(state)) {
        recoverCart(state);
        res = http.request(method, url, payload, makeParams());
      }
    } else if (err === 'session') {
      if (login(state)) {
        recoverCart(state);
        res = http.request(method, url, payload, makeParams());
      }
    }
    // error=denied (or unrecoverable): fall through, checks fail truthfully
  }
  noteCsrf(state, res);
  return res;
}

function catalogProducts(state) {
  const products = [];
  const r = http.get(BASE + '/v2/catalog', { jar: state.jar, redirects: 0, headers: headers(state) });
  if (r.status === 200) {
    const b = tryParseJson(r) || extractEmbeddedJson(r.body);
    if (b) {
      if (b.data && Array.isArray(b.data.products)) products.push.apply(products, b.data.products);
      else if (Array.isArray(b.products)) products.push.apply(products, b.products);
      else if (b.data && b.data.product) products.push(b.data.product);
      else if (b.product) products.push(b.product);
    }
  }
  if (products.length === 0) {
    let url = BASE + '/v2/catalog/page';
    for (let i = 0; i < 3 && url; i++) {
      const pr = http.get(url, { jar: state.jar, redirects: 0, headers: headers(state) });
      if (pr.status !== 200) break;
      const b = tryParseJson(pr) || extractEmbeddedJson(pr.body);
      if (!b) break;
      if (b.product) products.push(b.product);
      else if (b.data && b.data.product) products.push(b.data.product);
      else if (b.data && Array.isArray(b.data.products)) products.push.apply(products, b.data.products);
      else if (Array.isArray(b.products)) products.push.apply(products, b.products);
      url = b.next ? resolveUrl(b.next) : null;
    }
  }
  return products;
}

function runChallenge(state) {
  const r = http.get(BASE + '/v2/challenge-form', { jar: state.jar, redirects: 0, headers: headers(state) });
  if (r.status !== 200) return null;
  const action = extractFormAction(r.body);
  const challengeVal = extractInputValue(r.body, 'challenge');
  if (!action || !challengeVal) return null;
  const pr = http.post(resolveUrl(action), JSON.stringify({ challenge: challengeVal }), {
    jar: state.jar,
    redirects: 0,
    headers: headers(state),
  });
  if (pr.status === 302) {
    const loc = header(pr, 'Location');
    if (!loc) return null;
    const gr = http.get(resolveUrl(loc), { jar: state.jar, redirects: 0, headers: headers(state) });
    const b = tryParseJson(gr);
    if (b) {
      if (b.csrf) state.csrf = b.csrf;
      return b.grant_id || null;
    }
    return null;
  }
  const b = tryParseJson(pr);
  if (b) {
    if (b.csrf) state.csrf = b.csrf;
    return b.grant_id || null;
  }
  return null;
}

export default function () {
  const state = newState();

  if (!login(state)) {
    check(state, { 'journey authenticated': () => false });
    return;
  }

  const products = catalogProducts(state);
  let chosen = null;
  for (const p of products) {
    const variants = (p && p.variants) || [];
    for (const v of variants) {
      if (v && v.in_stock) { chosen = { product_id: p.id, variant_id: v.id }; break; }
    }
    if (chosen) break;
  }
  check(chosen, { 'in-stock variant found': (c) => !!c });
  if (!chosen) return;

  const grantId = runChallenge(state);

  const cartBody = { product_id: chosen.product_id, variant_id: chosen.variant_id };
  if (grantId) cartBody.grant_id = grantId;
  const cartRes = authed(state, 'POST', BASE + '/v2/carts', cartBody);
  check(cartRes, { 'cart created': (r) => r.status === 201 });
  const cartJson = tryParseJson(cartRes);
  if (cartRes.status !== 201 || !cartJson || !cartJson.id) return;
  state.cartId = cartJson.id;
  state.idemKey = 'idem-' + state.cartId;
  state.cartEtag = header(cartRes, 'ETag') || state.cartEtag;

  const getRes = authed(state, 'GET', BASE + '/v2/carts/' + state.cartId, null);
  const getEtag = header(getRes, 'ETag');
  if (getEtag) state.cartEtag = getEtag;

  const patchPayload = { quantity: 2 };
  let patchRes = authed(state, 'PATCH', BASE + '/v2/carts/' + state.cartId, patchPayload, {
    'If-Match': state.cartEtag || '',
  });
  if (patchRes.status === 412) {
    const re = authed(state, 'GET', BASE + '/v2/carts/' + state.cartId, null);
    const et = header(re, 'ETag');
    if (et) state.cartEtag = et;
    patchRes = authed(state, 'PATCH', BASE + '/v2/carts/' + state.cartId, patchPayload, {
      'If-Match': state.cartEtag || '',
    });
  }
  check(patchRes, { 'cart quantity patched': (r) => r.status >= 200 && r.status < 300 });
  const patchEtag = header(patchRes, 'ETag');
  if (patchEtag) state.cartEtag = patchEtag;

  const resRes = authed(state, 'POST', BASE + '/v2/reservations', { cart_id: state.cartId });
  check(resRes, { 'reservation job accepted (202)': (r) => r.status === 202 });
  const resJson = tryParseJson(resRes);
  const statusUrl = resJson && resJson.status_url ? resolveUrl(resJson.status_url) : null;
  check(resRes, { 'dynamic status url present': () => !!statusUrl });

  let reservationId = null;
  let ready = false;
  let lastPoll = null;
  if (statusUrl) {
    for (let i = 0; i < 5; i++) {
      sleep(0.05);
      lastPoll = http.get(statusUrl, { jar: state.jar, redirects: 0, headers: headers(state) });
      const b = tryParseJson(lastPoll);
      if (b && b.csrf) state.csrf = b.csrf;
      const status = b && b.status;
      if (status === 'ready') {
        reservationId = b.reservation_id || null;
        ready = !!reservationId;
        break;
      }
      if (status === 'failed') break;
    }
  }
  check(lastPoll || resRes, { 'reservation ready': () => ready });

  if (!ready) {
    // Never check out a pending or failed job.
    return;
  }

  const preOrder = authed(state, 'GET', BASE + '/v2/carts/' + state.cartId, null);
  const preEtag = header(preOrder, 'ETag');
  if (preEtag) state.cartEtag = preEtag;

  const orderRes = authed(
    state,
    'POST',
    BASE + '/v2/orders',
    { cart_id: state.cartId, reservation_id: reservationId },
    { 'Idempotency-Key': state.idemKey, 'If-Match': state.cartEtag || '' }
  );
  const orderJson = tryParseJson(orderRes);
  const orderOk = orderRes.status === 201 && orderJson && orderJson.accepted === true;
  check(orderRes, { 'order committed': () => orderOk });
}
