import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';

export const options = {
  scenarios: {
    flow: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

function headerValue(res, name) {
  const headers = (res && res.headers) || {};
  const lower = String(name).toLowerCase();
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === lower) return headers[key];
  }
  return null;
}

function jsonBody(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractFormCsrf(html) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    if (!/\bname\s*=\s*["']csrf["']/i.test(tag)) continue;
    const m = tag.match(/\bvalue\s*=\s*["']([^"']*)["']/i);
    if (m) return m[1];
  }
  return null;
}

function buildHeaders(csrf, etag, cart) {
  const h = { 'Content-Type': 'application/json' };
  if (csrf) h['X-CSRF-Token'] = csrf;
  if (etag) h['If-Match'] = etag;
  if (cart) h['Idempotency-Key'] = cart;
  return h;
}

export default function () {
  const jar = new http.CookieJar();
  const params = (csrf, etag, cart) => ({
    jar,
    redirects: 0,
    timeout: '3s',
    headers: buildHeaders(csrf, etag, cart),
  });

  let csrf = null;
  let etag = null;
  let cart = null;
  let grant = null;

  // 1) GET /v2/login-form
  const formRes = http.get(`${BASE_URL}/v2/login-form`, params(csrf, etag, cart));
  const formCsrf = extractFormCsrf(formRes.body);
  const formEtag = headerValue(formRes, 'ETag');
  if (formEtag) etag = formEtag;
  check(formRes, {
    'login form csrf extracted': () => !!formCsrf,
  });

  // 2) POST /v2/login
  const username = `bench-${__VU}`;
  const loginRes = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password: PASSWORD, csrf: formCsrf }),
    params(formCsrf, etag, cart)
  );
  const loginBody = jsonBody(loginRes);
  if (loginBody && loginBody.csrf) csrf = loginBody.csrf;
  const loginEtag = headerValue(loginRes, 'ETag');
  if (loginEtag) etag = loginEtag;
  check(loginRes, {
    'login returns csrf': (r) => /"csrf"\s*:/.test(r.body || ''),
  });

  // 3) Optional login redirect: GET the dynamic Location exactly once
  const location = headerValue(loginRes, 'Location');
  if (location) {
    const target = /^https?:\/\//i.test(location) ? location : `${BASE_URL}${location}`;
    const redirectRes = http.get(target, params(csrf, etag, cart));
    const redirectBody = jsonBody(redirectRes);
    if (redirectBody) {
      if (redirectBody.csrf) csrf = redirectBody.csrf;
      if (redirectBody.grant_id) grant = redirectBody.grant_id;
    }
    const redirectEtag = headerValue(redirectRes, 'ETag');
    if (redirectEtag) etag = redirectEtag;
  }

  // 4) GET /v2/catalog — first product whose first variant is in stock
  const catalogRes = http.get(`${BASE_URL}/v2/catalog`, params(csrf, etag, cart));
  const catalogBody = jsonBody(catalogRes);
  if (catalogBody && catalogBody.csrf) csrf = catalogBody.csrf;
  const catalogEtag = headerValue(catalogRes, 'ETag');
  if (catalogEtag) etag = catalogEtag;
  const products =
    catalogBody && catalogBody.data && Array.isArray(catalogBody.data.products)
      ? catalogBody.data.products
      : [];
  let product = null;
  let variant = null;
  for (const p of products) {
    const v = p && Array.isArray(p.variants) ? p.variants[0] : null;
    if (v && v.in_stock) {
      product = p.id;
      variant = v.id;
      break;
    }
  }
  check(catalogRes, {
    'catalog product selected': () => !!product && !!variant,
  });
  if (!product || !variant) return;

  // 5) POST /v2/carts
  const cartPayload = { product_id: product, variant_id: variant };
  if (grant) cartPayload.grant_id = grant;
  const cartRes = http.post(
    `${BASE_URL}/v2/carts`,
    JSON.stringify(cartPayload),
    params(csrf, etag, null)
  );
  const cartBody = jsonBody(cartRes);
  if (cartBody) {
    if (cartBody.csrf) csrf = cartBody.csrf;
    if (cartBody.id) cart = cartBody.id;
  }
  const cartEtag = headerValue(cartRes, 'ETag');
  if (cartEtag) etag = cartEtag;
  check(cartRes, {
    'cart created': (r) => /"id"\s*:\s*"cart-/.test(r.body || ''),
  });
  if (!cart) return;

  // 6) POST /v2/orders — Idempotency-Key stable per cart, If-Match from cart ETag
  const orderRes = http.post(
    `${BASE_URL}/v2/orders`,
    JSON.stringify({ cart_id: cart }),
    params(csrf, etag, cart)
  );
  const orderBody = jsonBody(orderRes);
  if (orderBody && orderBody.csrf) csrf = orderBody.csrf;
  check(orderRes, {
    'order accepted': (r) => /"accepted"\s*:\s*true/.test(r.body || ''),
  });
}

import os
import re
import itertools
import threading

from locust import HttpUser, task, LoadTestShape, StopUser

BASE_URL = os.environ["BASE_URL"]

_user_counter = itertools.count(1)
_counter_lock = threading.Lock()


def _next_user_number():
    with _counter_lock:
        return next(_user_counter)


class ShopUser(HttpUser):
    host = BASE_URL
    completed_iterations = 0
    _completed_lock = threading.Lock()

    def on_start(self):
        self.username = "bench-%d" % _next_user_number()
        self.password = "bench"
        self._reset_state()
        self._iterations = 0

    def _reset_state(self):
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None

    # ---------- helpers ----------

    @staticmethod
    def _extract_form_csrf(html):
        if not html:
            return None
        for tag_match in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE | re.DOTALL):
            tag = tag_match.group(0)
            if not re.search(r"\bname\s*=\s*(?:\"csrf\"|'csrf'|csrf)(?=[\s/>])", tag, re.IGNORECASE):
                continue
            value_match = re.search(
                r"\bvalue\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>]+))",
                tag,
                re.IGNORECASE,
            )
            if value_match:
                for group in value_match.groups():
                    if group is not None:
                        return group
        return None

    def _headers(self, if_match=False, idempotency=False):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if if_match and self.etag:
            headers["If-Match"] = self.etag
        if idempotency and self.cart_id:
            headers["Idempotency-Key"] = self.cart_id
        return headers

    def _update_etag(self, response):
        etag = response.headers.get("ETag") or response.headers.get("etag")
        if etag:
            self.etag = etag

    def _update_csrf(self, response):
        try:
            data = response.json()
        except Exception:
            return None
        if isinstance(data, dict):
            csrf = data.get("csrf")
            if csrf:
                self.csrf = csrf
            return data
        return None

    def _error_code(self, response):
        try:
            data = response.json()
            if isinstance(data, dict):
                return data.get("error")
        except Exception:
            pass
        return None

    def _request(self, method, url, name, **kwargs):
        kwargs["catch_response"] = True
        kwargs["name"] = name
        response = self.client.request(method, url, **kwargs)
        if response.status_code == 401:
            error = self._error_code(response)
            if error in ("expired", "session"):
                if self._renew_and_recover(error):
                    response.success()
                    return self.client.request(method, url, **kwargs)
                response.failure("401 %s: recovery failed" % error)
                return None
        return response

    def _renew_and_recover(self, error):
        renewed = False
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            catch_response=True,
            name="/v2/session/renew",
        ) as renew:
            if renew.status_code == 200:
                try:
                    data = renew.json()
                    if isinstance(data, dict) and data.get("csrf"):
                        self.csrf = data["csrf"]
                    renew.success()
                    renewed = True
                except Exception:
                    renew.failure("renew: invalid JSON body")
            elif error == "session":
                # Revoked session: renew may fail; fall back to a fresh login.
                renew.success()
                renewed = self._fresh_login()
            else:
                renew.failure("renew failed: status=%s" % renew.status_code)
        if not renewed:
            return False
        if self.cart_id:
            with self.client.post(
                "/v2/carts/%s/recover" % self.cart_id,
                json={},
                headers=self._headers(),
                catch_response=True,
                name="/v2/carts/[id]/recover",
            ) as recover:
                if recover.status_code in (200, 201):
                    try:
                        data = recover.json()
                        if isinstance(data, dict) and data.get("csrf"):
                            self.csrf = data["csrf"]
                    except Exception:
                        pass
                    recover.success()
                else:
                    recover.failure("cart recover failed: status=%s" % recover.status_code)
                    return False
        return True

    def _fresh_login(self):
        with self.client.get(
            "/v2/login-form",
            headers={"Content-Type": "application/json"},
            catch_response=True,
            name="/v2/login-form",
            allow_redirects=False,
        ) as form:
            form_csrf = self._extract_form_csrf(form.text)
            if form.status_code == 200 and form_csrf:
                self.csrf = form_csrf
                form.success()
            else:
                form.failure("re-login: csrf input not found")
                return False
        with self.client.post(
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            headers=self._headers(),
            catch_response=True,
            name="/v2/login",
            allow_redirects=False,
        ) as login:
            data = self._update_csrf(login)
            location = login.headers.get("Location") or login.headers.get("location")
            if login.status_code in (200, 201) and data and data.get("csrf"):
                login.success()
                return True
            if login.status_code in (301, 302, 303, 307, 308) and location:
                login.success()
                with self.client.get(
                    location,
                    headers=self._headers(),
                    catch_response=True,
                    name="login-redirect",
                    allow_redirects=False,
                ) as redirect:
                    redirect_data = self._update_csrf(redirect)
                    if redirect_data and redirect_data.get("grant_id"):
                        self.grant_id = redirect_data["grant_id"]
                    if redirect.status_code == 200:
                        redirect.success()
                        return True
                    redirect.failure("re-login redirect failed: status=%s" % redirect.status_code)
                    return False
            login.failure("re-login failed: status=%s" % login.status_code)
            return False

    # ---------- journey ----------

    @task
    def journey(self):
        try:
            self._journey()
        except Exception:
            pass
        finally:
            self._iterations += 1
            with ShopUser._completed_lock:
                ShopUser.completed_iterations += 1
            if self._iterations >= 2:
                raise StopUser()

    def _journey(self):
        self._reset_state()

        # 1. Login form: extract the csrf input (decoys / attribute variants tolerated).
        response = self._request(
            "GET",
            "/v2/login-form",
            "/v2/login-form",
            headers=self._headers(),
            allow_redirects=False,
        )
        if response is None:
            return
        self._update_etag(response)
        form_csrf = self._extract_form_csrf(response.text)
        if response.status_code == 200 and form_csrf:
            self.csrf = form_csrf
            response.success()
        else:
            response.failure("login-form: csrf input not found (status=%s)" % response.status_code)
            return

        # 2. Login.
        response = self._request(
            "POST",
            "/v2/login",
            "/v2/login",
            json={"username": self.username, "password": self.password, "csrf": self.csrf},
            headers=self._headers(),
            allow_redirects=False,
        )
        if response is None:
            return
        self._update_etag(response)
        data = self._update_csrf(response)
        location = response.headers.get("Location") or response.headers.get("location")
        if response.status_code in (200, 201) and data and data.get("csrf"):
            response.success()
        elif response.status_code in (301, 302, 303, 307, 308) and location:
            response.success()
        else:
            response.failure("login failed: status=%s" % response.status_code)
            return

        # 3. Optional login redirect (challenge grant): GET the dynamic Location exactly once.
        if location:
            response = self._request(
                "GET",
                location,
                "login-redirect",
                headers=self._headers(),
                allow_redirects=False,
            )
            if response is None:
                return
            self._update_etag(response)
            data = self._update_csrf(response)
            if data and data.get("grant_id"):
                self.grant_id = data["grant_id"]
            if response.status_code == 200:
                response.success()
            else:
                response.failure("login redirect failed: status=%s" % response.status_code)
                return

        # 4. Catalog: pick the first in-stock product (order-independent).
        response = self._request(
            "GET",
            "/v2/catalog",
            "/v2/catalog",
            headers=self._headers(),
        )
        if response is None:
            return
        self._update_etag(response)
        data = self._update_csrf(response)
        product_id = None
