import http from 'k6/http';
import { check } from 'k6';
import { SharedArray } from 'k6/data';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';

const accounts = new SharedArray('accounts', function () {
  return JSON.parse(open('/fixtures/m04-accounts.json'));
});

export const options = {
  scenarios: {
    journey: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '5m',
    },
  },
};

function tryJson(body) {
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function getHeader(res, name) {
  if (!res || !res.headers) {
    return null;
  }
  const lower = String(name).toLowerCase();
  const keys = Object.keys(res.headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === lower) {
      return res.headers[keys[i]];
    }
  }
  return null;
}

function resolveUrl(loc) {
  if (!loc) {
    return BASE_URL;
  }
  if (/^https?:\/\//i.test(loc)) {
    return loc;
  }
  return BASE_URL + (loc.charAt(0) === '/' ? loc : '/' + loc);
}

function extractInputValue(html, name) {
  if (!html) {
    return null;
  }
  const re = new RegExp('<input(?=[^>]*\\bname=["\']' + name + '["\'])(?=[^>]*\\bvalue=["\']([^"\']+)["\'])[^>]*>', 'i');
  const m = String(html).match(re);
  return m ? m[1] : null;
}

function extractFormAction(html) {
  if (!html) {
    return null;
  }
  const m = String(html).match(/<form[^>]*\baction=["']([^"']+)["']/i);
  return m ? m[1] : null;
}

function authHeaders(state, extra) {
  const h = { 'Content-Type': 'application/json' };
  if (state.csrf) {
    h['X-CSRF-Token'] = state.csrf;
  }
  if (extra) {
    const keys = Object.keys(extra);
    for (let i = 0; i < keys.length; i++) {
      h[keys[i]] = extra[keys[i]];
    }
  }
  return h;
}

function doLogin(jar, username, password) {
  const state = { csrf: null, grantId: null };

  const formRes = http.get(BASE_URL + '/v2/login-form', { jar: jar, redirects: 0 });
  const formCsrf = extractInputValue(formRes.body, 'csrf');
  check(formRes, {
    'login form 200': function (r) { return r.status === 200; },
    'login form csrf present': function () { return !!formCsrf; },
  });
  state.csrf = formCsrf;

  const loginRes = http.post(
    BASE_URL + '/v2/login',
    JSON.stringify({ username: username, password: password, csrf: formCsrf }),
    { jar: jar, redirects: 0, headers: authHeaders(state) }
  );

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loginRes, { 'login redirect location present': function () { return !!loc; } });
    if (loc) {
      const challengeRes = http.get(resolveUrl(loc), { jar: jar, redirects: 0, headers: authHeaders(state) });
      const parsed = tryJson(challengeRes.body);
      if (parsed && (parsed.grant_id || parsed.csrf)) {
        if (parsed.csrf) { state.csrf = parsed.csrf; }
        if (parsed.grant_id) { state.grantId = parsed.grant_id; }
      } else {
        const action = extractFormAction(challengeRes.body);
        const challenge = extractInputValue(challengeRes.body, 'challenge');
        check(challengeRes, { 'challenge form parsed': function () { return !!action && !!challenge; } });
        if (action && challenge) {
          const postRes = http.post(
            resolveUrl(action),
            JSON.stringify({ challenge: challenge }),
            { jar: jar, redirects: 0, headers: authHeaders(state) }
          );
          let grantRes = null;
          if (postRes.status === 302) {
            const loc2 = getHeader(postRes, 'Location');
            if (loc2) {
              grantRes = http.get(resolveUrl(loc2), { jar: jar, redirects: 0, headers: authHeaders(state) });
            }
          } else {
            grantRes = postRes;
          }
          const g = grantRes ? tryJson(grantRes.body) : null;
          if (g) {
            if (g.csrf) { state.csrf = g.csrf; }
            if (g.grant_id) { state.grantId = g.grant_id; }
          }
          check(grantRes || postRes, { 'challenge grant received': function () { return !!(g && g.grant_id); } });
        }
      }
    }
  } else {
    const parsed = tryJson(loginRes.body);
    check(loginRes, {
      'login 200': function (r) { return r.status === 200; },
      'login csrf present': function () { return !!(parsed && parsed.csrf); },
    });
    if (parsed && parsed.csrf) { state.csrf = parsed.csrf; }
  }

  return state;
}

function isRecoverable401(res) {
  if (!res || res.status !== 401) {
    return false;
  }
  const parsed = tryJson(res.body);
  const err = parsed && parsed.error;
  return err === 'expired' || err === 'session';
}

function recover(jar, state) {
  const renewRes = http.post(BASE_URL + '/v2/session/renew', '{}', { jar: jar, redirects: 0, headers: authHeaders(state) });
  const renewParsed = tryJson(renewRes.body);
  if (renewParsed && renewParsed.csrf) { state.csrf = renewParsed.csrf; }
  if (renewRes.status === 401) {
    const fresh = doLogin(jar, state.username, state.password);
    state.csrf = fresh.csrf;
  }
  if (state.cartId) {
    const recRes = http.post(BASE_URL + '/v2/carts/' + state.cartId + '/recover', '{}', { jar: jar, redirects: 0, headers: authHeaders(state) });
    const recParsed = tryJson(recRes.body);
    if (recParsed && recParsed.csrf) { state.csrf = recParsed.csrf; }
    const etag = getHeader(recRes, 'ETag');
    if (etag) { state.etag = etag; }
  }
}

function callWithRecovery(jar, state, fn) {
  let res = fn();
  if (isRecoverable401(res)) {
    recover(jar, state);
    res = fn();
  }
  return res;
}

export default function () {
  const account = accounts[(__VU - 1) % accounts.length];
  const jar = new http.CookieJar();
  const state = {
    username: account.username,
    password: account.password,
    csrf: null,
    etag: null,
    cartId: null,
    grantId: null,
  };

  const login = doLogin(jar, account.username, account.password);
  state.csrf = login.csrf;
  state.grantId = login.grantId;

  const catRes = callWithRecovery(jar, state, function () {
    return http.get(BASE_URL + '/v2/catalog', { jar: jar, redirects: 0, headers: authHeaders(state) });
  });
  const cat = tryJson(catRes.body);
  if (cat && cat.csrf) { state.csrf = cat.csrf; }
  check(catRes, { 'catalog 200': function (r) { return r.status === 200; } });

  let product = null;
  let variant = null;
  const products = cat && cat.data && Array.isArray(cat.data.products) ? cat.data.products : [];
  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const v0 = p.variants && p.variants[0];
    if (v0 && v0.in_stock) { product = p; variant = v0; break; }
  }
  if (!product) {
    for (let i = 0; i < products.length; i++) {
      const p = products[i];
      const vs = p.variants || [];
      for (let j = 0; j < vs.length; j++) {
        if (vs[j].in_stock) { product = p; variant = vs[j]; break; }
      }
      if (product) { break; }
    }
  }
  check(catRes, { 'in-stock product found': function () { return !!product && !!variant; } });

  const cartBody = { product_id: product ? product.id : null, variant_id: variant ? variant.id : null };
  if (state.grantId) { cartBody.grant_id = state.grantId; }
  const cartRes = callWithRecovery(jar, state, function () {
    return http.post(BASE_URL + '/v2/carts', JSON.stringify(cartBody), { jar: jar, redirects: 0, headers: authHeaders(state) });
  });
  const cart = tryJson(cartRes.body);
  if (cart) {
    if (cart.csrf) { state.csrf = cart.csrf; }
    if (cart.id) { state.cartId = cart.id; }
  }
  const cartEtag = getHeader(cartRes, 'ETag');
  if (cartEtag) { state.etag = cartEtag; }
  check(cartRes, {
    'cart created 201': function (r) { return r.status === 201; },
    'cart id present': function () { return !!state.cartId; },
  });

  const patchBody = JSON.stringify({ quantity: account.quantity });
  const patchOnce = function () {
    const extra = state.etag ? { 'If-Match': state.etag } : null;
    return http.patch(BASE_URL + '/v2/carts/' + state.cartId, patchBody, { jar: jar, redirects: 0, headers: authHeaders(state, extra) });
  };
  let patchRes = callWithRecovery(jar, state, patchOnce);
  if (patchRes.status === 412) {
    const getRes = http.get(BASE_URL + '/v2/carts/' + state.cartId, { jar: jar, redirects: 0, headers: authHeaders(state) });
    const etag = getHeader(getRes, 'ETag');
    if (etag) { state.etag = etag; }
    patchRes = patchOnce();
  }
  const patchParsed = tryJson(patchRes.body);
  if (patchParsed && patchParsed.csrf) { state.csrf = patchParsed.csrf; }
  const patchEtag = getHeader(patchRes, 'ETag');
  if (patchEtag) { state.etag = patchEtag; }
  check(patchRes, { 'cart quantity patched': function (r) { return r.status === 200 || r.status === 201 || r.status === 204; } });

  const orderRes = callWithRecovery(jar, state, function () {
    const extra = { 'Idempotency-Key': String(state.cartId) };
    if (state.etag) { extra['If-Match'] = state.etag; }
    return http.post(BASE_URL + '/v2/orders', JSON.stringify({ cart_id: state.cartId }), { jar: jar, redirects: 0, headers: authHeaders(state, extra) });
  });
  const order = tryJson(orderRes.body);
  if (order && order.csrf) { state.csrf = order.csrf; }
  check(orderRes, {
    'order 201': function (r) { return r.status === 201; },
    'order accepted': function () { return !!(order && order.accepted === true); },
  });
}
