import json
import os
import re

from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
FIXTURE_PATH = "/fixtures/m04-accounts.json"
USERS = 2
ITERATIONS = 2
MAX_RUN_TIME = 300

with open(FIXTURE_PATH) as _f:
    ACCOUNTS = json.load(_f)

STATE = {"started": 0, "done": 0}


def _attr(tag, attr):
    pattern = r"(?<![\w-])" + re.escape(attr) + r"\s*=\s*"
    m = re.search(pattern + r'"([^"]*)"', tag, re.IGNORECASE) or \
        re.search(pattern + r"'([^']*)'", tag, re.IGNORECASE) or \
        re.search(pattern + r"([^\s>]+)", tag, re.IGNORECASE)
    return m.group(1) if m else None


def extract_input_value(html, name):
    if not html:
        return None
    for tag in re.findall(r"<input\b[^>]*>", html, re.IGNORECASE | re.DOTALL):
        if _attr(tag, "name") == name:
            return _attr(tag, "value")
    return None


def extract_form_action(html):
    if not html:
        return None
    m = re.search(r"<form\b[^>]*>", html, re.IGNORECASE | re.DOTALL)
    return _attr(m.group(0), "action") if m else None


class ShopUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        idx = STATE["started"]
        STATE["started"] += 1
        self.account = ACCOUNTS[idx] if idx < len(ACCOUNTS) else None
        self.iterations = 0
        self._done_counted = False
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None

    def on_stop(self):
        self._mark_done()

    def _mark_done(self):
        if self.account is not None and not self._done_counted:
            self._done_counted = True
            STATE["done"] += 1

    @task
    def journey(self):
        if self.account is None:
            raise StopUser()
        try:
            self.run_journey()
        except Exception as exc:
            print(f"journey error: {exc}")
        self.iterations += 1
        if self.iterations >= ITERATIONS:
            self._mark_done()
            raise StopUser()

    # ---------- helpers ----------
    def _json(self, r):
        try:
            data = r.json()
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    def _error(self, r):
        return self._json(r).get("error")

    def _auth_headers(self, if_match=False, idempotency_key=None):
        headers = {"Content-Type": "application/json"}
        if self.csrf:
            headers["X-CSRF-Token"] = self.csrf
        if if_match and self.etag:
            headers["If-Match"] = self.etag
        if idempotency_key:
            headers["Idempotency-Key"] = idempotency_key
        return headers

    def _update_csrf(self, r):
        data = self._json(r)
        if data.get("csrf"):
            self.csrf = data["csrf"]

    def _update_etag(self, r):
        etag = r.headers.get("ETag")
        if etag:
            self.etag = etag

    # ---------- journey ----------
    def run_journey(self):
        account = self.account
        username = account["username"]
        password = account.get("password", "bench")
        quantity = int(account["quantity"])

        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None

        r = self.client.get("/v2/login-form", allow_redirects=False,
                            catch_response=True, name="GET /v2/login-form")
        if r.status_code != 200:
            r.failure(f"login-form status {r.status_code}")
            return
        form_csrf = extract_input_value(r.text, "csrf")
        if not form_csrf:
            r.failure("login-form missing csrf input")
            return
        r.success()
        self.csrf = form_csrf

        if not self.do_login(username, password, form_csrf):
            return

        product_id, variant_id = self.do_catalog()
        if not product_id:
            return

        cart_id = self.do_create_cart(product_id, variant_id)
        if not cart_id:
            return

        if not self.do_patch_cart(cart_id, quantity):
            return

        self.do_order(cart_id)

    def do_login(self, username, password, form_csrf):
        r = self.client.post("/v2/login",
                             json={"username": username, "password": password, "csrf": form_csrf},
                             allow_redirects=False, catch_response=True, name="POST /v2/login")
        if r.status_code == 200:
            self._update_csrf(r)
            r.success()
            return True
        if r.status_code == 302:
            location = r.headers.get("Location")
            if not location:
                r.failure("login 302 missing Location")
                return False
            r.success()
            return self.do_challenge(location)
        r.failure(f"login status {r.status_code}: {r.text[:200]}")
        return False

    def do_challenge(self, location):
        r = self.client.get(location, allow_redirects=False,
                            catch_response=True, name="GET challenge-form")
        if r.status_code != 200:
            r.failure(f"challenge-form status {r.status_code}")
            return False
        data = self._json(r)
        if "grant_id" in data or "csrf" in data:
            if data.get("csrf"):
                self.csrf = data["csrf"]
            self.grant_id = data.get("grant_id")
            r.success()
            return True
        html = r.text
        action = extract_form_action(html)
        challenge = extract_input_value(html, "challenge")
        challenge_csrf = extract_input_value(html, "csrf")
        if challenge_csrf:
            self.csrf = challenge_csrf
        if not action or not challenge:
            r.failure("challenge-form missing action or challenge")
            return False
        r.success()
        r = self.client.post(action, json={"challenge": challenge},
                             headers=self._auth_headers(),
                             allow_redirects=False, catch_response=True,
                             name="POST challenge")
        if r.status_code == 302:
            claim = r.headers.get("Location")
            if not claim:
                r.failure("challenge 302 missing Location")
                return False
            r.success()
        elif r.status_code == 200:
            data = self._json(r)
            if data.get("csrf"):
                self.csrf = data["csrf"]
            self.grant_id = data.get("grant_id")
            r.success()
            return True
        else:
            r.failure(f"challenge status {r.status_code}: {r.text[:200]}")
            return False
        r = self.client.get(claim, allow_redirects=False,
                            catch_response=True, name="GET challenge-claim")
        if r.status_code != 200:
            r.failure(f"challenge-claim status {r.status_code}")
            return False
        data = self._json(r)
        if data.get("csrf"):
            self.csrf = data["csrf"]
        self.grant_id = data.get("grant_id")
        r.success()
        return True

    def do_catalog(self):
        r = self.client.get("/v2/catalog", headers=self._auth_headers(),
                            allow_redirects=False, catch_response=True,
                            name="GET /v2/catalog")
        if r.status_code != 200:
            r.failure(f"catalog status {r.status_code}")
            return None, None
        data = self._json(r)
        if data.get("csrf"):
            self.csrf = data["csrf"]
        products = (data.get("data") or {}).get("products") or []
        for product in products:
            variants = product.get("variants") or []
            if variants and variants[0].get("in_stock"):
                r.success()
                return product.get("id"), variants[0].get("id")
        r.failure("catalog has no in-stock product")
