            if not location:
                r.failure("login 302 missing Location")
                return False
            r.success()
            return self.do_challenge(location)
        r.failure(f"login status {r.status_code}: {r.text[:200]}")
        return False

    def do_challenge(self, location):
        r = self.client.get(location, allow_redirects=False,
                            catch_response=True, name="GET challenge-form")
        if r.status_code != 200:
            r.failure(f"challenge-form status {r.status_code}")
            return False
        data = self._json(r)
        if "grant_id" in data or "csrf" in data:
            if data.get("csrf"):
                self.csrf = data["csrf"]
            self.grant_id = data.get("grant_id")
            r.success()
            return True
        html = r.text
        action = extract_form_action(html)
        challenge = extract_input_value(html, "challenge")
        challenge_csrf = extract_input_value(html, "csrf")
        if challenge_csrf:
            self.csrf = challenge_csrf
        if not action or not challenge:
            r.failure("challenge-form missing action or challenge")
            return False
        r.success()
        r = self.client.post(action, json={"challenge": challenge},
                             headers=self._auth_headers(),
                             allow_redirects=False, catch_response=True,
                             name="POST challenge")
        if r.status_code == 302:
            claim = r.headers.get("Location")
            if not claim:
                r.failure("challenge 302 missing Location")
                return False
            r.success()
        elif r.status_code == 200:
            data = self._json(r)
            if data.get("csrf"):
                self.csrf = data["csrf"]
            self.grant_id = data.get("grant_id")
            r.success()
            return True
        else:
            r.failure(f"challenge status {r.status_code}: {r.text[:200]}")
            return False
        r = self.client.get(claim, allow_redirects=False,
                            catch_response=True, name="GET challenge-claim")
        if r.status_code != 200:
            r.failure(f"challenge-claim status {r.status_code}")
            return False
        data = self._json(r)
        if data.get("csrf"):
            self.csrf = data["csrf"]
        self.grant_id = data.get("grant_id")
        r.success()
        return True

    def do_catalog(self):
        r = self.client.get("/v2/catalog", headers=self._auth_headers(),
                            allow_redirects=False, catch_response=True,
                            name="GET /v2/catalog")
        if r.status_code != 200:
            r.failure(f"catalog status {r.status_code}")
            return None, None
        data = self._json(r)
        if data.get("csrf"):
            self.csrf = data["csrf"]
        products = (data.get("data") or {}).get("products") or []
        for product in products:
            variants = product.get("variants") or []
            if variants and variants[0].get("in_stock"):
                r.success()
                return product.get("id"), variants[0].get("id")
        r.failure("catalog has no in-stock product")
        return None, None

    def do_create_cart(self, product_id, variant_id):
        body = {"product_id": product_id, "variant_id": variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id
        r = self.client.post("/v2/carts", json=body, headers=self._auth_headers(),
                             allow_redirects=False, catch_response=True,
                             name="POST /v2/carts")
        if r.status_code != 201:
            r.failure(f"cart status {r.status_code}: {r.text[:200]}")
            return None
        data = self._json(r)
        cart_id = data.get("id")
        if not cart_id:
            r.failure("cart response missing id")
            return None
        if data.get("csrf"):
            self.csrf = data["csrf"]
        self._update_etag(r)
        self.cart_id = cart_id
        r.success()
        return cart_id

    def _patch(self, cart_id, payload):
        return self.client.patch(f"/v2/carts/{cart_id}", json=payload,
                                 headers=self._auth_headers(if_match=True),
                                 allow_redirects=False, catch_response=True,
                                 name="PATCH /v2/carts/{id}")

    def _refresh_etag(self, cart_id):
        r = self.client.get(f"/v2/carts/{cart_id}", headers=self._auth_headers(),
                            allow_redirects=False, catch_response=True,
                            name="GET /v2/carts/{id}")
        if r.status_code == 200:
            self._update_etag(r)
            self._update_csrf(r)
            r.success()
            return True
        r.failure(f"get cart status {r.status_code}")
        return False

    def _fresh_login(self):
        r = self.client.get("/v2/login-form", allow_redirects=False,
                            catch_response=True, name="GET /v2/login-form")
        if r.status_code != 200:
            r.failure(f"re-login form status {r.status_code}")
            return False
        form_csrf = extract_input_value(r.text, "csrf")
        if not form_csrf:
            r.failure("re-login form missing csrf")
            return False
        r.success()
        self.csrf = form_csrf
        return self.do_login(self.account["username"],
                             self.account.get("password", "bench"),
                             form_csrf)

    def _recover_401(self, cart_id):
        r = self.client.post("/v2/session/renew", json={},
                             headers=self._auth_headers(),
                             allow_redirects=False, catch_response=True,
                             name="POST /v2/session/renew")
        if r.status_code == 200:
            self._update_csrf(r)
            r.success()
        elif r.status_code == 401:
            # session revoked: renew may fail, fall back to fresh login
            r.success()
            if not self._fresh_login():
                return False
        else:
            r.failure(f"renew status {r.status_code}")
            return False
        if cart_id:
            r = self.client.post(f"/v2/carts/{cart_id}/recover", json={},
                                 headers=self._auth_headers(),
                                 allow_redirects=False, catch_response=True,
                                 name="POST /v2/carts/{id}/recover")
            if r.status_code in (200, 201):
                self._update_csrf(r)
                self._update_etag(r)
                r.success()
            else:
                r.failure(f"recover status {r.status_code}")
                return False
        return True

    def do_patch_cart(self, cart_id, quantity):
        payload = {"quantity": int(quantity)}
        r = self._patch(cart_id, payload)
        retried_412 = False
        retried_401 = False
        while True:
            if r.status_code == 412 and not retried_412:
                retried_412 = True
                r.success()
                self._refresh_etag(cart_id)
                r = self._patch(cart_id, payload)
                continue
            if r.status_code == 401 and not retried_401:
                retried_401 = True
                err = self._error(r)
                if err == "denied":
                    r.failure("PATCH denied (401)")
                    return False
                if self._recover_401(cart_id):
                    r.success()
                    r = self._patch(cart_id, payload)
                    continue
                r.failure("PATCH 401 and recovery failed")
                return False
            break
        if r.status_code in (200, 201):
            self._update_csrf(r)
            self._update_etag(r)
            r.success()
            return True
        r.failure(f"PATCH status {r.status_code}: {r.text[:200]}")
        return False

    def do_order(self, cart_id):
        def _post():
            return self.client.post("/v2/orders", json={"cart_id": cart_id},
                                    headers=self._auth_headers(if_match=True,
                                                               idempotency_key=cart_id),
                                    allow_redirects=False, catch_response=True,
                                    name="POST /v2/orders")
        r = _post()
        retried_412 = False
        retried_401 = False
        while True:
            if r.status_code == 412 and not retried_412:
                retried_412 = True
                r.success()
                self._refresh_etag(cart_id)
                r = _post()
                continue
            if r.status_code == 401 and not retried_401:
                retried_401 = True
                err = self._error(r)
                if err == "denied":
                    r.failure("orders denied (401)")
                    return False
                if self._recover_401(cart_id):
                    r.success()
                    r = _post()
                    continue
                r.failure("orders 401 and recovery failed")
                return False
            break
        if r.status_code == 201:
            data = self._json(r)
            if data.get("accepted") is True:
                self._update_csrf(r)
                r.success()
                return True
            r.failure("orders accepted is not true")
            return False
        if r.status_code == 200:
            r.failure(f"orders business failure: {r.text[:200]}")
            return False
        r.failure(f"orders status {r.status_code}: {r.text[:200]}")
        return False


