import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ModelSimulation extends Simulation {

    private static final AtomicInteger userCounter = new AtomicInteger(0);

    private final HttpProtocolBuilder httpProtocol = http
            .baseUrl(System.getenv("BASE_URL"))
            .disableFollowRedirect()
            .acceptHeader("application/json, text/html, */*")
            .contentTypeHeader("application/json");

    private final ChainBuilder journey =
            exec(session -> session.set("username", "bench-" + ((userCounter.getAndIncrement() % 16) + 1)))
            .exec(http("login-form")
                    .get("/v2/login-form")
                    .check(status().is(200))
                    .check(regex("<input(?=[^>]*\\bname=[\"']csrf[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>").saveAs("formCsrf")))
            .exec(http("login")
                    .post("/v2/login")
                    .header("X-CSRF-Token", "#{formCsrf}")
                    .body(StringBody(session -> {
                        String fc = session.contains("formCsrf") ? session.getString("formCsrf") : "";
                        return "{\"username\":\"" + session.getString("username")
                                + "\",\"password\":\"bench\",\"csrf\":\"" + fc + "\"}";
                    }))
                    .check(status().in(200, 302))
                    .check(header("Location").optional().saveAs("location"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(session -> {
                if (session.contains("csrf")) {
                    return session;
                }
                String fc = session.contains("formCsrf") ? session.getString("formCsrf") : "";
                return session.set("csrf", fc);
            })
            .doIf(session -> session.contains("location")).then(
                    exec(http("challenge-form")
                            .get("#{location}")
                            .check(status().in(200, 302))
                            .check(regex("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("grant"))
                            .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf"))
                            .check(regex("<form[^>]*action=[\"']([^\"']+)[\"'][^>]*>").optional().saveAs("challengeAction"))
                            .check(regex("<input(?=[^>]*\\bname=[\"']challenge[\"'])(?=[^>]*\\bvalue=[\"']([^\"']+)[\"'])[^>]*>").optional().saveAs("challengeValue")))
                    .doIf(session -> session.contains("challengeAction")).then(
                            exec(http("challenge-submit")
                                    .post("#{challengeAction}")
                                    .header("X-CSRF-Token", "#{csrf}")
                                    .body(StringBody(session -> {
                                        String cv = session.contains("challengeValue") ? session.getString("challengeValue") : "";
                                        return "{\"challenge\":\"" + cv + "\"}";
                                    }))
                                    .check(status().in(200, 302))
                                    .check(header("Location").optional().saveAs("challengeLocation"))
                                    .check(regex("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("grant"))
                                    .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").optional().saveAs("csrf")))
                            .doIf(session -> session.contains("challengeLocation")).then(
                                    exec(http("challenge-result")
                                            .get("#{challengeLocation}")
                                            .check(status().is(200))
                                            .check(regex("\"grant_id\"\\s*:\\s*\"([^\"]+)\"").saveAs("grant"))
                                            .check(regex("\"csrf\"\\s*:\\s*\"([^\"]+)\"").saveAs("csrf"))))))
            .exec(http("catalog")
                    .get("/v2/catalog")
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf"))
                    .check(jsonPath("$.data.products[*].id").findAll().saveAs("productIds"))
                    .check(jsonPath("$.data.products[*].variants[0].id").findAll().saveAs("variantIds"))
                    .check(jsonPath("$.data.products[*].variants[0].in_stock").findAll().saveAs("inStockFlags")))
            .exec(session -> {
                List<Object> ids = session.contains("productIds") ? session.getList("productIds") : Collections.emptyList();
                List<Object> vids = session.contains("variantIds") ? session.getList("variantIds") : Collections.emptyList();
                List<Object> flags = session.contains("inStockFlags") ? session.getList("inStockFlags") : Collections.emptyList();
                int idx = -1;
                for (int i = 0; i < flags.size(); i++) {
                    Object f = flags.get(i);
                    boolean inStock = (f instanceof Boolean) ? (Boolean) f : Boolean.parseBoolean(String.valueOf(f));
                    if (inStock) {
                        idx = i;
                        break;
                    }
                }
                if (idx < 0) {
                    idx = 0;
                }
                String product = (idx < ids.size()) ? String.valueOf(ids.get(idx)) : "";
                String variant = (idx < vids.size()) ? String.valueOf(vids.get(idx)) : "";
                return session.set("product", product).set("variant", variant);
            })
            .exec(http("create-cart")
                    .post("/v2/carts")
                    .header("X-CSRF-Token", "#{csrf}")
                    .body(StringBody(session -> {
                        StringBuilder sb = new StringBuilder();
                        sb.append("{\"product_id\":\"").append(session.getString("product"))
                          .append("\",\"variant_id\":\"").append(session.getString("variant")).append("\"");
                        if (session.contains("grant")) {
                            String g = session.getString("grant");
                            if (g != null && !g.isEmpty() && !"MISSING".equals(g)) {
                                sb.append(",\"grant_id\":\"").append(g).append("\"");
                            }
                        }
                        sb.append("}");
                        return sb.toString();
                    }))
                    .check(status().is(201))
                    .check(header("ETag").saveAs("etag"))
                    .check(jsonPath("$.id").saveAs("cart"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")))
            .exec(http("create-order")
                    .post("/v2/orders")
                    .header("X-CSRF-Token", "#{csrf}")
                    .header("If-Match", "#{etag}")
                    .header("Idempotency-Key", "#{cart}")
                    .body(StringBody(session -> {
                        String cart = session.contains("cart") ? session.getString("cart") : "";
                        return "{\"cart_id\":\"" + cart + "\"}";
                    }))
                    .check(status().is(201))
                    .check(regex("\"accepted\"\\s*:\\s*true"))
                    .check(jsonPath("$.csrf").optional().saveAs("csrf")));

    public ModelSimulation() {
        setUp(
                scenario("journey")
                        .exec(journey)
                        .injectOpen(constantUsersPerSec(2).during(Duration.ofSeconds(40)))
                        .protocols(httpProtocol)
        );
    }
}

