import http from 'k6/http';
import { check } from 'k6';
import { Counter } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const checkoutStarts = new Counter('checkout_starts');

export const options = {
  scenarios: {
    journey: {
      executor: 'constant-arrival-rate',
      rate: 2,
      timeUnit: '1s',
      duration: '40s',
      preAllocatedVUs: 4,
      maxVUs: 4,
    },
  },
};

function getHeader(res, name) {
  const headers = (res && res.headers) || {};
  const lower = String(name).toLowerCase();
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === lower) return headers[key];
  }
  return null;
}

function resolveUrl(u) {
  if (!u) return BASE;
  if (/^https?:\/\//i.test(u)) return u;
  return BASE + (u.charAt(0) === '/' ? u : '/' + u);
}

function jsonBody(res) {
  try { return res.json(); } catch (e) { return null; }
}

function parseAttrs(tag) {
  const attrs = {};
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'>]+))/g;
  let m;
  while ((m = re.exec(tag)) !== null) {
    const v = m[3] !== undefined ? m[3] : (m[4] !== undefined ? m[4] : m[5]);
    attrs[m[1].toLowerCase()] = v;
  }
  return attrs;
}

function extractInputValue(html, name) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const attrs = parseAttrs(tag);
    if (attrs.name === name && attrs.value !== undefined) return attrs.value;
  }
  return null;
}

function extractFormAction(html) {
  const tags = String(html || '').match(/<form\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const attrs = parseAttrs(tag);
    if (attrs.action) return attrs.action;
  }
  const m = String(html || '').match(/action\s*=\s*["']([^"']+)["']/i);
  return m ? m[1] : null;
}

function baseHeaders(state) {
  const h = { 'Content-Type': 'application/json' };
  if (state.csrf) h['X-CSRF-Token'] = state.csrf;
  return h;
}

function recoverCart(state) {
  if (!state.cartId) return;
  const res = http.post(`${BASE}/v2/carts/${state.cartId}/recover`, '{}', { headers: baseHeaders(state), redirects: 0 });
  const j = jsonBody(res);
  if (j && j.csrf) state.csrf = j.csrf;
  const et = getHeader(res, 'ETag');
  if (et) state.etag = et;
}

function handleChallengeResponse(state, res) {
  const j = jsonBody(res);
  if (j && (j.grant_id || j.csrf)) {
    if (j.csrf) state.csrf = j.csrf;
    if (j.grant_id) state.grantId = j.grant_id;
    return;
  }
  const body = res && res.body ? res.body : '';
  const action = extractFormAction(body);
  const challenge = extractInputValue(body, 'challenge');
  if (!action || !challenge) return;
  const postRes = http.post(resolveUrl(action), JSON.stringify({ challenge }), { headers: baseHeaders(state), redirects: 0 });
  if (postRes.status === 302) {
    const loc = getHeader(postRes, 'Location');
    if (loc) {
      const grantRes = http.get(resolveUrl(loc), { headers: baseHeaders(state), redirects: 0 });
      const gj = jsonBody(grantRes);
      if (gj) {
        if (gj.csrf) state.csrf = gj.csrf;
        if (gj.grant_id) state.grantId = gj.grant_id;
      }
    }
  }
}

function doLogin(state) {
  const formRes = http.get(`${BASE}/v2/login-form`, { headers: { 'Content-Type': 'application/json' }, redirects: 0 });
  const formCsrf = extractInputValue(formRes.body, 'csrf');
  check(formRes, { 'login-form ok': (r) => r.status === 200 });
  check(formRes, { 'login-form csrf present': () => !!formCsrf });
  if (formCsrf) state.csrf = formCsrf;

  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: state.username,
    password: 'bench',
    csrf: formCsrf,
  }), { headers: baseHeaders(state), redirects: 0 });

  if (loginRes.status === 302) {
    const loc = getHeader(loginRes, 'Location');
    check(loginRes, { 'login redirect location': () => !!loc });
    if (loc) {
      const challengeRes = http.get(resolveUrl(loc), { headers: baseHeaders(state), redirects: 0 });
      handleChallengeResponse(state, challengeRes);
    }
    return;
  }
  const j = jsonBody(loginRes);
  check(loginRes, { 'login ok': (r) => r.status === 200 && !!j && !!j.csrf });
  if (j && j.csrf) state.csrf = j.csrf;
}

function withRecovery(state, fn) {
  let res = fn();
  if (res.status !== 401) return res;
  const j = jsonBody(res);
  const err = j && j.error;
  if (err === 'expired') {
    const renew = http.post(`${BASE}/v2/session/renew`, '{}', { headers: baseHeaders(state), redirects: 0 });
    const rj = jsonBody(renew);
    if (renew.status === 200 && rj) {
      if (rj.csrf) state.csrf = rj.csrf;
      recoverCart(state);
      res = fn();
    }
  } else if (err === 'session') {
    doLogin(state);
    recoverCart(state);
    res = fn();
  }
  return res;
}

export default function () {
  const state = {
    username: `bench-${((__VU - 1) % 16) + 1}`,
    csrf: null,
    etag: null,
    cartId: null,
    grantId: null,
  };

  doLogin(state);

  const catRes = withRecovery(state, () => http.get(`${BASE}/v2/catalog`, { headers: baseHeaders(state), redirects: 0 }));
  const cat = jsonBody(catRes);
  if (cat && cat.csrf) state.csrf = cat.csrf;
  let productId = null;
  let variantId = null;
  const products = cat && cat.data && Array.isArray(cat.data.products) ? cat.data.products : [];
  for (const p of products) {
    const variants = Array.isArray(p.variants) ? p.variants : [];
    const v = variants.find((vv) => vv && vv.in_stock);
    if (v) { productId = p.id; variantId = v.id; break; }
  }
  check(catRes, { 'catalog ok': (r) => r.status === 200 });
  check(catRes, { 'catalog selection': () => !!productId && !!variantId });

  const cartRes = withRecovery(state, () => {
    const body = { product_id: productId, variant_id: variantId };
    if (state.grantId) body.grant_id = state.grantId;
    return http.post(`${BASE}/v2/carts`, JSON.stringify(body), { headers: baseHeaders(state), redirects: 0 });
  });
  const cartJson = jsonBody(cartRes);
  if (cartJson && cartJson.csrf) state.csrf = cartJson.csrf;
  if (cartJson && cartJson.id) state.cartId = cartJson.id;
  const cartEtag = getHeader(cartRes, 'ETag');
  if (cartEtag) state.etag = cartEtag;
  check(cartRes, { 'cart created': (r) => r.status === 201 && !!(jsonBody(r) || {}).id });

  const orderRes = withRecovery(state, () => {
    const h = baseHeaders(state);
    if (state.etag) h['If-Match'] = state.etag;
    h['Idempotency-Key'] = state.cartId || `order-${__VU}-${Date.now()}`;
    return http.post(`${BASE}/v2/orders`, JSON.stringify({ cart_id: state.cartId }), { headers: h, redirects: 0 });
  });
  const orderJson = jsonBody(orderRes);
  if (orderJson && orderJson.csrf) state.csrf = orderJson.csrf;
  const accepted = orderRes.status === 201 && !!orderJson && orderJson.accepted === true;
  if (accepted) checkoutStarts.add(1);
  check(orderRes, { 'order accepted': () => accepted });
}

import os
import re
import time
import itertools

from locust import HttpUser, task, LoadTestShape, StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
TARGET_RATE = 2.0
MAX_VUS = 4
PERIOD = MAX_VUS / TARGET_RATE
TEST_DURATION = 40.0

_account_counter = itertools.count(1)


def _input_value(html, name):
    if not html:
        return None
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"\bname\s*=\s*[\"']" + re.escape(name) + r"[\"']", tag, re.IGNORECASE):
            vm = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


def _form_action(html):
    if not html:
        return None
    m = re.search(r"<form\b[^>]*?\baction\s*=\s*[\"']([^\"']+)[\"']", html, re.IGNORECASE | re.DOTALL)
    return m.group(1) if m else None


class JourneyUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        idx = next(_account_counter)
        self.account = "bench-%d" % (((idx - 1) % 16) + 1)
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self.deadline = time.time() + TEST_DURATION
        time.sleep(((idx - 1) % MAX_VUS) * (PERIOD / MAX_VUS))

    def _headers(self, idem=None, if_match=None):
        h = {"Content-Type": "application/json"}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if if_match:
            h["If-Match"] = if_match
        if idem:
            h["Idempotency-Key"] = idem
        return h

    @task
    def journey(self):
        if time.time() >= self.deadline:
            raise StopUser()
        start = time.time()
        try:
            self._run_journey()
        except Exception:
            pass
        elapsed = time.time() - start
        remaining = PERIOD - elapsed
        if remaining > 0:
            time.sleep(remaining)

    def _run_journey(self):
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None

        # 1. login form
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            form_csrf = _input_value(r.text, "csrf")
            if not form_csrf:
                r.failure("login-form missing csrf")
                return False
            self.csrf = form_csrf
            r.success()

        # 2. login
        payload = {"username": self.account, "password": "bench", "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, name="/v2/login",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location") or r.headers.get("location")
                if not loc:
                    r.failure("login 302 without Location")
                    return False
                r.success()
                if not self._follow_login_redirect(loc):
                    return False
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login bad json")
                    return False
                if not isinstance(data, dict) or not data.get("csrf"):
                    r.failure("login missing csrf")
                    return False
                self.csrf = data["csrf"]
                r.success()
            else:
                r.failure("login status %s" % r.status_code)
                return False

        # 3. catalog
        with self.client.get("/v2/catalog", name="/v2/catalog",
                             headers=self._headers(), catch_response=True) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return False
            try:
                data = r.json()
                products = data["data"]["products"]
                chosen = None
                for p in products:
                    variants = p.get("variants") or []
                    if variants and variants[0].get("in_stock"):
                        chosen = (p.get("id"), variants[0].get("id"))
                        break
                if not chosen or not chosen[0] or not chosen[1]:
                    r.failure("catalog no in-stock product")
                    return False
                self.product_id, self.variant_id = chosen
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                r.success()
            except Exception:
                r.failure("catalog parse error")
                return False

        # 4. create cart
        body = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id
        with self.client.post("/v2/carts", json=body, name="/v2/carts",
                              headers=self._headers(), catch_response=True) as r:
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return False
            try:
                data = r.json()
                cart_id = data.get("id")
                if not cart_id:
                    r.failure("cart missing id")
                    return False
                self.cart_id = cart_id
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                etag = r.headers.get("ETag") or r.headers.get("etag")
                if etag:
                    self.etag = etag
                r.success()
            except Exception:
                r.failure("cart parse error")
                return False

        # 5. checkout
        headers = self._headers(idem=self.cart_id, if_match=self.etag)
        with self.client.post("/v2/orders", json={"cart_id": self.cart_id},
                              name="/v2/orders", headers=headers,
                              catch_response=True) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order bad json")
                    return False
                if isinstance(data, dict) and data.get("accepted") is True:
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    r.success()
                    return True
                r.failure("order not accepted")
                return False
            r.failure("order status %s" % r.status_code)
            return False

    def _follow_login_redirect(self, loc):
        with self.client.get(loc, name="login-redirect", headers=self._headers(),
                             catch_response=True, allow_redirects=False) as r:
            body = r.text
            grant = None
            try:
                data = r.json()
                if isinstance(data, dict):
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    grant = data.get("grant_id")
            except Exception:
                data = None
            if grant:
                self.grant_id = grant
                r.success()
                return True
            action = _form_action(body)
            challenge = _input_value(body, "challenge")
            if not action or not challenge:
                r.failure("challenge form parse failed")
                return False
            r.success()
        with self.client.post(action, json={"challenge": challenge},
                              name="challenge", headers=self._headers(),
                              catch_response=True, allow_redirects=False) as r:
            loc2 = r.headers.get("Location") or r.headers.get("location")
            if r.status_code in (301, 302, 303, 307, 308) and loc2:
                r.success()
            else:
                r.failure("challenge status %s" % r.status_code)
                return False
        with self.client.get(loc2, name="challenge-grant", headers=self._headers(),
                             catch_response=True, allow_redirects=False) as r:
            try:
                data = r.json()
            except Exception:
                r.failure("grant bad json")
                return False
            if not isinstance(data, dict):
                r.failure("grant bad json")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            if data.get("grant_id"):
                self.grant_id = data["grant_id"]
            r.success()
            return True


class JourneyShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() < TEST_DURATION:
            return (MAX_VUS, MAX_VUS)
        return None

