import os
import re
import time
import itertools

from locust import HttpUser, task, LoadTestShape
from locust.exception import StopUser

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
TARGET_RATE = 2.0
MAX_VUS = 4
PERIOD = MAX_VUS / TARGET_RATE
TEST_DURATION = 40.0

_account_counter = itertools.count(1)


def _input_value(html, name):
    if not html:
        return None
    for m in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE):
        tag = m.group(0)
        if re.search(r"\bname\s*=\s*[\"']" + re.escape(name) + r"[\"']", tag, re.IGNORECASE):
            vm = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", tag, re.IGNORECASE)
            if vm:
                return vm.group(1)
    return None


def _form_action(html):
    if not html:
        return None
    m = re.search(r"<form\b[^>]*?\baction\s*=\s*[\"']([^\"']+)[\"']", html, re.IGNORECASE | re.DOTALL)
    return m.group(1) if m else None


class JourneyUser(HttpUser):
    host = BASE_URL

    def on_start(self):
        idx = next(_account_counter)
        self.account = "bench-%d" % (((idx - 1) % 16) + 1)
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None
        self.deadline = time.time() + TEST_DURATION
        time.sleep(((idx - 1) % MAX_VUS) * (PERIOD / MAX_VUS))

    def _headers(self, idem=None, if_match=None):
        h = {"Content-Type": "application/json"}
        if self.csrf:
            h["X-CSRF-Token"] = self.csrf
        if if_match:
            h["If-Match"] = if_match
        if idem:
            h["Idempotency-Key"] = idem
        return h

    @task
    def journey(self):
        if time.time() >= self.deadline:
            raise StopUser()
        start = time.time()
        try:
            self._run_journey()
        except Exception:
            pass
        elapsed = time.time() - start
        remaining = PERIOD - elapsed
        if remaining > 0:
            time.sleep(remaining)

    def _run_journey(self):
        self.csrf = None
        self.etag = None
        self.cart_id = None
        self.grant_id = None
        self.product_id = None
        self.variant_id = None

        # 1. login form
        with self.client.get("/v2/login-form", name="/v2/login-form",
                             catch_response=True, allow_redirects=False) as r:
            if r.status_code != 200:
                r.failure("login-form status %s" % r.status_code)
                return False
            form_csrf = _input_value(r.text, "csrf")
            if not form_csrf:
                r.failure("login-form missing csrf")
                return False
            self.csrf = form_csrf
            r.success()

        # 2. login
        payload = {"username": self.account, "password": "bench", "csrf": self.csrf}
        with self.client.post("/v2/login", json=payload, name="/v2/login",
                              headers=self._headers(), catch_response=True,
                              allow_redirects=False) as r:
            if r.status_code == 302:
                loc = r.headers.get("Location") or r.headers.get("location")
                if not loc:
                    r.failure("login 302 without Location")
                    return False
                r.success()
                if not self._follow_login_redirect(loc):
                    return False
            elif r.status_code == 200:
                try:
                    data = r.json()
                except Exception:
                    r.failure("login bad json")
                    return False
                if not isinstance(data, dict) or not data.get("csrf"):
                    r.failure("login missing csrf")
                    return False
                self.csrf = data["csrf"]
                r.success()
            else:
                r.failure("login status %s" % r.status_code)
                return False

        # 3. catalog
        with self.client.get("/v2/catalog", name="/v2/catalog",
                             headers=self._headers(), catch_response=True) as r:
            if r.status_code != 200:
                r.failure("catalog status %s" % r.status_code)
                return False
            try:
                data = r.json()
                products = data["data"]["products"]
                chosen = None
                for p in products:
                    variants = p.get("variants") or []
                    if variants and variants[0].get("in_stock"):
                        chosen = (p.get("id"), variants[0].get("id"))
                        break
                if not chosen or not chosen[0] or not chosen[1]:
                    r.failure("catalog no in-stock product")
                    return False
                self.product_id, self.variant_id = chosen
                if isinstance(data, dict) and data.get("csrf"):
                    self.csrf = data["csrf"]
                r.success()
            except Exception:
                r.failure("catalog parse error")
                return False

        # 4. create cart
        body = {"product_id": self.product_id, "variant_id": self.variant_id}
        if self.grant_id:
            body["grant_id"] = self.grant_id
        with self.client.post("/v2/carts", json=body, name="/v2/carts",
                              headers=self._headers(), catch_response=True) as r:
            if r.status_code != 201:
                r.failure("cart status %s" % r.status_code)
                return False
            try:
                data = r.json()
                cart_id = data.get("id")
                if not cart_id:
                    r.failure("cart missing id")
                    return False
                self.cart_id = cart_id
                if data.get("csrf"):
                    self.csrf = data["csrf"]
                etag = r.headers.get("ETag") or r.headers.get("etag")
                if etag:
                    self.etag = etag
                r.success()
            except Exception:
                r.failure("cart parse error")
                return False

        # 5. checkout
        headers = self._headers(idem=self.cart_id, if_match=self.etag)
        with self.client.post("/v2/orders", json={"cart_id": self.cart_id},
                              name="/v2/orders", headers=headers,
                              catch_response=True) as r:
            if r.status_code == 201:
                try:
                    data = r.json()
                except Exception:
                    r.failure("order bad json")
                    return False
                if isinstance(data, dict) and data.get("accepted") is True:
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    r.success()
                    return True
                r.failure("order not accepted")
                return False
            r.failure("order status %s" % r.status_code)
            return False

    def _follow_login_redirect(self, loc):
        with self.client.get(loc, name="login-redirect", headers=self._headers(),
                             catch_response=True, allow_redirects=False) as r:
            body = r.text
            grant = None
            try:
                data = r.json()
                if isinstance(data, dict):
                    if data.get("csrf"):
                        self.csrf = data["csrf"]
                    grant = data.get("grant_id")
            except Exception:
                data = None
            if grant:
                self.grant_id = grant
                r.success()
                return True
            action = _form_action(body)
            challenge = _input_value(body, "challenge")
            if not action or not challenge:
                r.failure("challenge form parse failed")
                return False
            r.success()
        with self.client.post(action, json={"challenge": challenge},
                              name="challenge", headers=self._headers(),
                              catch_response=True, allow_redirects=False) as r:
            loc2 = r.headers.get("Location") or r.headers.get("location")
            if r.status_code in (301, 302, 303, 307, 308) and loc2:
                r.success()
            else:
                r.failure("challenge status %s" % r.status_code)
                return False
        with self.client.get(loc2, name="challenge-grant", headers=self._headers(),
                             catch_response=True, allow_redirects=False) as r:
            try:
                data = r.json()
            except Exception:
                r.failure("grant bad json")
                return False
            if not isinstance(data, dict):
                r.failure("grant bad json")
                return False
            if data.get("csrf"):
                self.csrf = data["csrf"]
            if data.get("grant_id"):
                self.grant_id = data["grant_id"]
            r.success()
            return True


class JourneyShape(LoadTestShape):
    def tick(self):
        if self.get_run_time() < TEST_DURATION:
            return (MAX_VUS, MAX_VUS)
        return None

