import io.gatling.javaapi.core.*;
import io.gatling.javaapi.http.*;
import static io.gatling.javaapi.core.CoreDsl.*;
import static io.gatling.javaapi.http.HttpDsl.*;

import java.util.Iterator;
import java.util.Map;
import java.util.stream.Stream;

public class ModelSimulation extends Simulation {

    private static final String BASE_URL = System.getenv().getOrDefault("BASE_URL", "http://127.0.0.1:8000");

    private static final Iterator<Map<String, Object>> USER_FEEDER =
        Stream.iterate(1, i -> i + 1)
              .map(i -> Map.<String, Object>of("username", "bench-" + i))
              .iterator();

    private final HttpProtocolBuilder httpProtocol = http
        .baseUrl(BASE_URL)
        .disableFollowRedirect()
        .acceptHeader("application/json")
        .contentTypeHeader("application/json");

    private final ScenarioBuilder scn = scenario("ModelSimulation")
        .feed(USER_FEEDER)
        .repeat(2).on(
            exec(session -> session
                .remove("form")
                .remove("csrf")
                .remove("location")
                .remove("grant")
                .remove("product")
                .remove("variant")
                .remove("cart")
                .remove("etag"))
            .exec(http("GET /v2/login-form")
                .get("/v2/login-form")
                .check(status().is(200))
                .check(css("input[name=csrf]", "value").find().saveAs("form")))
            .exec(http("POST /v2/login")
                .post("/v2/login")
                .header("X-CSRF-Token", "#{form}")
                .body(StringBody("{\"username\":\"#{username}\",\"password\":\"bench\",\"csrf\":\"#{form}\"}"))
                .check(status().in(200, 302))
                .check(regex("\"csrf\"\\s*:").exists())
                .check(jsonPath("$.csrf").find().optional().saveAs("csrf"))
                .check(header("Location").optional().saveAs("location")))
            .doIf(session -> session.contains("location")).then(
                exec(http("GET login redirect")
                    .get(session -> {
                        String loc = session.getString("location");
                        return loc.startsWith(BASE_URL) ? loc.substring(BASE_URL.length()) : loc;
                    })
                    .check(status().is(200))
                    .check(jsonPath("$.csrf").find().optional().saveAs("csrf"))
                    .check(jsonPath("$.grant_id").find().optional().saveAs("grant"))))
            .exec(http("GET /v2/catalog")
                .get("/v2/catalog")
                .check(status().is(200))
                .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].id").find().saveAs("product"))
                .check(jsonPath("$.data.products[?(@.variants[0].in_stock == true)].variants[0].id").find().saveAs("variant")))
            .exec(http("POST /v2/carts")
                .post("/v2/carts")
                .header("X-CSRF-Token", "#{csrf}")
                .body(StringBody(session -> {
                    StringBuilder sb = new StringBuilder();
                    sb.append("{\"product_id\":\"").append(session.getString("product"))
                      .append("\",\"variant_id\":\"").append(session.getString("variant")).append("\"");
                    if (session.contains("grant")) {
                        sb.append(",\"grant_id\":\"").append(session.getString("grant")).append("\"");
                    }
                    sb.append("}");
                    return sb.toString();
                }))
                .check(status().is(201))
                .check(regex("\"id\"\\s*:\\s*\"cart-").exists())
                .check(jsonPath("$.id").find().saveAs("cart"))
                .check(jsonPath("$.csrf").find().optional().saveAs("csrf"))
                .check(header("ETag").saveAs("etag")))
            .exec(http("POST /v2/orders")
                .post("/v2/orders")
                .header("X-CSRF-Token", "#{csrf}")
                .header("Idempotency-Key", "#{cart}")
                .header("If-Match", "#{etag}")
                .body(StringBody("{\"cart_id\":\"#{cart}\"}"))
                .check(status().in(200, 201))
                .check(regex("\"accepted\"\\s*:\\s*true").exists())
                .check(jsonPath("$.csrf").find().optional().saveAs("csrf")))
        );

    public ModelSimulation() {
        setUp(scn.injectOpen(atOnceUsers(2)))
            .protocols(httpProtocol)
            .assertions(
                global().failedRequests().count().is(0),
                details("POST /v2/orders").failedRequests().count().is(0)
            );
    }
}
