import os
import re
import itertools

from locust import HttpUser, LoadTestShape, task, constant
from locust.exception import StopUser

BASE_URL = os.environ["BASE_URL"]
USERS = 2
ITERATIONS = 2

_state = {"completed": 0}
_user_counter = itertools.count(1)


def _extract_input_value(html, name):
    if not html:
        return None
    for match in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE | re.DOTALL):
        tag = match.group(0)
        name_match = re.search(r"\bname\s*=\s*[\"']([^\"']*)[\"']", tag, re.IGNORECASE)
        if not name_match or name_match.group(1) != name:
            continue
        value_match = re.search(r"\bvalue\s*=\s*[\"']([^\"']*)[\"']", tag, re.IGNORECASE)
        if value_match:
            return value_match.group(1)
    return None


def _json(response):
    try:
        return response.json()
    except Exception:
        return None


def _pick_product(response):
    data = _json(response)
    if not isinstance(data, dict):
        return None
    products = (data.get("data") or {}).get("products") or []
    for product in products:
        if not isinstance(product, dict):
            continue
        for variant in product.get("variants") or []:
            if isinstance(variant, dict) and variant.get("in_stock"):
                return product.get("id"), variant.get("id")
    return None


def _check_catalog(response):
    if response.status_code != 200:
        return False, "catalog: status %s" % response.status_code
    if _pick_product(response) is None:
        return False, "catalog: no in-stock product"
    return True, ""


def _check_cart(response):
    data = _json(response)
    cart_id = data.get("id") if isinstance(data, dict) else None
    if response.status_code == 201 and cart_id and str(cart_id).startswith("cart-"):
        return True, ""
    return False, "cart: creation failed (status %s)" % response.status_code


def _check_order(response):
    data = _json(response)
    if not isinstance(data, dict):
        return False, "order: unparseable response (status %s)" % response.status_code
    if response.status_code == 201 and data.get("accepted") is True:
        return True, ""
    if response.status_code == 200 and data.get("accepted") is False:
        return False, "order declined: accepted=false"
    return False, "order: status %s accepted=%s" % (response.status_code, data.get("accepted"))


class ShopUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        number = next(_user_counter)
        self.username = "bench-%d" % (((number - 1) % 16) + 1)
        self.iterations_done = 0

    @task
    def journey(self):
        try:
            self._journey()
        finally:
            self.iterations_done += 1
            _state["completed"] += 1
        if self.iterations_done >= ITERATIONS:
            raise StopUser()

    def _journey(self):
        csrf, grant_id = self._fresh_login()
        if csrf is None:
            return
        response, csrf = self._call("GET", "/v2/catalog", "GET /v2/catalog",
                                    csrf, None, _check_catalog)
        pick = _pick_product(response)
        if not pick:
            return
        product_id, variant_id = pick
        payload = {"product_id": product_id, "variant_id": variant_id}
        if grant_id:
            payload["grant_id"] = grant_id
        response, csrf = self._call("POST", "/v2/carts", "POST /v2/carts",
                                    csrf, None, _check_cart, json=payload)
        data = _json(response)
        cart_id = data.get("id") if isinstance(data, dict) else None
        if not cart_id:
            return
        fresh_csrf = data.get("csrf") if isinstance(data, dict) else None
        if fresh_csrf:
            csrf = fresh_csrf
        etag = response.headers.get("ETag") or response.headers.get("etag")
        headers = {"Idempotency-Key": str(cart_id)}
        if etag:
            headers["If-Match"] = etag
        self._call("POST", "/v2/orders", "POST /v2/orders",
                   csrf, cart_id, _check_order,
                   json={"cart_id": cart_id}, headers=headers)

    def _fresh_login(self):
        with self.client.get("/v2/login-form", name="GET /v2/login-form",
                             catch_response=True) as response:
            form_csrf = _extract_input_value(response.text, "csrf")
            if response.status_code == 200 and form_csrf:
                response.success()
            else:
                response.failure("login-form: missing csrf input")
                return None, None
        with self.client.post("/v2/login",
                              json={"username": self.username,
                                    "password": "bench",
                                    "csrf": form_csrf},
                              headers={"X-CSRF-Token": form_csrf},
                              allow_redirects=False,
                              name="POST /v2/login",
                              catch_response=True) as response:
            if response.status_code == 200:
                data = _json(response)
                csrf = data.get("csrf") if isinstance(data, dict) else None
                if csrf:
                    response.success()
                    return csrf, None
                response.failure("login: missing csrf in response")
                return None, None
            if response.status_code == 302:
                location = response.headers.get("Location") or response.headers.get("location")
                if not location:
                    response.failure("login: 302 without Location")
                    return None, None
                response.success()
                return self._follow_challenge(location, form_csrf)
            response.failure("login: unexpected status %s" % response.status_code)
            return None, None

    def _follow_challenge(self, location, csrf):
        with self.client.get(location, name="GET challenge-form",
                             allow_redirects=False,
                             catch_response=True) as response:
            action = None
            challenge = None
            if response.text:
                match = re.search(r"<form\b[^>]*\baction\s*=\s*[\"']([^\"']+)[\"']",
                                  response.text, re.IGNORECASE | re.DOTALL)
                if match:
                    action = match.group(1)
                challenge = _extract_input_value(response.text, "challenge")
            if response.status_code == 200 and action and challenge:
                response.success()
            else:
                data = _json(response)
                if response.status_code == 200 and isinstance(data, dict) and data.get("grant_id"):
                    response.success()
                    return data.get("csrf") or csrf, data.get("grant_id")
                response.failure("challenge-form: unrecognized response")
                return None, None
        with self.client.post(action,
                              json={"challenge": challenge},
                              headers={"X-CSRF-Token": csrf},
                              allow_redirects=False,
                              name="POST challenge",
                              catch_response=True) as response:
            location2 = response.headers.get("Location") or response.headers.get("location")
            if response.status_code == 302 and location2:
                response.success()
            else:
                response.failure("challenge: unexpected status %s" % response.status_code)
                return None, None
        with self.client.get(location2, name="GET challenge-result",
                             catch_response=True) as response:
            data = _json(response)
            if response.status_code == 200 and isinstance(data, dict) and data.get("grant_id"):
                response.success()
                return data.get("csrf") or csrf, data.get("grant_id")
            response.failure("challenge-result: missing grant_id")
            return None, None

    def _recover(self, csrf, cart_id, error):
        renewed = None
        with self.client.post("/v2/session/renew", json={},
                              headers={"X-CSRF-Token": csrf},
                              name="POST /v2/session/renew",
                              catch_response=True) as response:
            if response.status_code == 200:
                data = _json(response)
                renewed = (data.get("csrf") if isinstance(data, dict) else None) or csrf
                response.success()
            elif error == "session":
                response.success()
            else:
                response.failure("session renew failed: %s" % response.status_code)
        if renewed is None:
            if error == "session":
                renewed, _ = self._fresh_login()
                if renewed is None:
                    return None
            else:
                return None
        if cart_id:
            with self.client.post("/v2/carts/%s/recover" % cart_id, json={},
                                  headers={"X-CSRF-Token": renewed},
                                  name="POST /v2/carts/{id}/recover",
                                  catch_response=True) as response:
                if response.status_code == 200:
                    data = _json(response)
                    renewed = (data.get("csrf") if isinstance(data, dict) else None) or renewed
                    response.success()
                else:
                    response.failure("cart recover failed: %s" % response.status_code)
                    return None
        return renewed

    def _call(self, method, url, name, csrf, cart_id, check, **kwargs):
        headers = dict(kwargs.pop("headers", {}))
        headers["X-CSRF-Token"] = csrf
        response = self.client.request(method, url, headers=headers, name=name,
                                       catch_response=True, **kwargs)
        if response.status_code == 401:
            data = _json(response)
            error = data.get("error") if isinstance(data, dict) else None
            if error == "denied":
                response.failure("401 denied")
                return response, csrf
            new_csrf = self._recover(csrf, cart_id, error)
            if new_csrf is None:
                response.failure("401 %s: recovery failed" % error)
                return response, csrf
            response.success()
            headers["X-CSRF-Token"] = new_csrf
            response = self.client.request(method, url, headers=headers, name=name,
                                           catch_response=True, **kwargs)
            csrf = new_csrf
        ok, message = check(response)
        if ok:
            response.success()
        else:
            response.failure(message)
        return response, csrf


class ShopShape(LoadTestShape):
    def tick(self):
        if _state["completed"] >= USERS * ITERATIONS:
            return None
        if self.get_run_time() > 300:
            return None
        return {"user_count": USERS, "spawn_rate": USERS}
