import http from 'k6/http';
import { check } from 'k6';

const base = __ENV.BASE_URL;
const rows = [
  { username: 'bench-1', password: 'bench' },
  { username: 'bench-2', password: 'bench' },
  { username: 'bench-3', password: 'bench' },
  { username: 'bench-4', password: 'bench' },
