  { username: 'bench-14', password: 'bench' },
  { username: 'bench-15', password: 'bench' },
  { username: 'bench-16', password: 'bench' }
];

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: 2,
      iterations: 2,
      maxDuration: '30s'
    }
  },
  thresholds: {
    checks: ['rate==1']
  }
};

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function url(path) {
  return /^https?:\/\//i.test(path) ? path : base + path;
}

function attrValue(tag, name) {
  const re = new RegExp('(?:^|\\s)' + name + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i');
  const m = String(tag || '').match(re);
  return m ? (m[1] || m[2] || m[3] || '') : '';
}

function inputValue(html, name) {
  const tags = String(html || '').match(/<input\b[^>]*>/gi) || [];
  let fallback = '';
  for (const tag of tags) {
    if (attrValue(tag, 'name') !== name) continue;
    if (/\bdisabled\b/i.test(tag)) continue;
    const value = attrValue(tag, 'value');
    if (!value) continue;
    const type = (attrValue(tag, 'type') || 'hidden').toLowerCase();
    if (type === 'hidden') return value;
    if (!fallback) fallback = value;
  }
  return fallback;
}

function formAction(html) {
  const forms = String(html || '').match(/<form\b[^>]*>/gi) || [];
  for (const tag of forms) {
    const action = attrValue(tag, 'action');
    if (action) return action;
  }
  return '';
}

function etagOf(r) {
  return r.headers.ETag || r.headers.Etag || r.headers.etag || '';
}

function raw(state, path, method, data, extra) {
  method = method || 'GET';
  data = data === undefined ? null : data;
  extra = extra || {};
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'X-CSRF-Token': state.csrf
  }, extra);
  const r = http.request(method, url(path), data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '3s'
  });
  const b = body(r);
  if (b.csrf) state.csrf = b.csrf;
  return r;
}

function solveChallenge(state, r) {
  const action = formAction(r.body);
  const challenge = inputValue(r.body, 'challenge');
  if (!action) return r;
  let rr = raw(state, action, 'POST', { challenge: challenge });
  if (rr.status === 302) {
    const loc = rr.headers.Location || rr.headers.location;
    if (loc) rr = raw(state, loc);
  }
  const b = body(rr);
  if (b.grant_id) state.grant = b.grant_id;
  return rr;
}

function login(state) {
  let r = raw(state, '/v2/login-form');
  const token = inputValue(r.body, 'csrf');
  state.csrf = token;
  const row = rows[(__VU - 1) % rows.length];
  r = raw(state, '/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
  });
  let ok = false;
  if (r.status === 302) {
    const loc = r.headers.Location || r.headers.location;
    if (loc) {
      r = raw(state, loc);
      if (/<form\b/i.test(r.body) && /challenge/i.test(r.body)) {
        r = solveChallenge(state, r);
      } else {
        const b = body(r);
        if (b.grant_id) state.grant = b.grant_id;
      }
      ok = r.status === 200;
    }
  } else if (r.status === 200) {
    ok = true;
  }
  check(r, { login: function () { return ok && !!state.csrf; } });
}

function request(state, path, method, data, extra) {
  let r = raw(state, path, method, data, extra);
  const b = body(r);
  if (r.status === 401 && (b.error === 'expired' || b.error === 'session')) {
    const renewed = raw(state, '/v2/session/renew', 'POST', {});
    if (renewed.status !== 200) login(state);
    if (state.cart) raw(state, '/v2/carts/' + state.cart + '/recover', 'POST', {});
    r = raw(state, path, method, data, extra);
  }
  return r;
}

function clearCookies() {
  const jar = http.cookieJar();
  const urls = [base, base + '/', base + '/v2', base + '/v2/'];
  for (const u of urls) {
    try { jar.clear(u); } catch (_) {}
  }
}

function flow() {
  const state = { csrf: '', cart: '', grant: '', etag: '' };
  clearCookies();
  login(state);

  let r = request(state, '/v2/catalog');
  check(r, { catalog: function () { return r.status === 200; } });
  const b = body(r);
  const products = b.data && b.data.products ? b.data.products : [];
  let product = null;
  let variant = null;
  for (const p of products) {
    const variants = p.variants || [];
    for (const v of variants) {
      if (v.in_stock) {
        product = p;
        variant = v;
        break;
      }
    }
    if (product) break;
  }
  if (!product) {
    check(false, { 'eligible product': function () { return false; } });
    return;
  }

  const cartPayload = { product_id: product.id, variant_id: variant.id };
  if (state.grant) cartPayload.grant_id = state.grant;
  r = request(state, '/v2/carts', 'POST', cartPayload);
  const cb = body(r);
  state.cart = cb.id || '';
  state.etag = etagOf(r);
  check(r, { cart: function () { return r.status === 201 && !!state.cart; } });
  if (!state.cart) return;

  const orderPayload = { cart_id: state.cart };
  const orderHeaders = { 'Idempotency-Key': state.cart };
  if (state.etag) orderHeaders['If-Match'] = state.etag;
  r = request(state, '/v2/orders', 'POST', orderPayload, orderHeaders);
  check(r, { accepted: function () { return r.status === 201 && body(r).accepted === true; } });
}

export default function () {
  flow();
}

