            .exec(doIf(session -> isRecoverable401(session, "cartStatus", "cartError")).then(
                renewAndRecover()
                    .exec(http("cart retry").post("/v2/carts")
                        .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody(session -> cartBody(session)))
                        .check(status().is(201), jsonPath("$.id").saveAs("cart"),
                            header("ETag").optional().saveAs("etag"),
                            jsonPath("$.csrf").optional().saveAs("csrf")))));

        if (MODE.equals("expiry") || MODE.equals("denial") || MODE.equals("ownership")) {
            chain = chain.exec(doIf(session -> MODE.equals("ownership") && session.userId() == 1)
                    .then(pause(Duration.ofMillis(300))))
                .exec(doIf(session -> MODE.equals("ownership") && session.userId() != 1)
                    .then(pause(Duration.ofMillis(500))))
                .exec(http("expiry probe").get("/v2/carts/#{cart}")
                    .header("X-CSRF-Token", "#{csrf}")
                    .check(status().in(200, 401), status().saveAs("probeStatus"),
                        jsonPath("$.error").optional().saveAs("probeError"),
                        header("ETag").optional().saveAs("etag"),
                        jsonPath("$.csrf").optional().saveAs("csrf")))
                .exec(doIf(session -> isRecoverable401(session, "probeStatus", "probeError")).then(
                    renewAndRecover()
                        .exec(http("expiry probe retry").get("/v2/carts/#{cart}")
                            .header("X-CSRF-Token", "#{csrf}")
                            .check(status().is(200), header("ETag").optional().saveAs("etag"),
