            # Expected expiry/revocation: renew (or re-login), recover the cart,
            # then retry only the interrupted operation once.
            self.recover(body.get('error'))
            if headers and 'If-Match' in headers and self.etag:
                headers = dict(headers)
                headers['If-Match'] = self.etag
            response, body = self.raw(path, method, data, headers, name, _retry=True)
        return response, body

