                        .header("Content-Type", "application/json").header("X-CSRF-Token", "#{csrf}")
                        .body(StringBody("{}"))
                        .check(status().in(200, 401), status().saveAs("renewStatus"),
                            jsonPath("$.csrf").optional().saveAs("csrf")))
                    .exec(doIf(session -> MODE.equals("ownership")
