import time

from gevent import sleep
from gevent.event import Event
from gevent.lock import Semaphore
from locust import HttpUser, LoadTestShape, task
from locust.exception import StopUser

CFG = {'users': 2, 'iterations': 2, 'mode': 'errors'}
MODE = CFG.get('mode', 'flow')
ROWS = [{"username": "bench-1", "password": "bench", "quantity": 2}, {"username": "bench-2", "password": "bench", "quantity": 3}, {"username": "bench-3", "password": "bench", "quantity": 4}, {"username": "bench-4", "password": "bench", "quantity": 5}, {"username": "bench-5", "password": "bench", "quantity": 6}, {"username": "bench-6", "password": "bench", "quantity": 7}, {"username": "bench-7", "password": "bench", "quantity": 8}, {"username": "bench-8", "password": "bench", "quantity": 9}, {"username": "bench-9", "password": "bench", "quantity": 10}, {"username": "bench-10", "password": "bench", "quantity": 11}, {"username": "bench-11", "password": "bench", "quantity": 12}, {"username": "bench-12", "password": "bench", "quantity": 13}, {"username": "bench-13", "password": "bench", "quantity": 14}, {"username": "bench-14", "password": "bench", "quantity": 15}, {"username": "bench-15", "password": "bench", "quantity": 16}, {"username": "bench-16", "password": "bench", "quantity": 17}]
DURATION = CFG.get('duration', 35)
POOLS = CFG.get('pools') or [{'name': 'work', 'path': CFG.get('path', '/v2/work'),
                              'rate': CFG.get('rate', 5),
                              'operation': CFG.get('operation', 'work')}]
if isinstance(POOLS, dict):
    POOLS = [dict(pool, name=name) for name, pool in POOLS.items()]

_USER_COUNTER = itertools.count(1)
_COUNTER_LOCK = Semaphore()

class ArrivalPlan:
    def __init__(self):
        self.started = None
        self.counts = {pool['name']: 0 for pool in POOLS}
        self.lock = Semaphore()

    def slot(self, pool, number):
        rates = CFG.get('rates', [pool['rate']]) if not CFG.get('pools') else [pool['rate']]
        spans = [15, 10, 10] if len(rates) > 1 else [DURATION]
        offset = 0
        for rate, span in zip(rates, spans):
            count = int(rate * span)
            if number < count:
                return offset + number / rate + (
                    number * 0.002 if pool.get('operation') == 'journey' else 0)
            number -= count
            offset += span
        return None

    def next(self):
        with self.lock:
            if self.started is None:
                self.started = time.monotonic()
            scheduled = [(self.slot(pool, self.counts[pool['name']]), pool)
                         for pool in POOLS]
            scheduled = [(slot, pool) for slot, pool in scheduled if slot is not None]
            if not scheduled:
                return None
            slot, pool = min(scheduled, key=lambda item: item[0])
            self.counts[pool['name']] += 1
            deadline = self.started + slot
        sleep(max(0, deadline - time.monotonic()))
        return pool

ARRIVALS = ArrivalPlan()
OWNER = {'logins': 0, 'ready': Event(), 'lock': Semaphore()}

class MatrixUser(HttpUser):
    host = os.environ.get('BASE_URL', 'http://127.0.0.1:8000')
    wait_time = lambda self: 0

    def on_start(self):
        worker_id = getattr(self, '_p95_worker_id', None)
        number = None
        if worker_id is not None:
            try:
                number = int(str(worker_id).rsplit('-', 1)[1])
            except (ValueError, IndexError):
                number = None
        if number is None:
            with _COUNTER_LOCK:
                number = next(_USER_COUNTER)
        self.row = ROWS[(number - 1) % len(ROWS)]
        self.username = ('bench' if MODE == 'ownership' else
                         self.row['username'] if MODE in ('data', 'partition') else
                         'bench-' + str((number - 1) % 16 + 1))
        self.password = self.row.get('password', 'bench')
        self.csrf = ''
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.iteration = 0

    def raw(self, path, method='GET', data=None, headers=None, name=None):
        request_headers = {'Content-Type': 'application/json'}
        if self.csrf:
            request_headers['X-CSRF-Token'] = self.csrf
        request_headers.update(headers or {})
        with self.client.request(method, path, json=data, headers=request_headers,
                                 name=name, catch_response=True, allow_redirects=False,
                                 timeout=3) as response:
            try:
                body = response.json()
            except ValueError:
                body = {}
            allowed = response.status_code < 400
            if response.status_code == 401 and body.get('error') == 'expired':
                # Expected session expiry: caller renews and retries once.
                allowed = True
            elif response.status_code == 429:
                # Scheduled rate limit: caller honors Retry-After and retries.
                allowed = True
            # Anything else >= 400 (including unexpected 500) stays a failure.
            if (path.startswith('/v2/jobs/') and response.status_code < 400
                    and body.get('status') == 'failed'
                    or path.split('?', 1)[0] == '/v2/orders' and method == 'POST'
                    and response.status_code < 400
                    and body.get('accepted') is not True):
                allowed = False
            if name == 'checkout' and response.elapsed.total_seconds() * 1000 >= 250:
                allowed = False
            if allowed:
                response.success()
            else:
                response.failure('request assertion failed')
                self.environment.process_exit_code = 99
            if body.get('csrf'):
                self.csrf = body['csrf']
            return response, body

    def login(self):
        self.csrf = ''
        form, _ = self.raw('/v2/login-form')
        token = re.search(
            r'<input(?=[^>]*\bname=["\']csrf["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
            form.text, re.IGNORECASE)
        if not token:
            self.environment.process_exit_code = 99
            return
        response, body = self.raw('/v2/login', 'POST',
                                  {'username': self.username, 'password': self.password,
                                   'csrf': token.group(1)})
        if response.status_code == 302:
            location = response.headers.get('Location')
            if location:
                _, body = self.request(location)
        self.grant = body.get('grant_id', '')

    def recover(self):
        renewed, _ = self.raw('/v2/session/renew', 'POST', {})
        if renewed.status_code != 200:
            self.login()
        if self.cart:
            response, _ = self.raw('/v2/carts/' + self.cart + '/recover', 'POST', {})
            self.etag = response.headers.get('ETag', self.etag)

    def request(self, path, method='GET', data=None, headers=None, name=None):
        response, body = None, {}
        for _ in range(2):
            response, body = self.raw(path, method, data, headers, name)
            if response.status_code == 401 and body.get('error') in ('expired', 'session'):
                self.recover()
                continue
            return response, body
        return response, body

    def work(self, path='/v2/work'):
        if not self.csrf:
            self.login()
        for _ in range(5):
            response, _ = self.request(path, 'POST', {})
            if response.status_code != 429:
                return
            try:
                delay = float(response.headers.get('Retry-After', '1'))
            except (TypeError, ValueError):
                delay = 1.0
            sleep(delay + 0.01)

    def flow(self):
        self.client.cookies.clear()
        self.cart = ''
        self.etag = ''
        self.grant = ''
        self.login()
        if MODE == 'ownership':
            with OWNER['lock']:
                OWNER['logins'] += 1
                if OWNER['logins'] >= CFG.get('users', 2):
                    OWNER['ready'].set()
            if not OWNER['ready'].wait(5):
                self.environment.process_exit_code = 99
                return
            if getattr(self, '_p95_worker_id', 'user-1') != 'user-1':
                sleep(0.5)
        if MODE == 'challenge':
            page, _ = self.request('/v2/challenge-form')
            action = re.search(
                r'<form\b[^>]*\baction=["\']([^"\']+)["\']', page.text, re.IGNORECASE)
            challenge = re.search(
                r'<input(?=[^>]*\bname=["\']challenge["\'])(?=[^>]*\bvalue=["\']([^"\']+)["\'])[^>]*>',
                page.text, re.IGNORECASE)
            if not action or not challenge:
                self.environment.process_exit_code = 99
                return
            response, _ = self.request(action.group(1), 'POST',
                                       {'challenge': challenge.group(1)})
            location = response.headers.get('Location')
            if location:
                _, body = self.request(location)
                self.grant = body.get('grant_id', '')
        page = '/v2/catalog/page' if MODE == 'pagination' else '/v2/catalog'
        product = None
        for _ in range(3):
            _, body = self.request(page)
            products = body.get('data', {}).get('products', [])
            product = next((item for item in products
                            if any(variant.get('in_stock') for variant in item.get('variants', []))),
                           None)
            if product:
                break
            page = body.get('next')
            if not page:
                break
        if not product:
            self.environment.process_exit_code = 99
            return
        variant = next(item for item in product['variants'] if item.get('in_stock'))
        response, body = self.request('/v2/carts', 'POST',
            {'product_id': product['id'], 'variant_id': variant['id'], 'grant_id': self.grant})
        self.cart = body.get('id', '')
        self.etag = response.headers.get('ETag', '')
        if not self.cart:
            return
        if MODE in ('etag', 'data'):
            quantity = self.row.get('quantity', 2) if MODE == 'data' else CFG.get('quantity', 2)
            headers = {'If-Match': self.etag}
            response, _ = self.request('/v2/carts/' + self.cart, 'PATCH',
                                       {'quantity': quantity}, headers)
            if response.status_code == 412:
                response, _ = self.request('/v2/carts/' + self.cart)
                self.etag = response.headers.get('ETag', self.etag)
                response, _ = self.request('/v2/carts/' + self.cart, 'PATCH',
                    {'quantity': quantity}, {'If-Match': self.etag})
            self.etag = response.headers.get('ETag', self.etag)
        reservation = None
        if MODE == 'reservation':
            _, body = self.request('/v2/reservations', 'POST', {'cart_id': self.cart})
            status_url = body.get('status_url')
            for _ in range(5):
                sleep(0.05)
                _, state = self.request(status_url)
                if state.get('status') == 'ready':
                    reservation = state.get('reservation_id')
                    break
                if state.get('status') == 'failed':
                    return
            if not reservation:
                return
        body = {'cart_id': self.cart}
        if reservation:
            body['reservation_id'] = reservation
        self.request('/v2/orders', 'POST', body,
                     {'Idempotency-Key': self.cart, 'If-Match': self.etag},
                     'checkout' if MODE == 'threshold' else None)

    @task
    def run_scenario(self):
        if CFG.get('workload'):
            pool = ARRIVALS.next()
            if pool is None:
                raise StopUser()
            if pool.get('operation') == 'journey':
                self.flow()
            else:
                self.work(pool['path'])
            return
        if MODE == 'errors':
            self.login()
            for _ in range(4):
                self.work()
        else:
            self.flow()
        self.iteration += 1
        if self.iteration >= CFG.get('iterations', 2):
            raise StopUser()

class MatrixShape(LoadTestShape):
    def __init__(self):
        super().__init__()
        self.first_tick = True

    def tick(self):
        users = (CFG.get('max_vus', 64 if CFG.get('capacity') or CFG.get('pools') else 32)
                 if CFG.get('workload') else CFG.get('users', 2))
        elapsed = self.get_run_time()
        if CFG.get('workload'):
            return None if elapsed >= DURATION + 5 else (users, max(1, users))
        if self.first_tick:
            self.first_tick = False
            return users, max(1, users)
        return None if self.runner.user_count == 0 else (users, max(1, users))

import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    work: {
      executor: 'per-vu-iterations',
      vus: 5,
      iterations: 1,
      maxDuration: '45s',
    },
  },
};

function safeJson(res) {
  try { return res.json(); } catch (e) { return {}; }
}

function parseAttrs(tag) {
  const attrs = {};
  const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/g;
  let m;
  while ((m = re.exec(tag))) {
    const name = m[1].toLowerCase();
    const value = m[3] !== undefined ? m[3] : (m[4] !== undefined ? m[4] : m[5]);
    attrs[name] = value;
  }
  return attrs;
}

function extractCsrf(html) {
  const re = /<input\b[^>]*>/gi;
  let m;
  while ((m = re.exec(html))) {
    if (/\bdisabled\b/i.test(m[0])) continue;
    const attrs = parseAttrs(m[0]);
    if ((attrs.name || '').toLowerCase() === 'csrf' && attrs.value !== undefined) {
      return attrs.value;
    }
  }
  const m2 = html.match(/name=["']?csrf["']?[^>]*value=["']?([^"'\s>]+)/i) || html.match(/value=["']?([^"'\s>]+)["']?[^>]*name=["']?csrf/i);
  return m2 ? m2[1] : null;
}

function resolveUrl(loc) {
  if (!loc) return BASE_URL;
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.charAt(0) === '/') return BASE_URL + loc;
  return BASE_URL + '/' + loc;
}

function login(username) {
  const form = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0, tags: { name: 'login-form' } });
  const csrf = extractCsrf(form.body || '');
  const res = http.post(`${BASE_URL}/v2/login`, JSON.stringify({ username, password: 'bench', csrf }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
    tags: { name: 'login' },
  });
  let finalRes = res;
  if (res.status === 302) {
    const loc = res.headers['Location'] || res.headers['location'];
    if (loc) finalRes = http.get(resolveUrl(loc), { redirects: 0, tags: { name: 'login-redirect' } });
  }
  const body = safeJson(finalRes);
  return { username, csrf: body.csrf || csrf };
}

function freshLogin(session) {
  const s = login(session.username);
  session.csrf = s.csrf;
  return true;
}

function renew(session) {
  const res = http.post(`${BASE_URL}/v2/session/renew`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf },
    tags: { name: 'renew' },
  });
  const body = safeJson(res);
  if (body && body.csrf) session.csrf = body.csrf;
  return res.status < 400;
}

function isUnexpectedWorkFailure(res, body) {
  if (res.status === 429) return false;
  if (res.status === 401) {
    const err = body && body.error;
    if (err === 'expired') return false;
    return true;
  }
  if (res.status >= 400) return true;
  if (!body || body.ok !== true) return true;
  return false;
}

function rawWork(session) {
  const res = http.post(`${BASE_URL}/v2/work`, '{}', {
    headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': session.csrf },
    tags: { name: 'work' },
  });
  const body = safeJson(res);
  if (body && body.csrf) session.csrf = body.csrf;
  businessFailure.add(isUnexpectedWorkFailure(res, body) ? 1 : 0);
  check(res, { 'work ok': (r) => r.status === 200 && safeJson(r).ok === true });
  return res;
}

function doWork(session) {
  let res = rawWork(session);
  if (res.status === 401) {
    const body = safeJson(res);
    const err = body && body.error;
    if (err === 'expired' || err === 'session') {
      let ok = renew(session);
      if (!ok) ok = freshLogin(session);
      if (ok) res = rawWork(session);
    } else {
      check(res, { 'work authorized': () => false });
    }
  }
  let retries = 0;
  while (res.status === 429 && retries < 4) {
    const ra = parseInt(res.headers['Retry-After'] || res.headers['retry-after'] || '1', 10);
    sleep(Math.max(1, isNaN(ra) ? 1 : ra));
    res = rawWork(session);
    retries += 1;
  }
  return res;
}

export default function () {
  const session = login(`bench-${__VU}`);
  const t0 = Date.now();
  const end = t0 + 35000;
  let next = t0;
  while (Date.now() < end) {
    doWork(session);
    next += 1000;
    const delay = next - Date.now();
    if (delay > 0) sleep(delay / 1000);
  }
}

import os
import re
import time

from locust import HttpUser, LoadTestShape, StopUser, constant, task

BASE_URL = os.environ["BASE_URL"].rstrip("/")
PASSWORD = "bench"
ACCOUNTS = ["bench-%d" % i for i in range(1, 17)]

READY = 0
SCHEDULE_START = None
COMPLETED = 0
SHAPE_START = time.time()
ACCOUNT_INDEX = 0


def _extract_csrf(html):
    if not html:
        return None
    for match in re.finditer(r"<input\b[^>]*>", html, re.IGNORECASE | re.DOTALL):
        tag = match.group(0)
        if not re.search(r"\bname\s*=\s*(?:\"csrf\"|'csrf'|csrf)(?=[\s>/])", tag, re.IGNORECASE):
            continue
        value = re.search(r"\bvalue\s*=\s*(?:\"([^\"]*)\"|'([^']*)'|([^\s>]+))", tag, re.IGNORECASE | re.DOTALL)
        if value:
            for group in value.groups():
                if group:
                    return group
    return None


def _error_code(response):
    try:
        data = response.json()
    except Exception:
        return None
    if not isinstance(data, dict):
        return None
    error = data.get("error")
    if isinstance(error, str):
        return error
    if isinstance(error, dict):
        code = error.get("code") or error.get("error")
        if isinstance(code, str):
            return code
    code = data.get("code")
    if isinstance(code, str):
        return code
    return None


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    @task
    def _idle(self):
        self.wait(1)

    def on_start(self):
        global READY, SCHEDULE_START, COMPLETED, ACCOUNT_INDEX
        index = ACCOUNT_INDEX % len(ACCOUNTS)
        ACCOUNT_INDEX += 1
        self.username = ACCOUNTS[index]
        self.csrf = None
        try:
            try:
                logged_in = self._login()
            except Exception:
                logged_in = False
            READY += 1
            if logged_in:
                while SCHEDULE_START is None:
                    if READY >= 5 and SCHEDULE_START is None:
                        SCHEDULE_START = time.time() + 0.5
                    self.wait(0.05)
                start = SCHEDULE_START
                for offset in range(35):
                    slot = start + offset
                    delay = slot - time.time()
                    if delay > 0:
                        self.wait(delay)
                    try:
                        self._do_work()
                    except Exception:
                        pass
        finally:
            COMPLETED += 1
        raise StopUser()

    def _headers(self):
        if self.csrf:
            return {"X-CSRF-Token": self.csrf}
        return {}

    def _csrf_from_response(self, response):
        try:
            data = response.json()
        except Exception:
            return None
        if isinstance(data, dict):
            csrf = data.get("csrf")
            if isinstance(csrf, str) and csrf:
                return csrf
        return None

    def _login(self):
        for _ in range(3):
            with self.client.get("/v2/login-form", name="/v2/login-form", catch_response=True) as response:
                if response.status_code != 200:
                    response.failure("login-form status %s" % response.status_code)
                    continue
                csrf = _extract_csrf(response.text)
                if not csrf:
                    response.failure("login-form missing csrf")
                    continue
            payload = {"username": self.username, "password": PASSWORD, "csrf": csrf}
            with self.client.post(
                "/v2/login",
                json=payload,
                headers={"X-CSRF-Token": csrf},
                allow_redirects=False,
                name="/v2/login",
                catch_response=True,
            ) as response:
                new_csrf = None
                if response.status_code in (301, 302, 303, 307, 308):
                    location = response.headers.get("Location")
                    if not location:
                        response.failure("login redirect missing location")
                        continue
                    with self.client.get(
                        location,
                        allow_redirects=False,
                        name="/v2/login-redirect",
                        catch_response=True,
                    ) as redirect_response:
                        if redirect_response.status_code >= 400:
                            redirect_response.failure("login redirect status %s" % redirect_response.status_code)
                            continue
                        new_csrf = self._csrf_from_response(redirect_response)
                elif response.status_code == 200:
                    new_csrf = self._csrf_from_response(response)
                else:
                    response.failure("login status %s" % response.status_code)
                    continue
                if new_csrf:
                    self.csrf = new_csrf
                    return True
                response.failure("login missing csrf")
        return False

    def _renew(self):
        with self.client.post(
            "/v2/session/renew",
            json={},
            headers=self._headers(),
            name="/v2/session/renew",
            catch_response=True,
        ) as response:
            if response.status_code == 200:
                csrf = self._csrf_from_response(response)
                if csrf:
                    self.csrf = csrf
                return True
            if response.status_code >= 500:
                response.failure("renew server error %s" % response.status_code)
            return False

    def _recover(self, kind):
        if kind == "expired":
            if self._renew():
                return True
            return self._login()
        if kind == "session":
            return self._login()
        return False

    def _post_work_once(self):
        with self.client.post(
            "/v2/work",
            json={},
            headers=self._headers(),
            name="/v2/work",
            catch_response=True,
        ) as response:
            if response.status_code == 200:
                try:
                    data = response.json()
                except Exception:
                    response.failure("work invalid json")
                    return "error"
                if isinstance(data, dict):
                    csrf = data.get("csrf")
                    if isinstance(csrf, str) and csrf:
                        self.csrf = csrf
                    if data.get("ok") is True:
                        return "ok"
                response.failure("work response not ok")
                return "error"
            if response.status_code == 401:
                error = _error_code(response)
                if error == "expired":
                    return "expired"
                if error == "session":
                    return "session"
                response.failure("work unauthorized")
                return "denied"
            if response.status_code == 429:
                return "429"
            if response.status_code >= 500:
                response.failure("work server error %s" % response.status_code)
                return "error"
            response.failure("work unexpected status %s" % response.status_code)
            return "error"

    def _do_work(self):
        result = self._post_work_once()
        if result == "ok":
            return True
        if result == "429":
            for _ in range(4):
                self.wait(1)
                result = self._post_work_once()
                if result == "ok":
                    return True
                if result == "429":
                    continue
                return False
            return False
        if result in ("expired", "session"):
            if self._recover(result):
                result = self._post_work_once()
                return result == "ok"
            return False
        return False


class WorkShape(LoadTestShape):
    def tick(self):
        if COMPLETED >= 5:
            return None
        if time.time() - SHAPE_START > 60:
            return None
        return (max(0, 5 - COMPLETED), 5)

