          exec(workAttempt))
      .doIf(session -> "401".equals(attr(session, "workStatus")) && "denied".equals(attr(session, "workError"))).then(
          exec(session -> session.markAsFailed()))
      .asLongAs(session -> "429".equals(attr(session, "workStatus")) && session.getInt("workRetry") < 4).on(
          exec(session -> session.set("workRetry", session.getInt("workRetry") + 1)),
          pause(Duration.ofSeconds(1)),
          exec(workAttempt));

  private final ScenarioBuilder scn = scenario("work-pool")
