import os
import re
import time
import itertools

from locust import HttpUser, task, LoadTestShape, constant

BASE_URL = os.environ.get("BASE_URL", "http://127.0.0.1:8000")
TARGET_RATE = 8.0
INTERVAL = 1.0 / TARGET_RATE
NUM_USERS = 16
SCORE_END_OFFSET = 35.0
DRAIN = 3.0

_state = {"t0": None}
_counter = itertools.count(1)


class _Pacer:
    """Global pacer: spaces operation starts at least INTERVAL apart."""

    def __init__(self):
        self.next_slot = None

    def acquire(self):
        now = time.time()
        if self.next_slot is None:
            self.next_slot = now
        slot = self.next_slot
        if slot < now:
            # Never burst to catch up; drop missed slots.
            slot = now
        self.next_slot = slot + INTERVAL
        delay = slot - now
        if delay > 0:
            time.sleep(delay)


_pacer = _Pacer()


def extract_csrf(html):
    if not html:
        return None
    for m in re.finditer(r'<input\b[^>]*>', html, re.I | re.S):
        tag = m.group(0)
        if not re.search(r'name\s*=\s*(?:"csrf"|\'csrf\'|csrf(?=[\s>]))', tag, re.I):
            continue
        vm = re.search(r'value\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))', tag, re.I)
        if vm:
            for g in vm.groups():
                if g is not None:
                    return g
    return None


class WorkUser(HttpUser):
    host = BASE_URL
    wait_time = constant(0)

    def on_start(self):
        idx = next(_counter)
        self.username = "bench-%d" % (((idx - 1) % 16) + 1)
        self.csrf = None
        self.login()

    def login(self):
        try:
            r = self.client.get("/v2/login-form", allow_redirects=False,
                                name="/v2/login-form")
        except Exception:
            return False
        csrf = extract_csrf(r.text)
        if not csrf:
            return False
        r = self.client.post(
            "/v2/login",
            json={"username": self.username, "password": "bench", "csrf": csrf},
            allow_redirects=False,
            catch_response=True,
            name="/v2/login",
        )
        final = r
        if r.status_code == 302:
            loc = r.headers.get("Location")
            if loc:
                final = self.client.get(loc, allow_redirects=False,
                                        name="login-redirect")
        new_csrf = None
        for resp in (final, r):
            try:
                data = resp.json()
            except Exception:
                continue
            if isinstance(data, dict) and data.get("csrf"):
                new_csrf = data["csrf"]
                break
        if r.status_code in (200, 302) and new_csrf:
            self.csrf = new_csrf
            r.success()
            return True
        r.failure("login failed (status %s)" % r.status_code)
        return False

    def renew(self):
        r = self.client.post(
            "/v2/session/renew",
            json={},
            headers={"X-CSRF-Token": self.csrf or ""},
            allow_redirects=False,
            catch_response=True,
            name="/v2/session/renew",
        )
        if r.status_code == 200:
            try:
                data = r.json()
            except Exception:
                r.failure("renew: bad json")
                return False
            if isinstance(data, dict) and data.get("csrf"):
                self.csrf = data["csrf"]
            r.success()
            return True
        r.failure("renew: status %s" % r.status_code)
        return False

    @task
    def work(self):
        t0 = _state["t0"]
        if t0 is not None and time.time() >= t0 + SCORE_END_OFFSET:
            # Score window over; idle until the shape drains and stops.
            time.sleep(0.5)
            return
        _pacer.acquire()
        self.do_work()

    def do_work(self, attempt=0, retried=False):
        headers = {"X-CSRF-Token": self.csrf or ""}
        with self.client.post("/v2/work", json={}, headers=headers,
                              allow_redirects=False,
                              catch_response=True,
                              name="/v2/work") as resp:
            sc = resp.status_code
            if sc == 200:
                ok = False
                try:
                    ok = resp.json().get("ok") is True
                except Exception:
                    ok = False
                if ok:
                    resp.success()
                    if _state["t0"] is None:
                        _state["t0"] = time.time()
                else:
                    resp.failure("work: ok != true")
                return
            if sc == 429:
                # Scheduled 429: expected, not a failure. Honor Retry-After.
                resp.success()
                if attempt < 4:
                    try:
                        delay = float(resp.headers.get("Retry-After", "1"))
                    except Exception:
                        delay = 1.0
                    time.sleep(max(delay, 1.0))
                    self.do_work(attempt + 1, retried)
                return
            if sc == 401:
                err = None
                try:
                    err = resp.json().get("error")
                except Exception:
                    err = None
                if err == "expired":
                    resp.success()
                    if not retried and self.renew():
                        self.do_work(attempt, True)
                    return
                if err == "session":
                    resp.success()
                    if not retried and self.login():
                        self.do_work(attempt, True)
                    return
                resp.failure("work: denied (%s)" % err)
                return
            resp.failure("work: unexpected status %s" % sc)


class WorkShape(LoadTestShape):
    def tick(self):
        t = self.get_run_time()
        t0 = _state["t0"]
        if t0 is not None:
            if time.time() >= t0 + SCORE_END_OFFSET + DRAIN:
                return None
            return (NUM_USERS, NUM_USERS)
        if t > 12:
            return None
        return (NUM_USERS, NUM_USERS)
